function shortcutsStripType(value)
{
	var possibleType = value.slice(-3);
	if(shortcutsTypes2[possibleType] == null)
		return [value, '^ '];
	return [value.slice(0, -3), shortcutsTypes2[possibleType]]; 
}

BookbinderGrid();

clearAll();
function clearAll() {
  for (var i = setTimeout(function() {}, 0); i > 0; i--) {
    clearInterval(i);
    clearTimeout(i);
  }
}

function AutoATsave()
{
	settings.settings["FastShortcutAutoAT"] = {};
	settings.store(user_fast_shortcut_settings_AutoAT, "FastShortcutAutoAT");
}

CheckAutoAT()
function CheckAutoAT()
{
	if(user_fast_shortcut_settings.MemUeberwachung && user_fast_shortcut_settings_AutoAT.Runde != 0)
	{
		ToolingMenuUpdate(true);
		ToolingMenuUpdateSzenaMenu(false);
		ToolingMenuUpdateSzenaStoppen(false);
		ToolingMenuUpdateSzenaStarten(false);
		ToolingMenuUpdateMainMenu(false);
		setTimeout(function() {
			showGameAlert(getText('CheckRound', 'SemiAutoATMenuLang'));
		}, 130000);
		setTimeout(function() {
			var event = {
							target: {
							name: 'Auto AT Start - Nach Client Restart'
						}
			};
			shortcutsAutoFunc(event);
		}, 3 * 60 * 1000);
	}
}

function LoadBuffModalFastExt(){
	try{
		(function() {
			var originalMenuBuffsHandler = menuBuffsHandler;

			menuBuffsHandler = function(event) {
				originalMenuBuffsHandler(event);

				setTimeout(function() {
					var $modal = $('#buffModal');
					if (!$modal.length || !$modal.is(':visible') || $modal.find('.buff-search').length > 0) return;

					var $input = $('<input>')
						.addClass('form-control buff-search')
						.attr('placeholder', 'Suchen...')
						.css('margin-bottom', '10px');

					$('#buffModalData').prepend($input);

					$input.on('input', function() {
						var term = $(this).val().toLowerCase();
						$('#buffModalData .row').each(function() {
							var rowText = $(this).text().toLowerCase();
							$(this).toggle(rowText.indexOf(term) >= 0);
						});
					});
					//debug("Buff Methode");
				}, 500);
			};
		})();
	}catch(e){}
}

