function updateProgress(progress, remainingTime) {
	try
	{
		progress = Math.max(0, Math.min(progress, 1));
		var percentage = Math.round(progress * 100);

		var totalBlocks = 10;
		var filledBlocks = Math.floor(progress * totalBlocks);
		var emptyBlocks = totalBlocks - filledBlocks;

		var bar = '';
		for (var i = 0; i < filledBlocks; i++) {
			bar += '█';
		}
		for (var i = 0; i < emptyBlocks; i++) {
			bar += '░';
		}
		
		menu.nativeMenu.getItemByName("existingProgress").label =
			getText('Loading', 'SemiAutoATMenuLang') + ' ' + percentage + ' % | ' + remainingTime + 's | ' + bar;
	}
	catch(e){game.showAlert(e);}
}


function VorlagenUeberwachungAutoStart() {
    if (!game.gi.isOnHomzone()) {
        game.showAlert(getText('not_home'));
        return;
    }
	if (!user_fast_shortcut_settings.PersonalTesting && parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenÜberwachungSelector, 10) !== 0 && parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenÜberwachungSelector2, 10) !== 0 && parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenÜberwachungSelector3, 10) !== 0)
	{
		ToolingMenuUpdateAllMainMenu(false);
	}

    const actions = [
        {
            delay: 15000,
            action: function() {
				LoadBuffModalFastExt();
				startTimeWatcher();
                if (user_fast_shortcut_settings.AutoTrade) {
                    _usAcceptTradesRunning = false;
                    _usAcceptTrades_Start();
                    game.showAlert(getText('TradeMessage', 'SemiAutoATMenuLang'));
                }
            }
        },
        {
            delay: 20000,
            action: function() {
                BuiBuffsUeberwachung(false);
                game.showAlert(getText('BuildingBuffActive', 'SemiAutoATMenuLang'));
            }
        },
        {
            delay: 105000,
            action: function() {
                BuiProdUeberwachung(false);
                game.showAlert(getText('BuildingProd', 'SemiAutoATMenuLang'));
            }
        },
        {
            delay: 140000,
            action: function() {
                try {
                    CHAOS_GLOBALFLASH().gui.mStarMenu.Show();
                    CHAOS_GLOBALFLASH().gui.mStarMenu.Hide();
                } catch (e) {}
                setTimeout(function() {
                    AllUeberwachung(false);
                    game.showAlert(getText('ShortcutMonitoring', 'SemiAutoATMenuLang'));
                }, 5000);
            }
        }
    ];

    actions.forEach(function(item) {
        setTimeout(item.action, item.delay);
    });

    const progressQueue = [];
    for (var i = 1; i <= 100; i++) {
        progressQueue.push(i / 100);
    }

    const totalDuration = 210000;
    const delay = totalDuration / progressQueue.length;

    progressQueue.forEach(function(progress, index) {
        setTimeout(function() {
			const remainingTime = Math.ceil((totalDuration - index * delay) / 1000);
            updateProgress(progress, remainingTime);
            if (progress === 1) {
                game.showAlert(getText('AllLoadingDone', 'SemiAutoATMenuLang'));
				ToolingMenuUpdateAllMainMenu(true);
                try {
                    const existingProgress = window.nativeWindow.menu.getItemByName("existingProgress");
                    if (existingProgress) {
                        window.nativeWindow.menu.removeItem(existingProgress);
                    }
                } catch (e) {}
            }
        }, index * delay);
    });
}


function AllUeberwachung(wasrestetueberwachung) {
    function checkUeberwachung() {
		shortcutGetpathVorlagenEnt();
        shortcutGetpathVorlagenGeo();
        shortcutGetpathVorlagenBuffs();
        shortcutGetpathVorlagenAusbau();
        shortcutGetpathVorlagenBauen();
        shortcutGetpathVorlagenZonenbuffs();
        WarteZeitZwischenVorlagenÜberwachungFinal = 0;
		if(parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenÜberwachungSelector, 10) === 0)
		{
			WarteZeitZwischenVorlagenÜberwachungFinal = 999 * WarteZeitZwischenVorlagenÜberwachungIntern;
			game.showAlert(getText('Paused', 'SemiAutoATMenuLang'));
		}
		else if(parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenÜberwachungSelector, 10) === 1 || parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenÜberwachungSelector, 10) === 2 || parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenÜberwachungSelector, 10) === 5)
		{
			WarteZeitZwischenVorlagenÜberwachungFinal = 10 * WarteZeitZwischenVorlagenÜberwachungIntern;
			game.showAlert(getText('TimeToLow', 'SemiAutoATMenuLang'));
		}
		else
		{
			WarteZeitZwischenVorlagenÜberwachungFinal = parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenÜberwachungSelector, 10) * WarteZeitZwischenVorlagenÜberwachungIntern;
		}

		if(!wasrestetueberwachung)
		{
			EntdeckerAktion();
		} else {
            wasrestetueberwachung = false;
        }

		nextExecutionTimeVorlagen = Date.now() + WarteZeitZwischenVorlagenÜberwachungFinal;

        ueberwachungTimeoutId = setTimeout(function () {
			checkUeberwachung();
		}, WarteZeitZwischenVorlagenÜberwachungFinal);
    }
    checkUeberwachung();
}

