function armyLoadGeneralsGenesAusStern() {
	try {
		menu.nativeMenu.getItemByName("DebugMethoden").label = "armyLoadGeneralsGenesAusStern()";
		safeReset('queuearmyLoadGeneralsGenesAusStern');
		queuearmyLoadGeneralsGenesAusStern = new TimedQueue(1000);
		var MyBuffIDReks = null;
		var armyMilitarySystemReks = swmmo.getDefinitionByName("MilitarySystem::cMilitaryUtil");
		var buffVectorReks = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();

		buffVectorReks.forEach(function(data) {
			if (
				data.GetBuffDefinition().GetName_string() === "HiredMilitary" &&
				data.GetResourceName_string() === user_fast_shortcut_settings.buffNameSöldnerSelector
			) {
				MyBuffIDReks = data.GetUniqueId();
			}
		});

		queuearmyLoadGeneralsGenesAusStern.add(function () {
			game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
			showGameAlert(getText('RefreshHiring', 'SemiAutoATMenuLang'));
		});

		$.each(battlePacket, function (item, packet) {
			var spec = armyGetSpecialistFromID(item);
			if (!spec) return;

			queuearmyLoadGeneralsGenesAusStern.add(function () {
				if (
					spec.getPlayerID() === game.player.GetPlayerId() &&
					spec.HasUnits() &&
					!spec.IsInUse() &&
					!spec.isTravellingAway() &&
					spec.GetGarrisonGridIdx() > 0 &&
					armySPECIALIST_TYPE.IsGeneral(spec.GetType())
				) {
					armyMilitarySystemReks.SendRaiseArmyToServer(game.gi, spec, null);
				}
			}, 2000);

			queuearmyLoadGeneralsGenesAusStern.add(function () {
				if (
					spec.getPlayerID() === game.player.GetPlayerId() &&
					armySPECIALIST_TYPE.IsGeneral(spec.GetType()) &&
					spec.GetGarrisonGridIdx() > 0 &&
					!spec.IsInUse() &&
					!spec.isTravellingAway()
				) {
					var grid = spec.GetGarrisonGridIdx();
					var firstReq = null;

					for (var res in packet.army) {
						if (packet.army.hasOwnProperty(res)) {
							firstReq = packet.army[res];
							break;
						}
					}

					if (MyBuffIDReks && firstReq) {
						game.gi.SendServerAction(61, 0, grid, firstReq, MyBuffIDReks);
					}
				}
			}, 4000);
		});

		queuearmyLoadGeneralsGenesAusStern.add(function () {
			showGameAlert(getText('HiringComplete', 'SemiAutoATMenuLang'));

			if (!game.gi.isOnHomzone() && automatisierung) {
				battleLoadDataNEW(function () {
					setTimeout(function () {armyLoadGeneralsGenesAusSternCheck();}, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector, 10));
				});
			}
		}, 6000);

		queuearmyLoadGeneralsGenesAusStern.run();

	} catch (e) {
		if (retrytryRunningMethod < 3) {
			safeReset('queuearmyLoadGeneralsGenesAusStern');
			retrytryRunningMethod++;
			armyLoadGeneralsGenesAusStern();
			showGameAlert('Retry - armyLoadGeneralsGenesAusStern Söldner erfolgreich');
		} else {
			showGameAlert('Retry x3 - armyLoadGeneralsGenesAusStern Söldner fehlgeschlagen');
		}
	}
}

function armyLoadGeneralsGenesAusSternCheck() {
	try {
		menu.nativeMenu.getItemByName("DebugMethoden").label = "armyLoadGeneralsGenesAusSternCheck()";
		safeReset('queuearmyLoadGeneralsNEWAusStern');
		queuearmyLoadGeneralsNEWAusStern = new TimedQueue(1000);

		var total = Object.keys(battlePacket).length;
		armyProgressCounter = total;

		$.each(battlePacket, function(key, value) {
			if (armyPacketMatches[key]) {
				total--;
				armyProgressCounter--;
				if (armyProgressCounter === 0) {
					showGameAlert(getText('HiringIsComplete', 'SemiAutoATMenuLang'));
					setTimeout(function () {
						if (!game.gi.isOnHomzone() && automatisierung) {
							KannWeiterGehen = true;
							automatisierungBasic("SöldnerBuffen");
						}
					}, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector, 10));
				}
				return;
			}

			var spec = armyGetSpecialistFromID(key);
			if (!spec) {
				armyProgressCounter--;
				showGameAlert(getText('NoGenes', 'SemiAutoATMenuLang'));
				return;
			}

			var dRaiseArmyVO = new dRaiseArmyVODef();
			dRaiseArmyVO.armyHolderSpecialistVO = spec.CreateSpecialistVOFromSpecialist();

			if (!value.army) return;

			$.each(value.army, function(resName, resAmount) {
				var dResourceVO = new dResourceVODef();
				dResourceVO.name_string = resName;
				dResourceVO.amount = resAmount;
				dRaiseArmyVO.unitSquads.addItem(dResourceVO);
			});

			queuearmyLoadGeneralsNEWAusStern.add(function () {
				game.gi.mClientMessages.SendMessagetoServer(1031, game.gi.mCurrentViewedZoneID, dRaiseArmyVO);
			});
		});

		if (queuearmyLoadGeneralsNEWAusStern.len() > 0) {
			queuearmyLoadGeneralsNEWAusStern.add(function () {
				if (retryBattleloadMethod < 3) {
					showGameAlert(getText('HiringCompleteCheck', 'SemiAutoATMenuLang'));
					battleLoadDataNEW(function () {
						setTimeout(armyLoadGeneralsGenesAusSternCheck, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector, 10));
					});
					retryBattleloadMethod++;
				}
				else if (retryBattleloadMethod === 3) {
					game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
					try
							{
								HammerManCountLoad++;
								menu.nativeMenu.getItemByName("HammermanMenu2").label = "Hammerman : " + HammerManCount + " | LagMove : " + HammerManCountMove + " | LagAttack : " + HammerManCountAttack + " | LagLoad : " + HammerManCountLoad;
							} catch (e) {}
					showGameAlert(getText('HiringErrorRefresh', 'SemiAutoATMenuLang'));
					setTimeout(function () {
						battleLoadDataNEW(function () {
							setTimeout(armyLoadGeneralsGenesAusStern, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector, 10));
						});
					}, 2000);
					retryBattleloadMethod++;
				}
				else {
					showGameAlert(getText('HiringErrorRefreshFail', 'SemiAutoATMenuLang'));
					shortcutsAutoFunc({
						target: {
							name: getText('DirectShortcutOFF', 'SemiAutoATMenuLang')
						}
					});
				}
			}, 8000);

			queuearmyLoadGeneralsNEWAusStern.run();
		}
	}
	catch (e) {
		if (retrytryRunningMethod < 3) {
			safeReset('queuearmyLoadGeneralsNEWAusStern');
			retrytryRunningMethod++;
			armyLoadGeneralsGenesAusSternCheck();
			showGameAlert('Retry - armyLoadGeneralsGenesAusSternCheck erfolgreich');
		} else {
			showGameAlert('Retry x3 - armyLoadGeneralsGenesAusSternCheck fehlgeschlagen');
		}
	}
}

