function battleLoadDataNEW(callback) {
	var retryLimit = 3;
	var retries = 0;

	function tryLoad() {
		try {
			menu.nativeMenu.getItemByName("DebugMethoden").label = "battleLoadDataNEW()";
			armyInfo = {};
			armyFreeInfo = {};

			var army = game.zone.GetArmy(game.player.GetPlayerId());
			var squads = army.GetSquadsCollection_vector().sort(game.def("MilitarySystem::cSquad").SortByCombatPriority);
			for (var i = 0; i < squads.length; i++) {
				var squad = squads[i];
				armyFreeInfo[squad.GetType()] = squad.GetAmount();
			}

			var armySPECIALIST_TYPE = swmmo.getDefinitionByName("Enums::SPECIALIST_TYPE");
			var specialists = game.zone.GetSpecialists_vector();

			for (var j = 0; j < specialists.length; j++) {
				var item = specialists[j];

				if (!armySPECIALIST_TYPE.IsGeneral(item.GetType()) || item.getPlayerID() !== game.player.GetPlayerId()) continue;
				if (!item || item.GetTask() !== null) continue;

				var uniqId = item.GetUniqueID().toKeyString();
				if (!armyInfo[uniqId]) {
					armyInfo[uniqId] = {
						name: item.getName(false),
						type: item.GetType(),
						army: {},
						skills: {}
					};
				}

				var skillTree = item.getSkillTree().getItems_vector();
				for (var k = 0; k < skillTree.length; k++) {
					var skill = skillTree[k];
					if (skill.getLevel() > 0) {
						armyInfo[uniqId].skills[k] = skill.getLevel();
					}
				}

				var generalSquads = item.GetArmy().GetSquadsCollection_vector().sort(game.def("MilitarySystem::cSquad").SortByCombatPriority);
				for (var l = 0; l < generalSquads.length; l++) {
					var gs = generalSquads[l];
					armyInfo[uniqId].army[gs.GetType()] = gs.GetAmount();
				}
			}

			battlePacket = battleLoadDataCheck(battlePacket);
			var checkedPacket = armyLoadDataCheck(battlePacket);

			var canSubmitAttack = true;
			var canSubmitMove = false;
			var attackSubmitChecker = [];

			$.each(battlePacket, function (itemKey) {
				var bpItem = battlePacket[itemKey];

				if (itemKey.substr(0, 4) === 'buff') {
					var gbCount = getBuffAvailableCount2(bpItem.name);
					var gbStatus = gbCount > 0;

					switch (bpItem.type) {
						case 'speedbuff':
							if (gbStatus) {
								canSubmitMove = true;
								bpItem.canMove = true;
							}
							break;
						case 'buff':
							if (!bpItem.canSubmitAttack && bpItem.target > 0) {
								canSubmitAttack = false;
							}
							attackSubmitChecker.push(bpItem.canAttack && bpItem.target > 0 && gbCount > 0);
							break;
					}
					return;
				}

				if (bpItem.spec == null) {
					canSubmitAttack = false;
					canSubmitMove = false;
					return;
				}

				if (bpItem.canSubmitMove) canSubmitMove = true;
				if (!bpItem.canSubmitAttack && bpItem.target > 0) canSubmitAttack = false;
				if (bpItem.target > 0) attackSubmitChecker.push(bpItem.canSubmitAttack);
			});

			if (typeof callback === "function") callback();
			if (user_fast_shortcut_settings.debugAT) {
			debug(battlePacket);}
		} catch (e) {
			retries++;
			if (retries < retryLimit) {
				showGameAlert("Retry – Battleload Versuch " + retries);
				setTimeout(tryLoad, 2000);
			} else {
				showGameAlert("Retry x" + retryLimit + " – Battleload fehlgeschlagen");
			}
			debug(e);
		}
	}

	tryLoad();
}

