function battleSendGeneralNEW(spec, name, targetName, type, target)
{
	try
	{
		game.gi.mCurrentCursor.mCurrentSpecialist = spec;
		var stask = new armySpecTaskDef();
		stask.uniqueID = spec.GetUniqueID();
		stask.subTaskID = 0;
		game.gi.SendServerAction(95, type, target, 0, stask);
		game.chatMessage("({0}/{1}) {2} {3} {4}".format(battleTimedQueueAuto.index, battleTimedQueueAuto.len() - 1, name.replace(/(<([^>]+)>)/gi, ""), (type == 5 ? ' x ' : ' > '), targetName), 'battle');
	}
	catch (e) {game.showAlert(e);}
}

function battleAttackNEW()
{
	try
	{
		menu.nativeMenu.getItemByName("DebugMethoden").label = "battleAttackNEW()";
		safeReset('battleTimedQueueAuto');
		battleTimedQueueAuto = new TimedQueue(1000);

		var RetryIntern = false;
		stopChecking = false;
		
		if(user_fast_shortcut_settings.HammermanMethoden)
		{
			var targetCampsAtk = [];
			$.each(battlePacket, function(item) {
				if(battlePacket[item].type == 'buff' || battlePacket[item].type == 'speedbuff'){ return;}
				if (targetCampsAtk.indexOf(battlePacket[item].target) === -1) {
					targetCampsAtk.push(battlePacket[item].target);
				}
			});
			
			$.each(battlePacket, function(item) {
				if (!battlePacket[item].canAttack) { return; }
				if (battlePacket[item].type == 'buff') {
					battleTimedQueueAuto.add(function() { 
						sendBuffPacket(buffsAvailable2[battlePacket[item].name].id, battlePacket[item].target);
					}, battlePacket[item].time);
					return;
				}
				if (battlePacket[item].type == 'speedbuff') {
					battleTimedQueueAuto.add(function() { 
						sendBuffPacket(buffsAvailable2[battlePacket[item].name].id, 0);
					});
					return;
				}
				var spec = armyGetSpecialistFromID(item);

				battleTimedQueueAuto.add(function(){ battleSendGeneralNEW(spec, battlePacket[item].name, battlePacket[item].targetName, 5, battlePacket[item].target); }, battlePacket[item].time);
			});
		}
		else
		{
			$.each(battlePacket, function(item) {
				if(!battlePacket[item].canAttack) { return; }
				if(battlePacket[item].type == 'buff') {
					battleTimedQueueAuto.add(function(){ 
						sendBuffPacket(buffsAvailable2[battlePacket[item].name].id, battlePacket[item].target);
					}, battlePacket[item].time);
					return;
				}
				if(battlePacket[item].type == 'speedbuff') {
					battleTimedQueueAuto.add(function(){ 
						sendBuffPacket(buffsAvailable2[battlePacket[item].name].id, 0);
					});
					return;
				}
				var spec = armyGetSpecialistFromID(item);
				
				battleTimedQueueAuto.add(function(){ battleSendGeneralNEW(spec, battlePacket[item].name, battlePacket[item].targetName, 5, battlePacket[item].target); }, battlePacket[item].time);
			});
		}
		
		
		
		if(user_fast_shortcut_settings.HammermanMethoden)
		{
		
			var allTargetsGone = false;
			
			var checkAllTargetsExistence = function() {
				if (stopChecking) {
					return;
				}
				allTargetsGone = true;
				for (var i = 0; i < targetCampsAtk.length; i++) {
					if (battleSendGeneralNEWCampExistAttack(targetCampsAtk[i]) && !RetryIntern && !game.gi.mPacketLost) {
						menu.nativeMenu.getItemByName("DebugMethoden").label = "battleAttackNEW("+ "Camp nicht zerstört: " + targetCampsAtk[i] +")";
						allTargetsGone = false;
						setTimeout(checkAllTargetsExistence, 10000);
						return;
					}
				}

				if (allTargetsGone && !game.gi.isOnHomzone() && game.gi.mCurrentPlayer.mIsAdventureZone && automatisierung && !game.gi.mPacketLost) {
					RetryIntern = true;
					targetCampsAtk = [];
					stopChecking = true;
					safeReset('AttackTimeoutIntern');
					setTimeout(function() {
						KannWeiterGehen = true;
						automatisierungBasic("Angriff");
					}, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector, 10));
					return;
				}
			};
		
			var checkAllAttackTimeoutIntern = function() {
				const TIMEOUT_DELAY = 300000;
				const SHORT_DELAY = 5000;
				const LONG_DELAY = 60000;
				
				AttackTimeoutIntern = setTimeout(function () {
					game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);

					setTimeout(function() {
						var taskGenesOnAttack;
						var GenesOnAttack = false;

						function checkSpecialists(callback) {
							try {
								swmmo.application.mGameInterface.mCurrentPlayerZone.GetSpecialists_vector().forEach(function(item) {
									if (game.player.GetPlayerId() == item.getPlayerID()) {
										if (item.GetTask() != null) {
											taskGenesOnAttack = item.GetTask().toString();
										}
										if (item.IsInUse() && taskGenesOnAttack != "[object cSpecialistTask_Recover]") {
											GenesOnAttack = true;
										}
									}
								});
								callback();
							} catch (e) {
								game.showAlert(e);
							}
						}

						function handleConditionalActions() {
							try
							{
								HammerManCountAttack++;
								menu.nativeMenu.getItemByName("HammermanMenu2").label = "Hammerman : " + HammerManCount + " | LagMove : " + HammerManCountMove + " | LagAttack : " + HammerManCountAttack + " | LagLoad : " + HammerManCountLoad;
							} catch (e) {}
							
							showGameAlert('Lag Hammer - Attack Retry');
							if (!allTargetsGone && !RetryIntern && !GenesOnAttack && !LetzteVorlage && game.gi.isOnHomzone() == false && !game.gi.mPacketLost) {
								$.each(battlePacket, function(item) {
									var spec2 = armyGetSpecialistFromID(item);
									battleSendGeneralNEW(spec2, battlePacket[item].name, battlePacket[item].grid, 4, battlePacket[item].grid);
								});
								setTimeout(function() {
									battleLoadDataNEW(function() {
										setTimeout(function() {battleAttackNEW();}, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector, 10));
									});
								}, LONG_DELAY);
								safeReset('AttackTimeoutIntern');
							}
						}

						checkSpecialists(function() {
							handleConditionalActions();
						});
					}, SHORT_DELAY);
				}, TIMEOUT_DELAY);
			};
			
			battleTimedQueueAuto.add(function() {
				checkAllTargetsExistence();
				checkAllAttackTimeoutIntern();
			}, 20000);
		}
		else
		{
			battleTimedQueueAuto.add(function(){ if(game.gi.isOnHomzone() == false && automatisierung){ KannWeiterGehen = true;automatisierungBasic("Angriff");}}, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector, 10));
		}

		battleTimedQueueAuto.run();
	}
	catch(e)
	{
		if(retrytryRunningMethod < 3){
			safeReset('battleTimedQueueAuto');
			retrytryRunningMethod++; 
			battleAttackNEW(); 
			showGameAlert('Retry - battleAttackNEW erfolgreich');
		}
		else
		{
			showGameAlert('Retry x3 - battleAttackNEW fehlgeschlagen');
		}
	}
}

function battleMoveNEW()
{
	try
	{
		menu.nativeMenu.getItemByName("DebugMethoden").label = "battleMoveNEW()";
		VomSternGen = false;
		safeReset('battleTimedQueueAuto');
		battleTimedQueueAuto = new TimedQueue(1000);
		
		var RetryIntern = false;
		var taskGenesOnMove = null;
		stopChecking = false;
		
		if(user_fast_shortcut_settings.HammermanMethoden)
		{
			var targetsGridMove = [];
			$.each(battlePacket, function(item) {
				if(battlePacket[item].type == 'buff' || battlePacket[item].type == 'speedbuff'){ return;}
				if (targetsGridMove.indexOf(battlePacket[item].grid) === -1) {
					targetsGridMove.push(battlePacket[item].grid);
				}
			});
		}

		$.each(battlePacket, function(item) {
			if(battlePacket[item].type == 'buff' || battlePacket[item].type == 'speedbuff'){ return;}
			var spec = armyGetSpecialistFromID(item);

			if(battlePacket[item].grid > 0) {
				battleTimedQueueAuto.add(function(){ battleSendGeneralNEW(spec, battlePacket[item].name, battlePacket[item].grid, 4, battlePacket[item].grid); });
			} else {
				battleTimedQueueAuto.add(function(){ armySendGeneralToStar(spec); });
			}

			if(automatisierung && game.gi.isOnHomzone() == false)
			{
				swmmo.application.mGameInterface.mCurrentPlayerZone.GetSpecialists_vector().forEach(function(item2){
					if(spec.GetUniqueID().toKeyString() == item2.GetUniqueID().toKeyString() && item2.GetGarrisonGridIdx() == -1)
					{
						VomSternGen = true;
					}
				});
			}
		});
		
		if(user_fast_shortcut_settings.HammermanMethoden)
		{
		
			var allTargetsSet = false;

			var checkAllTargetsSet = function() {
				if (stopChecking) {
					return;
				}
				allTargetsSet = true;
				for (var i = 0; i < targetsGridMove.length; i++) {
					if (!battleSendGeneralNEWCampExistMove(targetsGridMove[i]) && !RetryIntern && !game.gi.mPacketLost) {
						menu.nativeMenu.getItemByName("DebugMethoden").label = "battleMoveNEW("+ "Grid nicht besetzt: " + targetsGridMove[i] +")";
						allTargetsSet = false;
						setTimeout(checkAllTargetsSet, 10000);
						return;
					}
				}

				if (allTargetsSet && !game.gi.isOnHomzone() && game.gi.mCurrentPlayer.mIsAdventureZone && automatisierung && !game.gi.mPacketLost) {
					RetryIntern = true;
					targetsGridMove = [];
					stopChecking = true;
					safeReset('MoveTimeoutIntern');
					if(game.gi.isOnHomzone() == false && VomSternGen == true && automatisierung && game.gi.mCurrentPlayer.mIsAdventureZone)
					{
						game.showAlert(getText('AutoMove', 'SemiAutoATMenuLang') + parseInt(user_fast_shortcut_settings.WarteZeitAusSternVersetzenSelector, 10) + getText('AutoMove2', 'SemiAutoATMenuLang') + "(" +parseInt(user_fast_shortcut_settings.WarteZeitAusSternVersetzenSelector, 10)/1000 + getText('AutoMove3', 'SemiAutoATMenuLang'));
						setTimeout(function() {if(game.gi.isOnHomzone() == false && automatisierung){ KannWeiterGehen = true;automatisierungBasic("Move");game.showAlert(getText('NextAuto', 'SemiAutoATMenuLang'));}},parseInt(user_fast_shortcut_settings.WarteZeitAusSternVersetzenSelector));	
					}
					else if(game.gi.isOnHomzone() == false && VomSternGen == false && automatisierung && game.gi.mCurrentPlayer.mIsAdventureZone)
					{							
						setTimeout(function() {if(game.gi.isOnHomzone() == false && automatisierung){ KannWeiterGehen = true;automatisierungBasic("Move");}},parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector));
					}
					return;
				}
			};
		
			var checkAllMoveTimeoutIntern = function() {
				const TIMEOUT_DELAY = 300000;
				const SHORT_DELAY = 5000;
				const LONG_DELAY = 60000;

				var taskGenesOnMove;
				var GenesOnMove = false;

				function checkSpecialists(callback) {
					try {
						swmmo.application.mGameInterface.mCurrentPlayerZone.GetSpecialists_vector().forEach(function(item) {
							if (game.player.GetPlayerId() == item.getPlayerID()) {
								if (item.GetTask() != null) {
									taskGenesOnMove = item.GetTask().toString();
								}
								if (item.IsInUse() && taskGenesOnMove != "[object cSpecialistTask_Recover]") {
									GenesOnMove = true;
								}
							}
						});
						callback();
					} catch (e) {
						game.showAlert(e);
						callback(e);
					}
				}

				function handleConditionalActions() {
					if (!allTargetsSet && !RetryIntern && !GenesOnMove && !LetzteVorlage && game.gi.isOnHomzone() == false && !game.gi.mPacketLost) {
						try
							{
								HammerManCountMove++;
								menu.nativeMenu.getItemByName("HammermanMenu2").label = "Hammerman : " + HammerManCount + " | LagMove : " + HammerManCountMove + " | LagAttack : " + HammerManCountAttack + " | LagLoad : " + HammerManCountLoad;
							} catch (e) {}
						
						showGameAlert('Lag Hammer - Move Retry');
						shortcutsReturnAllNEWLagHammer();

						setTimeout(function() {
							battleLoadDataNEW(function() {
								setTimeout(function() {battleMoveNEW();}, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector, 10));
							});
						}, LONG_DELAY);
						safeReset('MoveTimeoutIntern');
					}
				}

				MoveTimeoutIntern = setTimeout(function() {
					game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
					setTimeout(function() {
						checkSpecialists(function() {
							handleConditionalActions();
						});
					}, SHORT_DELAY);
				}, TIMEOUT_DELAY);
			};
						
			battleTimedQueueAuto.add(function() {
				checkAllTargetsSet();
				checkAllMoveTimeoutIntern();
			}, 20000);
		}
		else
		{
			if(game.gi.isOnHomzone() == false && VomSternGen == true && automatisierung && game.gi.mCurrentPlayer.mIsAdventureZone)
			{
				game.showAlert(getText('AutoMove', 'SemiAutoATMenuLang') + parseInt(user_fast_shortcut_settings.WarteZeitAusSternVersetzenSelector, 10) + getText('AutoMove2', 'SemiAutoATMenuLang') + "(" +parseInt(user_fast_shortcut_settings.WarteZeitAusSternVersetzenSelector, 10)/1000 + getText('AutoMove3', 'SemiAutoATMenuLang'));
				setTimeout(function() {if(game.gi.isOnHomzone() == false && automatisierung){ KannWeiterGehen = true;automatisierungBasic("Move");game.showAlert(getText('NextAuto', 'SemiAutoATMenuLang'));}},parseInt(user_fast_shortcut_settings.WarteZeitAusSternVersetzenSelector));
			}
			else if(game.gi.isOnHomzone() == false && VomSternGen == false && automatisierung && game.gi.mCurrentPlayer.mIsAdventureZone)
			{
				setTimeout(function() {if(game.gi.isOnHomzone() == false && automatisierung){ KannWeiterGehen = true;automatisierungBasic("Move");}},parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector));
			}
		}
			
		battleTimedQueueAuto.run();
	}
	catch(e)
	{
		if(retrytryRunningMethod < 3)
		{
			safeReset('battleTimedQueueAuto');
			retrytryRunningMethod++; 
			battleMoveNEW(); 
			showGameAlert('Retry - battleMoveNEW erfolgreich');
		}
		else
		{
			showGameAlert('Retry x3 - battleMoveNEW fehlgeschlagen');
		}
	}
}

