function automatisierungBasic(currenttask) {
    menu.nativeMenu.getItemByName("DebugMethoden").label = "automatisierungBasic(" + currenttask +")";
    if (automatisierung && game.gi.isOnHomzone() == false && game.gi.mCurrentPlayer.mIsAdventureZone) {
        var MaxGenes = 0;
		var OnlyOnce = true;
        var arryAva = [];
        var task = "";
		var Genes;
		var startTime = new Date().getTime();

        function checkGenerals() {
            menu.nativeMenu.getItemByName("DebugMethoden").label = "automatisierungBasic(checkGenerals - " + currenttask +")";
            if (!automatisierung || LetzteVorlage || !game.gi.mCurrentPlayer.mIsAdventureZone) {
				menu.nativeMenu.getItemByName("DebugMethoden").label = "automatisierungBasic() - nicht mehr aktiv!";
                return;
            }
			
			if (GetQuestSemiStarten == true) {
				GetQuestSemi();
				GetQuestSemiStarten = false;
			}

            arryAva = [];
            MaxGenes = 0;
			
			try {
				swmmo.application.mGameInterface.mCurrentPlayerZone.GetSpecialists_vector().forEach(function(item) {
					if (game.player.GetPlayerId() == item.getPlayerID()) {
						MaxGenes++;
					}
				});
            } catch (e) 
			{
				if (user_fast_shortcut_settings.debugAT) {
					debug("automatisierungBasic maxgenes catch");
					debug(e);
				}
                game.showAlert(e);
            }
            try {
                swmmo.application.mGameInterface.mCurrentPlayerZone.GetSpecialists_vector().forEach(function(item) {
                    if (game.player.GetPlayerId() == item.getPlayerID()) {
						Genes = item;
                        if (item.GetTask() != null) {
                            task = item.GetTask().toString();
                        }

                        if (item.IsInUse() && task != "[object cSpecialistTask_Recover]") {
                            var index = arryAva.indexOf(item.GetUniqueID().toKeyString());
                            if (index > -1) {
                                arryAva.splice(index, 1);
                            }
                        } else if (item.IsInUse() && task == "[object cSpecialistTask_Recover]") {
                            if (arryAva.indexOf(item.GetUniqueID().toKeyString()) == -1) {
                                arryAva.push(item.GetUniqueID().toKeyString());
                            }
                        } else if (!item.IsInUse() && item.GetTask() == null) {
                            if (arryAva.indexOf(item.GetUniqueID().toKeyString()) == -1) {
                                arryAva.push(item.GetUniqueID().toKeyString());
                            }
                        }

                        if (user_fast_shortcut_settings.debugAT) {
                            debug(item);
                        }
                    }
                });
            } catch (e) {
				debug("automatisierungBasic item catch");
				debug(e);
                debug(Genes);
                game.showAlert(e);
				RefreshGenesData(Genes);
            }

            if (arryAva.length === MaxGenes && KannWeiterGehen == true && OnlyOnce == true && automatisierung == true && game.gi.mCurrentPlayer.mIsAdventureZone && !game.gi.mPacketLost) {
                menu.nativeMenu.getItemByName("DebugMethoden").label = "automatisierungBasic("+currenttask+")" + " - geht weiter";
                KannWeiterGehen = false;
				OnlyOnce = false;
                game.showAlert(getText('AllGenesReady', 'SemiAutoATMenuLang'));
                if (Hufeisendelay) {
                    ATStartBuffen();
                    Hufeisendelay = false;
                }
                shortcutsMenuSelectedHandlerNew(WoBinIch);
                return;
            }

            if (user_fast_shortcut_settings.debugAT) {
                debug("arryAva.length: " + arryAva.length);
            }
			
			var currentTime = new Date().getTime();
            var elapsedTime = currentTime - startTime;
            if (elapsedTime >= 15 * 60 * 1000 && KannWeiterGehen == true && OnlyOnce == true && automatisierung == true && game.gi.mCurrentPlayer.mIsAdventureZone) {
                game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
                showGameAlert(getText('LagHammerinAT', 'SemiAutoATMenuLang'));
                setTimeout(function() {
                    automatisierungBasic("RetryLaghammer");
                }, 20000);
                return;
            }
            
            setTimeout(checkGenerals, 10000);
        }

        setTimeout(checkGenerals, 10000);
    }
}

function RefreshGenesData(spec)
{
	if (spec === undefined || spec == null || game.gi.mPacketLost) return;
	try
	{
		swmmo.getDefinitionByName("globalFlash").gui.mSpecialistPanel.SetData(spec);
		swmmo.getDefinitionByName("globalFlash").gui.mSpecialistPanel.Show();
		swmmo.getDefinitionByName("globalFlash").gui.mSpecialistPanel.Hide();
	}
	catch (e)
	{
		debug("RefreshGenesData");
		debug(e);
		debug(spec);
	}
}

function automatisierungBasicATneustarten() {
    if (automatisierung && game.gi.isOnHomzone() && ATweitermachen && MyStart) {
        menu.nativeMenu.getItemByName("DebugMethoden").label = "automatisierungBasicATneustarten()";
        var arryAvaATneustarten = [];
        WoBinIchATneustarten = 0;
        PathGensAuslesen = true;
		var OnlyOnceATneustarten = true;
        shortcutsMenuSelectedHandlerNewGenAuslesen(WoBinIchATneustarten);
        var MaxGenesATneustarten;
		var startTime = new Date().getTime();

        function checkGeneralsATneustarten() {
            menu.nativeMenu.getItemByName("DebugMethoden").label = "automatisierungBasicATneustarten(checkGeneralsATneustarten)";
			if (!automatisierung || !game.gi.isOnHomzone() || !ATweitermachen || !MyStart) {
				menu.nativeMenu.getItemByName("DebugMethoden").label = "automatisierungBasicATneustarten(checkGeneralsATneustarten) - nicht mehr aktiv!";
				var event = {
                    target: {
                        name: getText('DirectShortcutOFF', 'SemiAutoATMenuLang')
                    }
                };
                shortcutsAutoFunc(event);
                return;
            }
            MaxGenesATneustarten = GenesAuslesenausVorlage.length;
            arryAvaATneustarten = [];

            try {
                GenesAuslesenausVorlage.forEach(function (item) {
					if(item == "00000.0")
					{
						if (arryAvaATneustarten.indexOf(item) == -1) {
                            arryAvaATneustarten.push(item);
                        }
						return;
					}
                    if (item.GetTask() != null || item.IsInUse() || item.isTravellingAway() || item.GetWaitingForServer()) {
                        var index = arryAvaATneustarten.indexOf(item.GetUniqueID().toKeyString());
                        if (index > -1) {
                            arryAvaATneustarten.splice(index, 1);
                        }
                    } else if (item.GetTask() == null && !item.IsInUse() && !item.isTravellingAway() && !item.GetWaitingForServer()) {
                        if (arryAvaATneustarten.indexOf(item.GetUniqueID().toKeyString()) == -1) {
                            arryAvaATneustarten.push(item.GetUniqueID().toKeyString());
                        }
                    }

                    if (user_fast_shortcut_settings.debugAT) {
                        debug(item);
                    }
                });
            } catch (e) {
				debug("automatisierungBasicATneustarten catch");
				debug(e);
                game.showAlert(e);
				setTimeout(automatisierungBasicATneustarten, 6000);
				return;
            }

            if (arryAvaATneustarten.length === MaxGenesATneustarten && OnlyOnceATneustarten && KannWeiterGehenATneustarten && ATweitermachen && automatisierung && game.gi.isOnHomzone() && !game.gi.mPacketLost) {
                menu.nativeMenu.getItemByName("DebugMethoden").label = "automatisierungBasicATneustarten() - geht weiter";
				if(user_fast_shortcut_settings.UnloadAllTroops)
				{
					shortcutsFreeAllUnitsNEW();
					setTimeout(function () {
						KannWeiterGehenATneustarten = false;
						OnlyOnceATneustarten = false;
						RundenanzahlCounter++;
						game.showAlert(getText('AllGenesReadyForAT', 'SemiAutoATMenuLang'));
						shortcutsMenuSelectedHandlerNew(WoBinIchATneustarten);	
					}, 30000);
				}
				else
				{
					KannWeiterGehenATneustarten = false;
					OnlyOnceATneustarten = false;
					RundenanzahlCounter++;
					game.showAlert(getText('AllGenesReadyForAT', 'SemiAutoATMenuLang'));
					shortcutsMenuSelectedHandlerNew(WoBinIchATneustarten);
				}
				return;
            }

            if (user_fast_shortcut_settings.debugAT) {
                debug("arryAvaATneustarten.length: " + arryAvaATneustarten.length);
                debug("RundenanzahlCounter: " + RundenanzahlCounter);
            }
			
			var currentTime = new Date().getTime();
            var elapsedTime = currentTime - startTime;
            if (elapsedTime >= 15 * 60 * 1000 && KannWeiterGehenATneustarten == true && OnlyOnceATneustarten == true && automatisierung == true && ATweitermachen && game.gi.isOnHomzone()) {
                game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
                showGameAlert(getText('LagHammerinATStart', 'SemiAutoATMenuLang'));
                setTimeout(function() {
                    automatisierungBasicATneustarten();
                }, 6000);
                return;
            }

            setTimeout(checkGeneralsATneustarten, 20000);
        }

        setTimeout(checkGeneralsATneustarten, 20000);
    }
}

