function MemTriggerClientRestartNONATTIME() {
	try{
		if (!user_fast_shortcut_settings.MemUeberwachungNONATTIME || MemTriggerClientRestartNONAT()) {
			if (user_fast_shortcut_settings.debugAT) {
			debug("MemUeberwachungNONATTIME ist deaktiviert. Oder HI Grenze läuft");}
			return false;
		}

		var limit = user_fast_shortcut_settings.MemUeberwachungLimitNONATTIME;
		if (user_fast_shortcut_settings.debugAT) {
		debug("Gesetztes Zeitlimit (Limit): " + limit);}

		var now = new Date();
		var yyyy = now.getFullYear();
		var mm = ("0" + (now.getMonth() + 1)).slice(-2);
		var dd = ("0" + now.getDate()).slice(-2);
		var todayDateStr = yyyy + "-" + mm + "-" + dd;
		if (user_fast_shortcut_settings.debugAT) {
		debug("Heutiges Datum (todayDateStr): " + todayDateStr);
		debug("Letzter ausgeführter Restart (LastTimeRestartDate): " + user_fast_shortcut_settings_MemTime.LastTimeRestartDate);}

		if (user_fast_shortcut_settings_MemTime.LastTimeRestartDate === todayDateStr) {
			if (user_fast_shortcut_settings.debugAT) {
			debug("Zeitlimit wurde bereits heute erreicht – kein Restart.");}
			return false;
		}

		var parts = limit.split(":");
		if (parts.length !== 2) {
			if (user_fast_shortcut_settings.debugAT) {
			debug("Ungültiges Format für Zeitlimit: " + limit);}
			return false;
		}

		var limitHour = parseInt(parts[0], 10);
		var limitMinute = parseInt(parts[1], 10);
		if (user_fast_shortcut_settings.debugAT) {
		debug("Limit Stunde: " + limitHour + ", Limit Minute: " + limitMinute);}

		if (isNaN(limitHour) || isNaN(limitMinute)) {
			if (user_fast_shortcut_settings.debugAT) {
			debug("Zeitlimit-Parsing fehlgeschlagen: " + parts[0] + ":" + parts[1]);}
			return false;
		}

		var nowHour = now.getHours();
		var nowMinute = now.getMinutes();
		if (user_fast_shortcut_settings.debugAT) {
		debug("Aktuelle Zeit: " + nowHour + ":" + nowMinute);}

		if (nowHour > limitHour ||(nowHour === limitHour && nowMinute >= limitMinute)) 
		{
			if (user_fast_shortcut_settings_AutoAT.Runde === 0 && user_fast_shortcut_settings_AutoSzenario.Runde === 0) 
			{
				user_fast_shortcut_settings_MemTime.LastTimeRestartDate = todayDateStr;
				MemTimesave();
				setTimeout(DoARestart, 120000);
				return true;
			} else {
				if (user_fast_shortcut_settings.debugAT) {
				debug("Zeit erreicht, aber aktive Runden – kein Restart.");}
				return false;
			}
		} else {
			if (user_fast_shortcut_settings.debugAT) {
			debug("Zeitlimit noch nicht erreicht – kein Restart.");}
		}

		return false;
	}catch(e){debug("Fehler in MemTriggerClientRestartNONATTIME: " + e);}
}

function MemTimesave()
{
	settings.settings["FastShortcutMemTime"] = {};
	settings.store(user_fast_shortcut_settings_MemTime, "FastShortcutMemTime");
}

var timeWatcherInterval = null;

function startTimeWatcher() {
	try {
		var now = new Date();
		var yyyy = now.getFullYear();
		var mm = ("0" + (now.getMonth() + 1)).slice(-2);
		var dd = ("0" + now.getDate()).slice(-2);
		var todayDateStr = yyyy + "-" + mm + "-" + dd;

		/* if (user_fast_shortcut_settings_MemTime.LastTimeRestartDate === todayDateStr) {
			if (user_fast_shortcut_settings.debugAT) {
			debug("startTimeWatcher – Heute bereits ausgeführt: " + todayDateStr + ", Watcher wird nicht gestartet.");}
			if (timeWatcherInterval !== null) {
				clearInterval(timeWatcherInterval);
				timeWatcherInterval = null;
			}
			return;
		} */
		if (user_fast_shortcut_settings.debugAT) {
		debug("startTimeWatcher – Watcher wird gestartet.");}

		timeWatcherInterval = setInterval(function () {
			if (
				user_fast_shortcut_settings.MemUeberwachungNONATTIME &&
				!ATweitermachen &&
				stopScenario &&
				game.gi.isOnHomzone()
			) {
				if (user_fast_shortcut_settings.debugAT) {
				debug("startTimeWatcher Tick – Bedingungen erfüllt, prüfe Zeitlimit...");}
				if (MemTriggerClientRestartNONATTIME()) {
					if (user_fast_shortcut_settings.debugAT) {
					debug("Zeitlimit überschritten – Neustart wird vorbereitet...");}
					showGameAlert("Zeitlimit erreicht, Neustart demnächst!");
					try {
						menu.nativeMenu.getItemByName("AutoATRundenanzahl").label = "TIME - Zeitgrenze erreicht, Neustart demnächst!";
					} catch (e) {
						debug("Fehler beim Setzen des Menüs: " + e);
					}
					ToolingMenuUpdateSzenaMenu(false);
					ToolingMenuUpdateSzenaStoppen(false);
					ToolingMenuUpdateSzenaStarten(false);
					ToolingMenuUpdate(false);
					ToolingMenuUpdateMainMenu(false);
					clearInterval(timeWatcherInterval);
					timeWatcherInterval = null;
				} else {
					if (user_fast_shortcut_settings.debugAT) {
					debug("Zeitlimit noch nicht erreicht.");}
				}
			} else {
				if (user_fast_shortcut_settings.debugAT) {debug("startTimeWatcher Tick – Bedingungen nicht erfüllt, kein Check.");}
			}
		}, 60000);
	} catch (e) {
		debug("Fehler in startTimeWatcher: " + e);
	}
}

function shortcutGetPath()
{
	var item = shortcutGetPathArray;
	
	item.forEach(function(data, idx){
		if(/--s[0-9]+p--/.test(data)) {
			
			return;
		}
		if(idx == user_fast_shortcut_settings.ATAuswahlID && PathATAuslesen)
		{
			ShortcutPathArray = [];
			data.items.forEach(function(i, index) {
					var label = "{0}".format(i);
						var label2 = label.split(",")[0];	
						ShortcutPathArray.push(label2);
				});	
		}
		
		if(idx == user_fast_shortcut_settings.ATAuswahlID && PathATAuslesen)
		{
			ShortcutPathArrayDirektSenden = [];
			data.items.forEach(function(i, index) {
					var label = "{0}".format(i);
					var label2 = label.split(",")[0];	
					ShortcutPathArrayDirektSenden.push(label2);
				});	
		}

		if(automatisierung && !MyStart && idx == GetIndexAT && !PathATAuslesen)
		{
			ShortcutPathArray = [];
			data.items.forEach(function(i, index) {
					var label = "{0}".format(i);
						var label2 = label.split(",")[0];	
						ShortcutPathArray.push(label2);
						
				});
				GetIndexATAuslesen = false;	
		}		
	});
}

