function ATStart() {
	if (PathATAuslesen) {
		shortcutGetPath();
		PathATAuslesen = false;
	}

	function checkATStart() {
		if(!automatisierung)
		{
			return;
		}
		if (game.gi.isOnHomzone() == false && automatisierung == true && game.gi.mCurrentPlayer.mIsAdventureZone) {
			if (WoBinIch == 0) {
				menu.nativeMenu.getItemByName("DebugMethoden").label = "ATStart() - im AT";
				game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
				showGameAlert('Auto Zone Refresh (F2)');
				game.showAlert(getText('AutoATMonitoringActive', 'SemiAutoATMenuLang'));
				setTimeout(function () {
					if (automatisierung && game.gi.mCurrentPlayer.mIsAdventureZone) {
						WoBinIch = -1;
						KannWeiterGehen = true;
						Hufeisendelay = true;
						/* if(user_fast_shortcut_settings.NoGenesLanding)
						{
							game.gi.mCurrentPlayerZone.mStreetDataMap.mLandingFields_vector.length = 0;
						} */
						automatisierungBasic("ATStart");
					}
				}, parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector));
				RefreshGUIBUI();
				GetQuest();
				if (user_fast_shortcut_settings.debugAT) {
					debug("Auto AT Start Überwachung aktiv | WoBinIch: " + WoBinIch);
				}
				return;
			} else {
				game.showAlert(getText('AbortAutoAT', 'SemiAutoATMenuLang'));
				game.showAlert(getText('StopSaftyAutomatic', 'SemiAutoATMenuLang'));
				var event = {
						target: {
									name: getText('DirectShortcutOFF', 'SemiAutoATMenuLang')
								}
				};
				shortcutsAutoFunc(event);
			}
		} else if (game.gi.isOnHomzone() == true && ATweitermachen == true && RundenanzahlCounter < user_fast_shortcut_settings.RundenanzahlSelector) {
			menu.nativeMenu.getItemByName("DebugMethoden").label = "ATStart() - Auf Heimatinsel";
			game.showAlert(getText('AutoATMonitoringActive', 'SemiAutoATMenuLang'));
			game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null); //Test 0300625
			showGameAlert('Auto Zone Refresh (F2)'); //Test 0300625
			try {
				var RundeAktuell = RundenanzahlCounter + 1;
				menu.nativeMenu.getItemByName("AutoATRundenanzahl").label = "AutoAT Runde : " + RundeAktuell;
			} catch (e) {}

			if (user_fast_shortcut_settings.debugAT) {
				debug("RundenanzahlCounter: " + RundenanzahlCounter);
				debug("Direktsenden Index Länge: " + ShortcutPathArrayDirektSenden.length);
			}
			
			if(user_fast_shortcut_settings.Wirbelwindbuffen)
			{
				setTimeout(function() {
					ZoneBuffForAutoAT("PropagationBuff_AdventureZoneTravelBoost_BlackTree");
				}, 3000);
			}
			
			if(user_fast_shortcut_settings.Resteessenbuffen)
			{
				setTimeout(function() {
					ZoneBuffForAutoAT("PropagationBuff_AdventureZoneTravelBoost_DoggyBag");    
				}, 5000);
			}
			
			if(user_fast_shortcut_settings.Feldlazabuffen)
			{
				setTimeout(function() {
					GebaeudeBuffsExe("GrandFieldHospital", user_fast_shortcut_settings.FeldlazaSelector, loca.GetText("BUI", "GrandFieldHospital"));       
				}, 9000);
			}
			if(user_fast_shortcut_settings.Freiluftbuffen)
			{
				setTimeout(function() {
					GebaeudeBuffsExe("OutdoorCanteen", user_fast_shortcut_settings.FreiluftSelector, loca.GetText("BUI", "OutdoorCanteen"));       
				}, 11000);
			}
			if(user_fast_shortcut_settings.Obsibuffen)
			{
				setTimeout(function() {
					GebaeudeBuffsExe("Observatory", user_fast_shortcut_settings.ObsiSelector, loca.GetText("BUI", "Observatory"));       
				}, 13000);
			}
			if(user_fast_shortcut_settings.Spaehbuffen)
			{
				setTimeout(function() {
					GebaeudeBuffsExe("EspionageBuilding", user_fast_shortcut_settings.SpaehSelector, loca.GetText("BUI", "EspionageBuilding"));       
				}, 15000);
			}

			setTimeout(function () {
				ATStartBuffen();                   
			}, parseInt(user_fast_shortcut_settings.WarteZeitZwischenATAutoStartSelector));
			return;
		}
		setTimeout(checkATStart, 10000);
	}

	setTimeout(checkATStart, 10000);
}

var	CollectiblesQuestsImAT = [ "CollectAllCollectiblesAdventure", "MiadSleepyReefQ4", "MiadArcticExplosionQ3", "MiadArcticExplosionQ4", "TombRaidersQ2", "CoopLakesideTreasureQ3", "MiadTheLostSkullQ3", "MiadBastilleIslandQ6", "RaidingtheRaidersQ3", "MiadTheSleepingVolcanoQ3", "MiadPirateLifeQ1a", "MiadPirateLifeQ2a", "MiadPirateLifeQ3a" ];

function GetQuest() {
	var LastQuest = false;
	var CounterQuestCheck = 0;
	game.gi.mQuestClientCallbacks.JustRefresh();
	globalFlash.gui.mQuestBook.Show();
	globalFlash.gui.mQuestBook.Hide();
	setTimeout(shortcutsPickupAllATFirstStart, 5000);
    function checkQuest() {
		if(!automatisierung || !ATweitermachen || !game.gi.mCurrentPlayer.mIsAdventureZone)
		{
			return;
		}
		
		try{
			if (game.gi.mCurrentPlayer.mIsAdventureZone && game.gi.mNewQuestManager.GetQuestPool().IsAnyQuestsActive()) {
				game.gi.mQuestClientCallbacks.JustRefresh();
				$.each(game.gi.mNewQuestManager.GetQuestPool().GetQuest_vector(), function (i, item) {
					if (item == null || LastQuest)
					{
						return;
					}						
					if (user_fast_shortcut_settings.debugAT) {
						debug(item.GetQuestDefinition());
						debug(item.GetQuestDefinition().specialType_string.toString());
					}
					
					globalFlash.gui.mQuestBook.SetPreselectedQuest(item);

					var questmode = item.GetQuestMode().toString();
					var questname = item.getQuestName_string();			

					if (questmode == "2")
					{
						globalFlash.gui.mQuestBook.Show();
						game.gi.mQuestClientCallbacks.QuestOkButtonPressedFromGui(item);
						globalFlash.gui.mQuestBook.Hide();
					}	
					
					if ((questmode == "1" || questmode == "3") && CollectiblesQuestsImAT.indexOf(questname) >= 0) {
						shortcutsPickupAllAT();
					}
					
					//game.showAlert("Quest: " + questname + "(Mode:"+ questmode +")" + " | " + "isFinished:"+item.isFinished());
					
					if (item.isFinished()) {
						game.showAlert(getText('QuestFinish', 'SemiAutoATMenuLang') + questname + "(Mode:"+ questmode +")");
						globalFlash.gui.mQuestBook.Show();
						game.gi.mNewQuestManager.RewardOkButtonPressedFromGui(item);
						globalFlash.gui.mQuestBook.Hide();
						if (item.GetQuestDefinition().specialType_string.toString() == "lastQuest") {
							LastQuest = true;
						}
						if (item.GetQuestDefinition().specialType_string.toString() == "firstQuestlastQuest") {
							LastQuest = true;
						}
					}
				});
								
				if(CounterQuestCheck == 3 && !LastQuest)
				{
					game.gi.mQuestClientCallbacks.JustRefresh();
					globalFlash.gui.mQuestBook.Show();
					globalFlash.gui.mQuestBook.Hide();
					CounterQuestCheck = 0;
				}
				CounterQuestCheck++;
			}
		}
		catch(e){game.showAlert(getText('AutoATQuestError', 'SemiAutoATMenuLang'));game.gi.mQuestClientCallbacks.JustRefresh();globalFlash.gui.mQuestBook.Show();globalFlash.gui.mQuestBook.Hide();}

        if (game.gi.mCurrentPlayer.mIsAdventureZone && LastQuest && !game.gi.mPacketLost) {
			safeReset('AttackTimeoutIntern');
			safeReset('MoveTimeoutIntern');
            game.showAlert(getText('LastQuestAuto', 'SemiAutoATMenuLang'));
            WoBinIch = 0;
            LastQuest = false;
			LetzteVorlage = true;
            setTimeout(function () {
                if (ATweitermachen) {
                    ToHeimatInsel();
                }
            }, parseInt(user_fast_shortcut_settings.WarteZeitZwischenZurHeimatinselATEndeSelector));
            return;
        }

        questTimeoutAutoAT = setTimeout(function () {
            if (game.gi.mCurrentPlayer.mIsAdventureZone) {
				checkQuest();
			}
        }, parseInt(user_fast_shortcut_settings.WarteZeitZwischenQuestÜberwachungSelector));
    }
	
	setTimeout(checkQuest, parseInt(user_fast_shortcut_settings.WarteZeitZwischenQuestÜberwachungSelector));
}

function GetQuestSemi() {
	var LastQuest = false;
	var CounterQuestCheck = 0;
	game.gi.mQuestClientCallbacks.JustRefresh();
	globalFlash.gui.mQuestBook.Show();
	globalFlash.gui.mQuestBook.Hide();
    function checkSemiQuest() {
		if(!automatisierung || ATweitermachen || !game.gi.mCurrentPlayer.mIsAdventureZone)
		{
			return;
		}
		
		try{
			if (game.gi.mCurrentPlayer.mIsAdventureZone && game.gi.mNewQuestManager.GetQuestPool().IsAnyQuestsActive() && !ATweitermachen) {
				game.gi.mQuestClientCallbacks.JustRefresh();
				$.each(game.gi.mNewQuestManager.GetQuestPool().GetQuest_vector(), function (i, item) {
					if (item == null || LastQuest)
					{
						return;
					}						
					if (user_fast_shortcut_settings.debugAT) {
						debug(item.GetQuestDefinition());
						debug(item.GetQuestDefinition().specialType_string.toString());
					}
					
					globalFlash.gui.mQuestBook.SetPreselectedQuest(item);

					var questmode = item.GetQuestMode().toString();
					var questname = item.getQuestName_string();					
					
					if (questmode == "2")
					{
						globalFlash.gui.mQuestBook.Show();
						game.gi.mQuestClientCallbacks.QuestOkButtonPressedFromGui(item);
						globalFlash.gui.mQuestBook.Hide();
					}	
					
					if ((questmode == "1" || questmode == "3") && CollectiblesQuestsImAT.indexOf(questname) >= 0) {
						shortcutsPickupAllAT();
					}
					
					//game.showAlert("Quest: " + questname + "(Mode:"+ questmode +")" + " | " + "isFinished:"+item.isFinished());
					if (item.isFinished()) {
                    if (item.GetQuestDefinition().specialType_string.toString() == "lastQuest" || item.GetQuestDefinition().specialType_string.toString() == "firstQuestlastQuest") {
                        LastQuest = true;
                    } else {
                        game.showAlert(getText('QuestFinish', 'SemiAutoATMenuLang') + questname + "(Mode:"+ questmode +")");
						globalFlash.gui.mQuestBook.Show();
                        game.gi.mNewQuestManager.RewardOkButtonPressedFromGui(item);
						globalFlash.gui.mQuestBook.Hide();
                    }
                }
				});
				
				if(CounterQuestCheck == 3 && !LastQuest)
				{
					game.gi.mQuestClientCallbacks.JustRefresh();
					globalFlash.gui.mQuestBook.Show();
					globalFlash.gui.mQuestBook.Hide();
					CounterQuestCheck = 0;
				}
				CounterQuestCheck++;
			}
		}
		catch(e){game.showAlert(getText('SemiQuestError', 'SemiAutoATMenuLang'));game.gi.mQuestClientCallbacks.JustRefresh();globalFlash.gui.mQuestBook.Show();globalFlash.gui.mQuestBook.Hide();}

        if (game.gi.mCurrentPlayer.mIsAdventureZone && LastQuest && !game.gi.mPacketLost) {
			safeReset('AttackTimeoutIntern');
			safeReset('MoveTimeoutIntern');
            game.showAlert(getText('SemiLastQuest', 'SemiAutoATMenuLang'));
            LastQuest = false;
			LetzteVorlage = true;
			GetQuestSemiStarten = true;
            return;
        }

        questTimeoutSemi = setTimeout(function () {
            if (game.gi.mCurrentPlayer.mIsAdventureZone) {
                checkSemiQuest();
            }
        }, parseInt(user_fast_shortcut_settings.WarteZeitZwischenQuestÜberwachungSelector));
    }
	
	setTimeout(checkSemiQuest, parseInt(user_fast_shortcut_settings.WarteZeitZwischenQuestÜberwachungSelector));
}

function shortcutsPickupAllAT() {
    var collectionsManager = swmmo.getDefinitionByName("Collections::CollectionsManager").getInstance(),
        queueshortcutsPickupAllAT = new TimedQueue(1000),
        questTriggersMap = {},
        itemBuildingName, itemGOContainer;
    if (game.gi.mCurrentPlayer.mIsAdventureZone && game.gi.mNewQuestManager.GetQuestPool().IsAnyQuestsActive()) {
		$.each(game.gi.mNewQuestManager.GetQuestPool().GetQuest_vector(), function(i, item) {
			if (item.isFinished() || !item.IsQuestActive()) { return; }
			$.each(item.mQuestDefinition.questTriggers_vector, function(n, trigger) {
				if(trigger.name_string != null && trigger.name_string != '')
					questTriggersMap[trigger.name_string] = true;
			});
		});
    }

    game.zone.mStreetDataMap.GetBuildings_vector().forEach(function(item){
        if (item === null) { return; }
        itemGOContainer = item.GetGOContainer();
        if (
            collectionsManager.getBuildingIsCollectible(item.GetBuildingName_string()) ||
            (
                questTriggersMap[item.GetBuildingName_string()] &&
                item.mIsSelectable &&
                itemGOContainer.mIsAttackable &&
                !itemGOContainer.mIsLeaderCamp &&
                itemGOContainer.ui !== "enemy" &&
                (item.GetArmy() == null || !item.GetArmy().HasUnits())
            )
        ) {
            queueshortcutsPickupAllAT.add(function(){
				game.gi.SelectBuilding(item);
            });
        }
    });

    if (queueshortcutsPickupAllAT.len() === 0) {
        showGameAlert(getText("NoCollectibles"));
        return;
    }
    showGameAlert(getText('command_sent'));
    queueshortcutsPickupAllAT.run();
}

function shortcutsPickupAllATFirstStart() {
    var collectionsManager = swmmo.getDefinitionByName("Collections::CollectionsManager").getInstance(),
        queueshortcutsPickupAllATFirstStart = new TimedQueue(1000),
        questTriggersMap = {},
        itemBuildingName, itemGOContainer;
    if (game.gi.mCurrentPlayer.mIsAdventureZone && game.gi.mNewQuestManager.GetQuestPool().IsAnyQuestsActive()) {
		$.each(game.gi.mNewQuestManager.GetQuestPool().GetQuest_vector(), function(i, item) {
			if (item.isFinished() || !item.IsQuestActive()) { return; }
			$.each(item.mQuestDefinition.questTriggers_vector, function(n, trigger) {
				if(trigger.name_string != null && trigger.name_string != '')
					questTriggersMap[trigger.name_string] = true;
			});
		});
    }

    game.zone.mStreetDataMap.GetBuildings_vector().forEach(function(item){
        if (item === null) { return; }
        itemGOContainer = item.GetGOContainer();
        if (
            collectionsManager.getBuildingIsCollectible(item.GetBuildingName_string()) ||
            (
                questTriggersMap[item.GetBuildingName_string()] &&
                item.mIsSelectable &&
                itemGOContainer.mIsAttackable &&
                !itemGOContainer.mIsLeaderCamp &&
                itemGOContainer.ui !== "enemy" &&
                (item.GetArmy() == null || !item.GetArmy().HasUnits())
            )
        ) {
            queueshortcutsPickupAllATFirstStart.add(function(){
				game.gi.SelectBuilding(item);
            });
        }
    });

    if (queueshortcutsPickupAllATFirstStart.len() === 0) {
        return;
    }
    showGameAlert(getText('command_sent'));
    queueshortcutsPickupAllATFirstStart.run();
}

function ToHeimatInsel()
{
	try {
		menu.nativeMenu.getItemByName("DebugMethoden").label = "ToHeimatInsel()";
		if(!automatisierung)
		{
			return;
		}
		showGameAlert(getText('ToHome', 'SemiAutoATMenuLang'));
		var HomeID = game.player.GetHomeZoneId();
			game.gi.visitZone(HomeID);
			BuffnochAktiv = false;
			if(ATweitermachen == true)
			{
				setTimeout(function() {
					/* game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
					showGameAlert('Auto Zone Refresh (F2)'); */
					RefreshGUIBUI();
					
					if(game.gi.isOnHomzone() == true && user_fast_shortcut_settings.QuestBeenden)
					{
						try{
							$.each(game.gi.mNewQuestManager.GetQuestPool().GetQuest_vector(), function(i, item) {
								
								if(item == null/*  || item.GetQuestDefinition().questName_string.indexOf("GuildFest_") != 0 */)
								{
									return;
								}
								if (user_fast_shortcut_settings.debugAT) {
									debug("ToHeimatInsel - Quest beenden");
									debug(item);}
								if(game.gi.isOnHomzone() == true && item.isFinished()/*  && item.GetQuestDefinition().questName_string.indexOf("GuildFest_") == 0 */)
								{
									game.showAlert(getText('QuestDone', 'SemiAutoATMenuLang'));
									globalFlash.gui.mQuestBook.SetPreselectedQuest(item);
									globalFlash.gui.mQuestBook.Show();
									game.gi.mNewQuestManager.RewardOkButtonPressedFromGui(item);
									globalFlash.gui.mQuestBook.Hide();		
								}
							});
						}catch(e){game.showAlert("Fehler Quest: " + e)};	
					}
					
					if(JZRebuildLosses_settingsAutoFast.autoProd)
					{
						topUpPopulationFastAuto();
						setTimeout(function () {
							checkAndStartProductionFast();
						}, 15000);	
					}
					
					if(game.gi.isOnHomzone() == true && user_fast_shortcut_settings.VorlagenUeberwachungAfterAT)
					{
						EntdeckerAktion();
						/* BuiBuffsAktion();
						BuiProdAktion(); */
					}
					
					if(!automatisierung)
					{
						return;
					}
					
					try{
						var AdvManager = swmmo.getDefinitionByName("com.bluebyte.tso.adventure.logic::AdventureManager").getInstance();
						AdvManager.removeAdventure(LaggyATID);
						/* showGameAlert('Laggy AT entfernt!'); */
					}catch(e){showGameAlert('Konnte Laggy AT nicht entfernen!');}
						setTimeout(function() {
							if(!automatisierung)
							{
								return;
							}
							if(ATweitermachen && automatisierung && RundenanzahlCounter < user_fast_shortcut_settings.RundenanzahlSelector)
							{
								if(user_fast_shortcut_settings.MemUeberwachung)
								{
									if(MemTriggerClientRestart())
									{
										showGameAlert(getText('MemInAT', 'SemiAutoATMenuLang') + humanMemorySize(air.System.privateMemory, 1) + getText('MemInAT2', 'SemiAutoATMenuLang'));
										try{menu.nativeMenu.getItemByName("AutoATRundenanzahl").label = "AutoModus - Speichergrenze erreicht, Neustart demnächst!";}catch(e){}
										user_fast_shortcut_settings_AutoAT.Runde = RundenanzahlCounter;
										AutoATsave();
										ToolingMenuUpdateSzenaMenu(false);
										ToolingMenuUpdateSzenaStoppen(false);
										ToolingMenuUpdateSzenaStarten(false);
										ToolingMenuUpdate(false);
										ToolingMenuUpdateMainMenu(false);
									}
									else
									{
										ATStart();
									}
								}
								else
								{
									ATStart();
								}
							}
							else
							{
								game.showAlert(getText('AutoATStopRoundCount', 'SemiAutoATMenuLang'));
								var event = {
									target: {
										name: getText('DirectShortcutOFF', 'SemiAutoATMenuLang')
									}
								};
								shortcutsAutoFunc(event);
							}
						},parseInt(user_fast_shortcut_settings.WarteZeitZwischenVorlagenSelector)+5000);
					},parseInt(user_fast_shortcut_settings.WarteZeitZwischenATNeustartSelector));			
			}
			
		} catch (error) {
			//alert("Err (retry): " + error.message);
		}
}

function ATStartBuffen()
{
	menu.nativeMenu.getItemByName("DebugMethoden").label = "ATStartBuffen()";
	if(!automatisierung)
	{
		return;
	}
	var BuffGefunden = false;
	if(automatisierung && game.gi.mCurrentPlayer.mIsAdventureZone && ATweitermachen)
	{
		menu.nativeMenu.getItemByName("DebugMethoden").label = "ATStartBuffen() - Hufeisen";
		var MyBuffID;
		var buffVector = [];
		try{
			buffVector = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();
			buffVector.forEach(function(data){
				if(data.GetBuffDefinition().GetName_string() == user_fast_shortcut_settings.buffNameHufeisenSelector) {
					BuffGefunden = true;
					MyBuffID = data.GetUniqueId();
				}
			});
			
			if(user_fast_shortcut_settings.Hufeisenbuffen)
			{
				if(BuffGefunden && !BuffnochAktiv && !game.gi.mZoneBuffManager.isBuffRunning(user_fast_shortcut_settings.buffNameHufeisenSelector))
				{
					game.showAlert(getText('Buffing', 'SemiAutoATMenuLang') + user_fast_shortcut_settings.buffNameHufeisenSelector + " | ID: " + MyBuffID);
					game.gi.SendServerAction(61, 0, 0, 0, MyBuffID);
					BuffnochAktiv = true;
				}
				else
				{
					game.showAlert(getText('BuffNotFound', 'SemiAutoATMenuLang'));
				}
			}
			else
			{
				game.showAlert(getText('BuffNotActivated', 'SemiAutoATMenuLang'));
			}
			timeoutAlreadySet = false;
		}
		catch(e)
		{
			game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
			globalFlash.gui.mStarMenu.Show();
			game.gi.mCurrentPlayer.resetLastFetchedBuff(); 
			game.gi.mCurrentPlayer.forceResortBuffsForStarMenu();
			globalFlash.gui.mStarMenu.Hide();
			if (!timeoutAlreadySet) {
				setTimeout(function () {
					if (ATweitermachen && automatisierung && game.gi.mCurrentPlayer.mIsAdventureZone) {
						ATStartBuffen();
					}
					timeoutAlreadySet = true;
				}, 10000);
			}
		}
	}
	else if(game.gi.isOnHomzone() == true && automatisierung && ATweitermachen)
	{
		menu.nativeMenu.getItemByName("DebugMethoden").label = "ATStartBuffen() - AT Buffen";
		var MyBuffID;
		var buffVector = [];
		try{
			buffVector = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();
			buffVector.forEach(function(data){
				if(data.GetResourceName_string() == user_fast_shortcut_settings.ATAuswahl && data.GetBuffDefinition().GetName_string() == "Adventure") {
					BuffGefunden = true;
					MyBuffID = data.GetUniqueId();
				}
			});
			
			try {
				ATnochAktiv = false;
				var AdvManager = swmmo.getDefinitionByName("com.bluebyte.tso.adventure.logic::AdventureManager").getInstance();
				var Adventures = AdvManager.getAdventures();
				
					if(Adventures[0] !== undefined && game.player.GetPlayerId() == Adventures[0].ownerPlayerID)
					{
						ATnochAktiv = true;
					}
					else if(Adventures[1] !== undefined && game.player.GetPlayerId() == Adventures[1].ownerPlayerID)
					{
						ATnochAktiv = true;
					}	
				} catch (error) {
					ATnochAktiv = true;
				}
				if(BuffGefunden && !ATnochAktiv)
				{
					game.showAlert(getText('Buffing', 'SemiAutoATMenuLang') + user_fast_shortcut_settings.ATAuswahl + " | ID: " + MyBuffID);
					game.gi.SendServerAction(61, 0, 0, 0, MyBuffID);
					ATisRunning();
				}
				else
				{
					ATisRunning();
					game.showAlert(getText('ATNotFound', 'SemiAutoATMenuLang'));
				}
			timeoutAlreadySet = false;
		}
		catch(e)
		{
			game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
			globalFlash.gui.mStarMenu.Show();
			game.gi.mCurrentPlayer.resetLastFetchedBuff(); 
			game.gi.mCurrentPlayer.forceResortBuffsForStarMenu();
			globalFlash.gui.mStarMenu.Hide();
			if (!timeoutAlreadySet) {
				setTimeout(function () {
					if (ATweitermachen && automatisierung && game.gi.isOnHomzone()) {
						ATStartBuffen();
					}
					timeoutAlreadySet = true;
				}, 10000);
			}
		}
	}
}

function ATisRunning()
{
	menu.nativeMenu.getItemByName("DebugMethoden").label = "ATisRunning()";
	var CounterATNotFound = 0;
	function ATisRunningIntern() {
		
		try {
			var ATAktivIntern = false;
			var AdvManager = swmmo.getDefinitionByName("com.bluebyte.tso.adventure.logic::AdventureManager").getInstance();
			var Adventures = AdvManager.getAdventures();			
				if(Adventures[0] !== undefined && game.player.GetPlayerId() == Adventures[0].ownerPlayerID)
				{
					ATAktivIntern = true;
				}
				else if(Adventures[1] !== undefined && game.player.GetPlayerId() == Adventures[1].ownerPlayerID)
				{
					ATAktivIntern = true;
				}	
			} catch (error) {
				ATAktivIntern = false;
				game.showAlert(error);
			}
			
			if(ATAktivIntern)
			{
				menu.nativeMenu.getItemByName("DebugMethoden").label = "ATisRunning() - geht weiter";
				KannWeiterGehenATneustarten = true;
				setTimeout(function () {
                        if (ATweitermachen) {
                            automatisierungBasicATneustarten();
                        }
                    }, 5000);
				CounterATNotFound = 0;
				return;
			}	
			else if(!ATAktivIntern && CounterATNotFound >= 12)
			{
				menu.nativeMenu.getItemByName("DebugMethoden").label = "ATisRunning() - AT nicht gefunden";
				game.showAlert(getText('ErrorATSTartBuff', 'SemiAutoATMenuLang'));
                var event = {
                    target: {
                        name: getText('DirectShortcutOFF', 'SemiAutoATMenuLang')
                    }
                };
                shortcutsAutoFunc(event);
                return;
			}
			CounterATNotFound++;
            setTimeout(ATisRunningIntern, 10000);
        }

        setTimeout(ATisRunningIntern, 10000);
}

