function SearchArchitecturesHandler2(event) {
	if(game.gi.isOnHomzone() == false) {
				game.showAlert(getText('not_home'));
				return;
	}
    $('div[role="dialog"]:not(#searchArchitecturesModal):visible').modal('hide');
    $('#searchArchitecturesModal').remove();
        
    createModalWindow('searchArchitecturesModal', utils.getImageTag('icon_dice.png', '45px') + ' '+ loca.GetText("ALT","UpgradeBuilding"));
	
	building_newTemplates2 = new SaveLoadTemplate('upg2', function(data, name) {
			$("#searchArchitecturesModal .templateFile").html("{0} ({1}: {2})".format('&nbsp;'.repeat(5), loca.GetText("LAB", "AvatarCurrentSelection"), name));
			buildingArrayLoad2 = data;
			var buildingList = _getArchitecturesList2();
			var keys = Object.keys(buildingList);
			keys.sort().forEach(function (key) {	
			buildingList[key].forEach(function (item) {
			var isGridInArray = false;
			for (var i = 0; i < buildingArrayLoad2.length; i++) {
				if (buildingArrayLoad2[i] === item.grid) {
					isGridInArray = true;
					break;
				}
			} 
			if (isGridInArray) {
				$('#_upgradeBuilding2_' + item.building.GetGrid()).prop('checked', true);
				if (isGridInArray) {
					$('#_upgradeBuilding2_' + item.building.GetGrid()).prop('checked', true);
					if (buildingArray2.indexOf(item.building) === -1) {
						buildingArray2.push(item.building);
					}
				}	
			}			
        });
    });
		});
	
    $('#searchArchitecturesModal .modal-header').append(
        '<br><div class="container-fluid" id="searchArchitecturesSelectLevel2"><b>'+loca.GetText("LAB","Filter")+':</b>&emsp; </div>');
    for (i = 1; i <= MAXLEVEL2; i++) {
        $('<label><input type="radio" name="searchArchitecturesRadio2" value={0}> &thinsp;{1}&emsp; </label>'.format(
            i, (i < MAXLEVEL2 ? i : i + '+')
        )).appendTo('#searchArchitecturesSelectLevel2');
    }
    $('<label><input type="radio" name="searchArchitecturesRadio2"  value={0}> &thinsp;{1}&emsp; </label>'.format(
        ALLLEVELS2, loca.GetText("LAB","All")
    )).appendTo('#searchArchitecturesSelectLevel2');
	$('#searchArchitecturesModal .modal-header').append(
        '<br><div class="container-fluid" id="searchArchitecturesSelectLevel22"><b>Max '+ loca.GetText("ALT","UpgradeBuilding") + ' ' + loca.GetText("LAB","GuildLevel") + ' (' +loca.GetText("QUL","GuiDaiAllTheShinyRoadsSub4") + ')' +':</b>&emsp; </div>');
    for (i = 1; i <= MAXLEVEL22; i++) {
        $('<label><input type="radio" name="searchArchitecturesRadio22" value={0}> &thinsp;{1}&emsp; </label>'.format(
            i, (i < MAXLEVEL22 ? i : i)
        )).appendTo('#searchArchitecturesSelectLevel22');
    }
	$('input[name="searchArchitecturesRadio22"][value=' + user_building_extension_settings.maxUpgradeLevelSettingUI + ']').prop('checked', true);
    $('input[name="searchArchitecturesRadio22"]').click(function () {
        user_building_extension_settings.maxUpgradeLevelSettingUI = $(this).val();
		settings.settings['UpgradeBuildingUI'] = {};
		settings.store(user_building_extension_settings, 'UpgradeBuildingUI');
		//game.showAlert(user_building_extension_settings.maxUpgradeLevelSettingUI);
    });
	
    $('#searchArchitecturesModal .modal-header').append(
        '<br><div class="container-fluid" id="searchArchitecturesSelectFound2"><b>'+ loca.GetText("LAB","Search") + ':</b>&emsp;</div>'
    );
	
    $('<input>', {
        'type': 'text', 'id': 'searchArchitecturesFind2', 'class': 'form-control',
        'style': 'display: inline;width: 300px;', 'value': searchStringUpgrade2
    }).appendTo('#searchArchitecturesSelectFound2');
    $('<label>&emsp</label>').appendTo('#searchArchitecturesSelectFound2');
    $('<label><input type="checkbox" id="searchImprovableArchitecturesOnly2"> &thinsp;'+ loca.GetText("LAB","Search") + ': '+ loca.GetText("ALT","UpgradeBuilding") + '&emsp; </label>'
    ).appendTo('#searchArchitecturesSelectFound2');
    $('<label><input type="checkbox" id="searchDestroyableArchitecturesOnly2"> &thinsp;'+ loca.GetText("LAB","Search") + ': '+ loca.GetText("HIL","Help_window_destroyable_mountains_0") + '&emsp; </label>'
    ).appendTo('#searchArchitecturesSelectFound2');
    $('#searchArchitecturesModal .modal-header').append(
    '<br><p style="color:cyan; font-weight:bold;">*Die Farbe Cyan bedeutet das Gebäude ist handelbar</p>' +
    '<div class="container-fluid">' + createTableRow([
        [5, loca.GetText("LAB", "Name")],
        [3, loca.GetText("LAB", "Buffs")],
        [1, ''],
        [2, loca.GetText("LAB", "Status")],
        [1, ''],
    ], true) + '</div>'
);
    $('#searchArchitecturesModal #searchArchitecturesFind2').keyup(function (e) {
        searchStringUpgrade2 = $(e.target).val();
        if (!searchStringUpgrade2 || searchStringUpgrade2 == "") {
            $('#searchArchitecturesModalData .container-fluid div:hidden').show();
            return;
        }
        $('#searchArchitecturesModalData .container-fluid .row').each(function (i, item) {
            if ($(item.firstChild).text().toUpperCase().indexOf(searchStringUpgrade2.toUpperCase()) == -1) {
                $(item).hide();
            } else {
                $(item).show();
            }
        });
    });
    $('input[name="searchArchitecturesRadio2"][value=' + searchLevel2 + ']').prop('checked', true);
    $('input[name="searchArchitecturesRadio2"]').click(function () {
        searchLevel2 = $(this).val();
        _updateArchitecturesModalData2();
    });
    $('#searchImprovableArchitecturesOnly2').prop('checked', improvableOnlyShow2);
    $('#searchImprovableArchitecturesOnly2').click(function () {
        improvableOnlyShow2 = $('#searchImprovableArchitecturesOnly2').is(':checked');
        _updateArchitecturesModalData2();
    });
    $('#searchDestroyableArchitecturesOnly2').prop('checked', destroyableOnlyShow2);
    $('#searchDestroyableArchitecturesOnly2').click(function () {
        destroyableOnlyShow2 = $('#searchDestroyableArchitecturesOnly2').is(':checked');
        _updateArchitecturesModalData2();
    });
    _updateArchitecturesModalData2();
    $('#searchArchitecturesModal:not(:visible)').modal({ backdrop: 'static' });

	$("#searchArchitecturesModal .modal-footer").prepend([
	$('<button>').attr({ "class": "btn btn-warning upgradeReset" }).text(getText('btn_reset')),
	$('<button>').attr({ "class": "btn btn-success upgradeSubmit" }).text(getText('btn_submit')),	
	]);
			
	$("#searchArchitecturesModal .modal-footer").prepend([
	$('<button>').attr({ "class": "btn btn-primary pull-left building_newSaveTemplate2" }).text(getText('save_template')),
	$('<button>').attr({ "class": "btn btn-primary pull-left building_newLoadTemplate2" }).text(getText('load_template'))
	]);		
			
		$('#searchArchitecturesModal .upgradeReset').click(function() {
			buildingArray2 = [];
			buildingArraySave2 = [];
			buildingArrayLoad2 = [];
			_updateArchitecturesModalData2();
		});
		$('#searchArchitecturesModal .upgradeSubmit').click(function() {
			$('#searchArchitecturesModal').modal('hide');

			if(buildingArray2.length === 0)
			{
				//game.showAlert('buildingArray2 leer');
			}
			else if(buildingArray2.length !== 0)
			{
				//game.showAlert('buildingArray2 nicht leer');
				setTimeout(function() {upgradeBuildingForClientArrayUI2(buildingArray2);},2000);		
			}			
		});
		$('#searchArchitecturesModal .building_newSaveTemplate2').click(function(){ 
			buildingArraySave2 = [];
			$.each(buildingArray2, function(i, building) {
				
				if (buildingArraySave2.indexOf(building.GetGrid()) === -1) {
					buildingArraySave2.push(building.GetGrid());
				}
				
			});
			building_newTemplates2.save(buildingArraySave2);
		});
		$('#searchArchitecturesModal .building_newLoadTemplate2').click(function() { 
			building_newTemplates2.load();
			
	
		});
		$("#searchArchitecturesModal .btnClose").click(function(e) { 
			buildingArray2 = [];
			buildingArraySave2 = [];
			buildingArrayLoad2 = [];
			$('#searchArchitecturesModal').modal('hide');
		});
}

function _updateArchitecturesModalData2() {
    var buildingList = _getArchitecturesList2();
    $('#searchArchitecturesModalData').html(_searchArchitecturesModal2(buildingList));
    var keys = Object.keys(buildingList);
    keys.sort().forEach(function (key) {
        buildingList[key].forEach(function (item) {
            if (item.goto != '')
                document.getElementById('buildPOSBuild2_' + item.grid).addEventListener(
                    'click', function () { _buildingViewerGoTo2(item.grid, item.building); }
                );
        });
    });
    $('#searchArchitecturesModalData .container-fluid .row').each(function (i, item) {
        if ($(item.firstChild).text().toUpperCase().indexOf(searchStringUpgrade2.toUpperCase()) == -1) {
            $(item).hide();
        } else {
            $(item).show();
        }
    });
}

function _getArchitecturesList2() {
    var buildingList = {};
    swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.mBuildingContainer.forEach(function (item) {
        if (item.isGarrison()) { return; }
        var isDestroyableMountain = item.IsDestroyableMountain();
        if (isDestroyableMountain != destroyableOnlyShow2) { return; }
        var level = item.GetUIUpgradeLevel();
        if (!(searchLevel2 == MAXLEVEL2 && level >= MAXLEVEL2 || searchLevel2 == level || searchLevel2 == ALLLEVELS2)) { return; }
        var grid = item.GetGrid();
        var buildingGoto = '';
        if (grid > 0)
            buildingGoto = getImageTag('accuracy.png', '24px', '24px').replace(
                '<img', '<img id="buildPOSBuild2_' + grid + '"'
            ).replace('style="', 'style="cursor: pointer;');
        var name = item.GetBuildingName_string();
        if (
            name.toUpperCase().indexOf('EW_') != -1 ||
            name.toUpperCase().indexOf('DECORATION_MOUNTAIN_PEAK') != -1 ||
            name.toUpperCase().indexOf('BANDITS') != -1
        ) { return; }
        var isUpgradeAllowed = item.IsUpgradeAllowed(true) && !isDestroyableMountain && !_findBuildingType2(item, ['decoration', 'minimal', 'enemy']);
        if (improvableOnlyShow2 && !isUpgradeAllowed) { return; }
        var locName = loca.GetText('BUI', name);
        if (locName.indexOf(UNDEFINED_TEXT2) >= 0) {
            locName = name;
        }
        if (buildingList[locName] === undefined) {
            buildingList[locName] = new Array();
        }
		
		var Glob = swmmo.getDefinitionByName("global");
		var BuiNr = game.zone.GetBuildingFromGridPosition(grid).GetBuildingNrFromName();
		var tradeable = Glob.buildingGroup.mGOList_vector[BuiNr].isTradable();
 
        var buff = '';
        if (item.productionBuff != null) {
            buff = loca.GetText("RES", item.productionBuff.GetBuffDefinition().GetName_string());
        }
        buildingList[locName].push({
            'grid': grid,
            'name': name,
            'goto': buildingGoto,
            'locName': locName,
            'level': level,
            'building': item,
            'isWorking': item.IsProductionActive(),
            'isUpgradeInProgress': item.IsUpgradeInProgress(),
            'isUpgradeAllowed': isUpgradeAllowed,
            'buff': buff,
			'tradeable': tradeable
        });
    });
    return buildingList
}

function _getArchitecturesList22() {
    var buildingListAuto = {};
    swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.mBuildingContainer.forEach(function (item) {
        try {
            if (item.isGarrison()) { return; }

            var isDestroyableMountain = item.IsDestroyableMountain();
            if (isDestroyableMountain) { return; }

            var level = item.GetUIUpgradeLevel();
            if (level >= user_fast_shortcut_settings.AusbauStufeSelector) { return; }

            var name = item.GetBuildingName_string();
            if (
                name.toUpperCase().indexOf('EW_') != -1 ||
                name.toUpperCase().indexOf('DECORATION_MOUNTAIN_PEAK') != -1 ||
                name.toUpperCase().indexOf('BANDITS') != -1
            ) { return; }

			var grid = item.GetGrid();
			
            var isUpgradeAllowed = item.IsUpgradeAllowed(true);
            if (!isUpgradeAllowed) { return; }

            var Glob = swmmo.getDefinitionByName("global");
            var BuiNr = game.zone.GetBuildingFromGridPosition(grid).GetBuildingNrFromName();
			var locName = loca.GetText('BUI', name);
			if (locName.indexOf(UNDEFINED_TEXT2) >= 0) {
				locName = name;
			}
			if (buildingListAuto[locName] === undefined) {
				buildingListAuto[locName] = new Array();
			}

            buildingListAuto[locName].push({
                'grid': grid,
                'building': item
            });
        } catch (error) {
            game.showAlert("Fehler beim Verarbeiten des Gebäudes: " + error);
            return;
        }
    });
    return buildingListAuto;
}

function _buildingViewerGoTo2(g, b) {
    try {
        $('#searchArchitecturesModal').modal('hide');
        swmmo.application.mGameInterface.mCurrentPlayerZone.ScrollToGrid(g);
        swmmo.application.mGameInterface.SelectBuilding(b)
    }
    catch (e) { }
}

function _findBuildingType2(b, bTypes) {
    var panelClass = globalFlash.gui.GetInfoPanel(b.GetBuildingName_string());
    var className = window.runtime.flash.utils.getQualifiedClassName(panelClass);
    var found = false;
    for (t in buildingTypeInfoPanelMap2) {
        if (bTypes.indexOf(t) >= 0){
            found = found || (className == 'GUI.GAME::{0}'.format(buildingTypeInfoPanelMap2[t]));
        }
    }
    return found;
}

function _searchArchitecturesModal2(buildingList) {
    var out = '<div class="container-fluid">';
    try {
        var keys = Object.keys(buildingList);
        keys.sort().forEach(function (key) {
            var buildingCount = buildingList[key].length,
                firstItem = buildingList[key][0],
                prefix = '&#9500',
                counter = 1;
            out += createTableRow([
                [12, '<b>' + firstItem.locName + '</b>' + (DEBUG2 ? ' <sup>' + firstItem.name + '</sup>' : '')],
            ]);
            buildingList[key].sort(_compareArchitecturesByLevel2).forEach(function (item) {
                _checkboxupgradBuilding2_ = '<input type="checkbox" id="_upgradeBuilding2_' +  item.building.GetGrid()  + '" />'.format(item.building);
                if (counter == buildingCount) {
                    prefix = '&#9492;';
                }
                itemStatus = '';
                if (!item.isWorking) {
                    itemStatus = 'Gestoppt';
                }
                if (item.isUpgradeInProgress) {
                    itemStatus = 'wird ausgebaut'
                }
                out += createTableRow([
                    [5, prefix +
						(itemStatus === '' ? '' : '<span style="color:LightGray;font-style:italic;">') +
						'<sup>' + item.level + '</sup>&thinsp;' +
						'<span style="color:' + (item.tradeable ? 'cyan' : 'white') + ';">' +  // Conditional color
						item.locName + " (Grid: " + item.grid + ")" +
						'</span>' + 
						(itemStatus === '' ? '' : '</span>')
					],
                    [3, (itemStatus == '' ? ' ' : ' <span style="color:LightGray;font-style:italic;">') +
                        '<small>' + item.buff + '</small>' + (itemStatus == '' ? '' : '</span>')],
                    [1, item.isUpgradeAllowed ?  _checkboxupgradBuilding2_ : ''],
                    [2, '<span style="color:LightGray;font-style:italic;"><small>' + itemStatus + '</small></span>'],
                    [1, item.goto]
                ]);
                

				
				$(document).on('click', '#_upgradeBuilding2_'+ item.building.GetGrid(), function () {
					var isChecked = $('#_upgradeBuilding2_' + item.building.GetGrid()).prop('checked');

					if (buildingArray2.indexOf(item.building) === -1 && isChecked) {
						buildingArray2.push(item.building);
						
					}
					else if(buildingArray2.indexOf(item.building) !== -1 && !isChecked)
					{
						var index = buildingArray2.indexOf(item.building);
						buildingArray2.splice(index, 1);
					}
				});

				counter++;
            });
        });
    } catch (e) {
        out += '<p>Error: ' + e + '/<p>';
    }
    out += '</div>';

    return out;
}


function _compareArchitecturesByLevel2(a, b) {
    if (a.level < b.level) return -1;
    if (a.level > b.level) return 1;
    return 0;
}

function upgradeBuildingForClientArray2(buildingArray_input) { 
	var x = new TimedQueue(1000);
	$.each(buildingArray_input, function(i, building) {
		if (building.GetUIUpgradeLevel() < user_fast_shortcut_settings.AusbauStufeSelector && building.IsBuildingInProduction() && !building.IsUpgradeInProgress() ) {
			var isDeplete = false;
			try
			{
				isDeplete = swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.IsADepletedDeposit(game.zone.GetBuildingFromGridPosition(building.GetGrid()));
			}
			catch(e)
			{
				isDeplete = false;
			}
			/* debug(building);
			debug("isDeplete: " + isDeplete); */
			var isUpgradeAllowed_tmp = building.IsUpgradeAllowed(true);
			if (isUpgradeAllowed_tmp && !isDeplete) {
				x.add(function() { 
					if (isUpgradeAllowed_tmp && !isDeplete && game.gi.isOnHomzone() == true) {
						game.gi.SendServerAction(60,  0, building.GetGrid(), 0, null);
					};
				}); 
			};
		}
		
	});
	x.run();
	buildingArray_input = [];
	buildingArray2 = [];
}

function upgradeBuildingForClientArrayUI2(buildingArray_input) { 
	var x = new TimedQueue(1000);
	$.each(buildingArray_input, function(i, building) {
		if (building.GetUIUpgradeLevel() < user_building_extension_settings.maxUpgradeLevelSettingUI && building.IsBuildingInProduction() && !building.IsUpgradeInProgress() ) {
			var isDepleteUI = swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.IsADepletedDeposit(game.zone.GetBuildingFromGridPosition(building.GetGrid()));
			/* debug(building);
			debug("isDepleteUI: " + isDepleteUI); */
			var isUpgradeAllowed_tmp = building.IsUpgradeAllowed(true);
			if (isUpgradeAllowed_tmp && !isDepleteUI) {
				x.add(function() { 
					if (isUpgradeAllowed_tmp && !isDepleteUI && game.gi.isOnHomzone() == true) {
						game.gi.SendServerAction(60,  0, building.GetGrid(), 0, null);
					};
				}); 
			};
		}
		
	});
	x.run();
	buildingArray_input = [];
	buildingArray2 = [];
}

