function SearchZoneBuffHandler2(event) {
    $('div[role="dialog"]:not(#searchZoneBuffModal):visible').modal('hide');
    $('#searchZoneBuffModal').remove();
        
    createModalWindow('searchZoneBuffModal', utils.getImageTag('icon_dice.png', '45px') + ' '+ loca.GetText("HIL", "Help_window_zonebuffs_0"));

    zoneBuff_newTemplates2 = new SaveLoadTemplate('zonebuff2', function (data, name) {
        $("#searchZoneBuffModal .templateFile").html("{0} ({1}: {2})".format('&nbsp;'.repeat(5), loca.GetText("LAB", "AvatarCurrentSelection"), name));
        zoneBuffArrayLoad2 = data;
        var ZoneBuffList2 = _getZoneBuffList2();
        ZoneBuffList2.forEach(function (item) {
        var isBuffInArray = false;
        for (var i = 0; i < zoneBuffArrayLoad2.length; i++) {
             if (zoneBuffArrayLoad2[i] === item.zonebuffname) {
                  isBuffInArray = true;
                  break;
                 }
             }
                if (isBuffInArray) {
                    $('#_Zonenbuffs2_' + item.zonebuffname).prop('checked', true);
                    if (isBuffInArray) {
                        $('#_Zonenbuffs2_' + item.zonebuffname).prop('checked', true);
                        if (zoneBuffArray2.indexOf(item.zonebuffname) === -1) {
                            zoneBuffArray2.push(item.zonebuffname);
                        }
                    }
                }
            });
    });


    $('#searchZoneBuffModal .modal-header').append(
        '<br><div class="container-fluid" id="searchZoneBuffSelectFound2"><b>' + loca.GetText("LAB", "Search") + ':</b>&emsp;</div>');

    $('<input>', {
        'type': 'text',
        'id': 'searchZoneBuffFind2',
        'class': 'form-control',
        'style': 'display: inline;width: 300px;',
        'value': searchStringZB2
    }).appendTo('#searchZoneBuffSelectFound2');
    $('<label>&emsp</label>').appendTo('#searchZoneBuffSelectFound2');
   
    $('#searchZoneBuffModal .modal-header').append('<br><div class="container-fluid">' + createTableRow([
                [5, loca.GetText("LAB", "Name")],
                [4, loca.GetText("LAB", "amount")],
                [3, loca.GetText("LAB", "Status")]
            ], true) + '</div>');
    $('#searchZoneBuffModal #searchZoneBuffFind2').keyup(function (e) {
        searchStringZB2 = $(e.target).val();
        if (!searchStringZB2 || searchStringZB2 == "") {
            $('#searchZoneBuffModalData .container-fluid div:hidden').show();
            return;
        }
        $('#searchZoneBuffModalData .container-fluid .row').each(function (i, item) {
            if ($(item.firstChild).text().toUpperCase().indexOf(searchStringZB2.toUpperCase()) == -1) {
                $(item).hide();
            } else {
                $(item).show();
            }
        });
    });
    _updateZoneBuffModalData2();
    $('#searchZoneBuffModal:not(:visible)').modal({
        backdrop: 'static'
    });

    $("#searchZoneBuffModal .modal-footer").prepend([
            $('<button>').attr({
                "class": "btn btn-warning upgradeReset"
            }).text(getText('btn_reset')),
            $('<button>').attr({
                "class": "btn btn-success upgradeSubmit"
            }).text(getText('btn_submit')),
        ]);

    $("#searchZoneBuffModal .modal-footer").prepend([$('<button>').attr({
    "class": "btn btn-primary pull-left zoneBuff_newSaveTemplate2"
    }).text(getText('save_template')),
    $('<button>').attr({
    "class": "btn btn-primary pull-left zoneBuff_newLoadTemplate2"
    }).text(getText('load_template'))
    ]);

    $('#searchZoneBuffModal .upgradeReset').click(function () {
        zoneBuffArray2 = [];
        zoneBuffArraySave2 = [];
        zoneBuffArrayLoad2 = [];
        _updateZoneBuffModalData2();
    });
    $('#searchZoneBuffModal .upgradeSubmit').click(function () {
        $('#searchZoneBuffModal').modal('hide');

        if (zoneBuffArray2.length === 0) {
            game.showAlert(getText('ZoneBuffListEmpty', 'SemiAutoATMenuLang'));
        } else if (zoneBuffArray2.length !== 0) {
            setTimeout(function () {
                ZoneBuffForClientArray2(zoneBuffArray2);
            }, 1000);
        }
    });
    $('#searchZoneBuffModal .zoneBuff_newSaveTemplate2').click(function () {
        zoneBuffArraySave2 = [];
        $.each(zoneBuffArray2, function (i, zoneBuff) {
            if (zoneBuffArraySave2.indexOf(zoneBuff) === -1) {
                zoneBuffArraySave2.push(zoneBuff);
            }

        });
        zoneBuff_newTemplates2.save(zoneBuffArraySave2);
    });
    $('#searchZoneBuffModal .zoneBuff_newLoadTemplate2').click(function () {
        zoneBuff_newTemplates2.load();

    });
    $("#searchZoneBuffModal .btnClose").click(function (e) {
        zoneBuffArray2 = [];
        zoneBuffArraySave2 = [];
        zoneBuffArrayLoad2 = [];
        $('#searchZoneBuffModal').modal('hide');
    });
}

function _updateZoneBuffModalData2() {
    var ZoneBuffList2 = _getZoneBuffList2();
    $('#searchZoneBuffModalData').html(_searchZoneBuffModal2(ZoneBuffList2));
    $('#searchZoneBuffModalData .container-fluid .row').each(function (i, item) {
        if ($(item.firstChild).text().toUpperCase().indexOf(searchStringZB2.toUpperCase()) == -1) {
            $(item).hide();
        } else {
            $(item).show();
        }
    });
}

function _getZoneBuffList2() {
    var ZoneBuffList2 = [];

    var buffVector = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();

    buffVector.forEach(function (data) {
        if (data.GetBuffDefinition().GetBuffType() == 8 && data.GetBuffDefinition().GetName_string() != "ChangeColorScheme") {
            var name = data.GetBuffDefinition().GetName_string();
			var buffobject = data.GetBuffDefinition();
			var amount = data.GetAmount();
            var buff = {
                'zonebuffname': name,
				'zoneBuff' : buffobject,
				'zoneBuffamount' : amount
            };

            ZoneBuffList2.push(buff);
        }
    });
    return ZoneBuffList2;
}

function _searchZoneBuffModal2(ZoneBuffList2) {
	
    var out = '<div class="container-fluid">';
    try {
         ZoneBuffList2.forEach(function (item) {
                _checkboxZonenbuffs2_ = '<input type="checkbox" id="_Zonenbuffs2_' + item.zonebuffname + '" />'.format(item.zonebuffname);

                out += createTableRow([
                        [5, loca.GetText("RES", item.zonebuffname)],
                        [4, item.zoneBuffamount],
						[3, _checkboxZonenbuffs2_ ]
                    ]);

                $(document).on('click', '#_Zonenbuffs2_' + item.zonebuffname, function () {
                    var isChecked = $('#_Zonenbuffs2_' + item.zonebuffname ).prop('checked');

                    if (zoneBuffArray2.indexOf(item.zonebuffname) === -1 && isChecked) {
                        zoneBuffArray2.push(item.zonebuffname);

                    } else if (zoneBuffArray2.indexOf(item.zonebuffname) !== -1 && !isChecked) {
                        var index = zoneBuffArray2.indexOf(item.zonebuffname);
                        zoneBuffArray2.splice(index, 1);
                    }
                });

            });
    } catch (e) {
    }
    out += '</div>';

    return out;
}

function ZoneBuffForClientArray2(zoneBuffArray_input2) {
    var x = new TimedQueue(1000);
    $.each(zoneBuffArray_input2, function (i, zoneBuff) {
		
	var BuffGefunden = false;
	if(game.gi.mZoneBuffManager.isBuffRunning(zoneBuff))
    {
		game.showAlert(loca.GetText("QTG", "buffactive") + " - " + loca.GetText("RES", zoneBuff));
    }
	else if(zoneBuff.indexOf("GeneralSpeedBuff_") !== -1 && !game.gi.IsAdventureZone() )
	{
		game.showAlert(loca.GetText("ACL", "HomeIsland") + " " + loca.GetText("RES", zoneBuff) + " " +loca.GetText("LAB", "NotAvailableText"));
	}
	else if(zoneBuff.indexOf("MultiplierBuffZone2_PremiumFriendBuff1Day") !== -1 && game.gi.isOnHomzone() )
	{
		game.showAlert(loca.GetText("ACL", "HomeIsland") + " " + loca.GetText("SHI", "MultiplierBuffZone2_PremiumFriendBuff1Day") + " " +loca.GetText("LAB", "NotAvailableText"));
	}
    else
    {
		var MyBuffID;
		var buffVector = [];
		buffVector = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();
		buffVector.forEach(function(data){
			if(data.GetBuffDefinition().GetName_string() == zoneBuff) {
				//debug(data);
				BuffGefunden = true;
				MyBuffID = data.GetUniqueId();
			}
		});
		if(BuffGefunden)
		{
			x.add(function () {
			game.showAlert(loca.GetText("LAB", "Buffs") + ": " + loca.GetText("RES", zoneBuff));
			game.gi.SendServerAction(61, 0, 0, 0, MyBuffID);
			});
		}
		else
		{
			game.showAlert(loca.GetText("LAB", "Buffs") + " " +loca.GetText("LAB", "NotAvailableText"));
		}		
	}
    });
    x.run();
    zoneBuffArray_input2 = [];
    zoneBuffArray2 = [];
}

