function BookbinderGrid()
{
	try{
		game.zone.mStreetDataMap.GetBuildings_vector().forEach(function(item){
			if (item === null) { return; }
			if(item.GetBuildingName_string() == "Bookbinder")
			{
				BookbinderGridInt = item.GetGrid();
				
			}
		});
	}
	catch(e)
	{
		game.showAlert(getText('BookbinderGridError', 'SemiAutoATMenuLang'));
		user_fast_shortcut_settings.VorlagenUeberwachungBookbinder = false;
	}
}

function BookbinderHandle()
{
	try{
		if(game.gi.isOnHomzone() == true && user_fast_shortcut_settings.VorlagenUeberwachungBookbinder)
		{
			var prodQueue0 = swmmo.application.mGameInterface.mCurrentPlayerZone.GetProductionQueue(2);
			for(var i = 0; i < prodQueue0.mTimedProductions_vector.length; i++){
				
				var item = prodQueue0.mTimedProductions_vector[i];
				var productionVO = item.GetProductionOrder().GetProductionVO();
			};
			
			if(productionVO.producedItems == 0)
			{
				game.showAlert(getText('BookNotReady', 'SemiAutoATMenuLang'));
			}

			var cPlayerDataEnoughRess = swmmo.application.mGameInterface.mHomePlayer;
			var EnoughRess = swmmo.application.mGameInterface.mCurrentPlayerZone.GetResources(cPlayerDataEnoughRess);
			var EnoughRessBool = true;
			if(user_fast_shortcut_settings.BookbinderSelector == "Manuscript")
			{
				$.each(EnoughRess.GetResources_Vector(), function(i, item) {
						switch(item.name_string) {
							case 'SimplePaper':
								if(item.amount < 590)
									EnoughRessBool = false;
							break;
							case 'Nib':
								if(item.amount < 470)
									EnoughRessBool = false;
							break;
							case 'Coin':
								if(item.amount < 24)
									EnoughRessBool = false;
							break;								
						}
				});
			}
			else if(user_fast_shortcut_settings.BookbinderSelector == "Tome") 
			{
				$.each(EnoughRess.GetResources_Vector(), function(i, item) {
						switch(item.name_string) {
							case 'IntermediatePaper':
								if(item.amount < 605)
									EnoughRessBool = false;
							break;
							case 'Letter':
								if(item.amount < 415)
									EnoughRessBool = false;
							break;
							case 'Manuscript':
								if(item.amount < 5)
									EnoughRessBool = false;
							break;								
						}
				});
			}
			else if(user_fast_shortcut_settings.BookbinderSelector == "Codex") 
			{
				$.each(EnoughRess.GetResources_Vector(), function(i, item) {
						switch(item.name_string) {
							case 'AdvancedPaper':
								if(item.amount < 375)
									EnoughRessBool = false;
							break;
							case 'BookFitting':
								if(item.amount < 300)
									EnoughRessBool = false;
							break;
							case 'Tome':
								if(item.amount < 2)
									EnoughRessBool = false;
							break;								
						}
				});
			}

			if(productionVO.producedItems == 1)
			{
				var prodQueue4 = swmmo.application.mGameInterface.mCurrentPlayerZone.GetProductionQueue(2); 
				var cPlayerData = swmmo.application.mGameInterface.mHomePlayer;
				var IncCollectedTime = true;
				prodQueue4.finishProduction(cPlayerData, IncCollectedTime);
				game.gi.mClientMessages.SendMessagetoServer(141, game.gi.mCurrentViewedZoneID, 2);
				game.showAlert(getText('BookCollected', 'SemiAutoATMenuLang'));
				if(EnoughRessBool)
				{
					setTimeout(function() {
					
						var dTimedProductionVO = swmmo.getDefinitionByName("Communication.VO::dTimedProductionVO");
						var timedProductionVO = new dTimedProductionVO();
						timedProductionVO.productionType = 2;
						timedProductionVO.type_string = user_fast_shortcut_settings.BookbinderSelector;
						timedProductionVO.amount = 1;
						timedProductionVO.stacks = 1;
						timedProductionVO.buildingGrid = BookbinderGridInt;
						if(game.gi.isOnHomzone() == true)
						{
							game.gi.mClientMessages.SendMessagetoServer(91, game.gi.mCurrentViewedZoneID, timedProductionVO);
							game.showAlert(getText('BookNew', 'SemiAutoATMenuLang'));
						}
					},10000);
				}
				else
				{
					game.showAlert(getText('BookbinderNotStarted', 'SemiAutoATMenuLang'));
				}
			}
		}
	}
	catch(e) 
	{
		if(game.gi.isOnHomzone() == true && user_fast_shortcut_settings.VorlagenUeberwachungBookbinder)
		{
			var cPlayerDataEnoughRess = swmmo.application.mGameInterface.mHomePlayer;
			var EnoughRess = swmmo.application.mGameInterface.mCurrentPlayerZone.GetResources(cPlayerDataEnoughRess);
			var EnoughRessBool = true;
			if(user_fast_shortcut_settings.BookbinderSelector == "Manuscript")
			{
				$.each(EnoughRess.GetResources_Vector(), function(i, item) {
						switch(item.name_string) {
							case 'SimplePaper':
								if(item.amount < 590)
									EnoughRessBool = false;
							break;
							case 'Nib':
								if(item.amount < 470)
									EnoughRessBool = false;
							break;
							case 'Coin':
								if(item.amount < 24)
									EnoughRessBool = false;
							break;								
						}
				});
			}
			else if(user_fast_shortcut_settings.BookbinderSelector == "Tome") 
			{
				$.each(EnoughRess.GetResources_Vector(), function(i, item) {
						switch(item.name_string) {
							case 'IntermediatePaper':
								if(item.amount < 605)
									EnoughRessBool = false;
							break;
							case 'Letter':
								if(item.amount < 415)
									EnoughRessBool = false;
							break;
							case 'Manuscript':
								if(item.amount < 5)
									EnoughRessBool = false;
							break;								
						}
				});
			}
			else if(user_fast_shortcut_settings.BookbinderSelector == "Codex") 
			{
				$.each(EnoughRess.GetResources_Vector(), function(i, item) {
						switch(item.name_string) {
							case 'AdvancedPaper':
								if(item.amount < 375)
									EnoughRessBool = false;
							break;
							case 'BookFitting':
								if(item.amount < 300)
									EnoughRessBool = false;
							break;
							case 'Tome':
								if(item.amount < 2)
									EnoughRessBool = false;
							break;								
						}
				});
			}
			if(EnoughRessBool)
			{
				game.showAlert(getText('BookNew2', 'SemiAutoATMenuLang'));
				var dTimedProductionVO = swmmo.getDefinitionByName("Communication.VO::dTimedProductionVO");
				var timedProductionVO = new dTimedProductionVO();
				timedProductionVO.productionType = 2;
				timedProductionVO.type_string = user_fast_shortcut_settings.BookbinderSelector;
				timedProductionVO.amount = 1;
				timedProductionVO.stacks = 1;
				timedProductionVO.buildingGrid = BookbinderGridInt;
				if(game.gi.isOnHomzone() == true)
				{
					game.gi.mClientMessages.SendMessagetoServer(91, game.gi.mCurrentViewedZoneID, timedProductionVO);
				}
			}
			else
			{
				game.showAlert(getText('BookbinderNotStarted', 'SemiAutoATMenuLang'));
			}
		}
	}
}

