function DepositDepletedGetDataAuto() {
	DepositAll2 = [];
	DepletedAll2 = [];
	var Deposits = swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.mDepositContainer;
    var sDep = new Array();
    Deposits.forEach(function (item) {
            if (assetsNamesMine2.indexOf(item.GetName_string()) !== -1) {
                sDep.push(item);
            }
        });
    Deposits = sDep;
	DepositAll2 = Deposits;
	
	var Depleted = new Array();
    swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.mBuildingContainer.forEach(function (item) {
        try {
            if (swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.IsADepletedDeposit(item)) {
				if (item == null || assetsNames2.indexOf(item.GetBuildingName_string()) === -1) {
                    return;
                }
                Depleted.push({
                    "Item": item,
                    "Resource": _FindOriginalResource2(item.GetBuildingName_string())
                });
            }
        } catch (edep) {}
    });
	
	DepletedAll2 = Depleted;
}

function DepositDepletedGetData2() {

	buildArray2 = [];
	DepositAll2 = [];
    DepletedAll2 = [];
	
    $('#DepositDepletedResult2').html("");
    var out = '';
	var buildingGoto = '';
    var Deposits = swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.mDepositContainer;
        var sDep = new Array();
        Deposits.forEach(function (item) {

            if (assetsNamesMine2.indexOf(item.GetName_string()) !== -1) {
                sDep.push(item);
            }
        });
        Deposits = sDep;
        Deposits.sort(function (a, b) {
            return loca.GetText("RES", a.GetName_string()).localeCompare(loca.GetText("RES", b.GetName_string()));
        });

        Deposits.forEach(function (item) {
            try {
				//debug(game.zone.mStreetDataMap.GetBuildingByGridPos(item.GetGrid()).GetBuildingNrFromName());
                var building_built = null;
				var buildingInfo = '(' + loca.GetText("LAB", "DetailsDeposit") + ')';
                var building_built = game.zone.GetBuildingFromGridPosition(item.GetGrid());
				_checkboxRebuildMines2_ = '<input type="checkbox" id="_RebuildMines2_' + item.GetGrid() + '" />'.format(item.GetGrid());
				if ( building_built !== null ){
					buildingInfo = getText('MineAllreadyBuild', 'SemiAutoATMenuLang');
					_checkboxRebuildMines2_ = '<input type="checkbox" class="mineNotAvailable" id="_RebuildMines2_' + item.GetGrid() + '" />'.format(item.GetGrid());
				}

				//document.getElementById('buildPOSMine2_' + item.grid).addEventListener('click', function () { _GoTo2(item.grid, item.building); });
				buildingGoto = getImageTag('accuracy.png', '24px', '24px').replace('<img', '<img id="buildPOSMine2_' + item.GetGrid() + '"').replace('style="', 'style="cursor: pointer;');
                $('#DepositDepletedResult2').append(
                    createTableRow([
                            [4, loca.GetText("RES", item.GetName_string()) + ' '+  buildingInfo],
                            [2, item.GetAmount()],
							[2, item.GetGrid()],
							[3, _checkboxRebuildMines2_],
							[1, '<div style="text-align: right;">' +  buildingGoto + '</div>']
                        ], false));
            } catch (e) {
                //alert(e.message);
            }
			if (buildingGoto != "")
			{
				document.getElementById("buildPOSMine2_" + item.GetGrid()).addEventListener("click",function() {_GoTo2(item.GetGrid());});
			}			
            $(document).on('click', '#_RebuildMines2_' + item.GetGrid(), function () {
				
                var isChecked = $('#_RebuildMines2_' + item.GetGrid()).prop('checked');
				
                if (buildArray2.indexOf(item) === -1 && isChecked) {
                    buildArray2.push(item);
                } else if (buildArray2.indexOf(item) !== -1 && !isChecked) {
                    var index = buildArray2.indexOf(item);
                    buildArray2.splice(index, 1);
                }
            });
        });
		DepositAll2 = Deposits;

    var Depleted = new Array();
    swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.mBuildingContainer.forEach(function (item) {
        try {
            if (swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.IsADepletedDeposit(item)) {
				if (item == null || assetsNames2.indexOf(item.GetBuildingName_string()) === -1) {
                    return;
                }
                Depleted.push({
                    "Item": item,
                    "Resource": _FindOriginalResource2(item.GetBuildingName_string())
                });
            }
        } catch (edep) {}
    });

    Depleted.sort(function (a, b) {
        return a.Resource.localeCompare(b.Resource);
    });

    Depleted.forEach(function (i) {
        try {
            var IconMap = "";
            if (i.Item.GetGrid() > 0)
				_checkboxRebuildMines2_ = '<input type="checkbox" id="_RebuildMines2_' + i.Item.GetGrid() + '" class="mineNotAvailable" />'.format(i.Item.GetGrid());
				buildingGoto = getImageTag('accuracy.png', '24px', '24px').replace('<img', '<img id="buildPOSMine2_' +  i.Item.GetGrid() + '"').replace('style="', 'style="cursor: pointer;');
                    $('#DepositDepletedResult2').append(
                        createTableRow([
                                [4, loca.GetText("BUI", i.Item.GetBuildingName_string()) + (i.Resource == "" ? "" : " (" + i.Resource + ")")],
                                [2, ""],
								[2, i.Item.GetGrid()],
								[3, _checkboxRebuildMines2_],
								[1, '<div style="text-align: right;">' +  buildingGoto + '</div>']
                            ], false));
        } catch (e) {}
		if (buildingGoto != "")
		{
			document.getElementById("buildPOSMine2_" + i.Item.GetGrid()).addEventListener("click",function() {_GoTo2(i.Item.GetGrid());});
		}
		$(document).on('click', '#_RebuildMines2_' + i.Item.GetGrid(), function () {
                var isChecked = $('#_RebuildMines2_' + i.Item.GetGrid()).prop('checked');

                if (buildArray2.indexOf(i.Item) === -1 && isChecked) {
                    buildArray2.push(i.Item);

                } else if (buildArray2.indexOf(i.Item) !== -1 && !isChecked) {
                    var index = buildArray2.indexOf(i.Item);
                    buildArray2.splice(index, 1);
                }
            });
    });
	DepletedAll2 = Depleted; 
	if ($("#" + DepositDepletedElements.ON_OFF_RADIO).is(':checked')) {
        $("." + DepositDepletedElements.NOT_AVAILABLE_CB).hide();
    } else {
        $("." + DepositDepletedElements.NOT_AVAILABLE_CB).show();
    }
}

function _FindOriginalResource2(building_name) {
    var res = "";
    try {
        assetsNamesMine2.forEach(function (item) {
            if (building_name.indexOf(item) >= 0)
                res = item;
        });
        if (res != "")
            res = loca.GetText("RES", res);
    } catch (e) {}
    return res;
}

function _GoTo2(g) {
    try {
        $('#DepositDepletedModal').modal('hide');
        swmmo.application.mGameInterface.mCurrentPlayerZone.ScrollToGrid(g);
    } catch (e) {}
}

function mapItemToNumber2(itemName) {
    switch (itemName) {
        case "TitaniumOre":
            return { number: 69, text: "TitaniumOre" };
        case "Salpeter":
            return { number: 63, text: "Salpeter" };
        case "BronzeOre":
            return { number: 36, text: "BronzeOre" };
        case "Coal":
            return { number: 37, text: "Coal" };
        case "GoldOre":
            return { number: 46, text: "GoldOre" };
        case "IronOre":
            return { number: 50, text: "IronOre" };
        case "MineDepletedDepositTitaniumOre":
            return { number: 69, text: "TitaniumOre" };
        case "MineDepletedDepositSalpeter":
            return { number: 63, text: "Salpeter" };
        case "MineDepletedDepositBronzeOre":
            return { number: 36, text: "BronzeOre" };
        case "MineDepletedDepositCoal":
            return { number: 37, text: "Coal" };
        case "MineDepletedDepositGoldOre":
            return { number: 46, text: "GoldOre" };
        case "MineDepletedDepositIronOre":
            return { number: 50, text: "IronOre" };
		case "Corn":
            return { number: parseInt(_RebuildMinesSettings.FieldNr), text: "Corn" };
		case "MineDepletedDepositCorn":
            return { number: parseInt(_RebuildMinesSettings.FieldNr), text: "Corn" };
    }
}

function buildMineUI2(buildArray_input) {
    var x = new TimedQueue(1000);
    var CurrentQueue = 0;
    var CurrentQueueFree = 0;
    var QueueTotal = 0;
    var buildArray_local = [];
	
	var addedGrids = [];
	
    $.each(buildArray_input, function (i, item) {
        try {
            var grid = item.GetGrid();
            if (grid !== undefined && addedGrids.indexOf(grid) === -1) {
                var buildingName = (item.GetBuildingName_string !== undefined) ? item.GetBuildingName_string() : item.GetName_string();

                if (buildingName !== undefined) {
					var Mapping2 = mapItemToNumber2(buildingName);
                    buildArray_local.push({
                        buiGrid: grid,
                        buiRessName: Mapping2.text,
                        buiMineType: Mapping2.number
                    });
                    addedGrids.push(grid);
                }
            }
        } catch (e) {
        }
    });
    $.each(swmmo.application.mGameInterface.mHomePlayer.mBuildQueue.GetQueue_vector(), function (i, GetQueue) {
        CurrentQueue++;
    });
    QueueTotal = swmmo.application.mGameInterface.mHomePlayer.mBuildQueue.GetTotalAvailableSlots();
    CurrentQueueFree = QueueTotal - CurrentQueue;
    //game.showAlert(CurrentQueueFree);
    $.each(buildArray_local, function (i, item) {
        if (CurrentQueueFree > 0) {
            var building_built = game.zone.GetBuildingFromGridPosition(item.buiGrid);
            if (game.gi.isOnHomzone() && (building_built == null || building_built.GetBuildingName_string() == "MineDepletedDepositCorn")) {
				CurrentQueueFree--;
                x.add(function () {
                    game.gi.SendServerAction(50, item.buiMineType, item.buiGrid, 0, null);
                    game.showAlert(getText('MineBuild3', 'SemiAutoATMenuLang') + loca.GetText("RES", item.buiRessName));
					try{
						if(building_built != null)
						{
							if(game.gi.isOnHomzone() && building_built.GetBuildingName_string() == "MineDepletedDepositCorn")
							{
								setTimeout(function() {
									game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
									showGameAlert('Zone Refresh');
								}, 60000);
							}
						}
					}catch(e){}
                });
            }
        }
		
    });
    x.run();
    buildArray_input = [];
    buildArray_local = [];
    buildArray2 = [];
}

