function _usAcceptTradesMenuHandler(event)
{
	try{
		if (!game.gi.isOnHomzone())
		{
			game.showAlert(getText('not_home'));
			return;
		}
		// close all modals
		$( "div[role='dialog']:not(#AcceptTradesModal):visible").modal("hide");
		$('#AcceptTradesModal').remove();
		// create modal
		createModalWindow('AcceptTradesModal', utils.getImageTag('icon_dice.png', '45px') + ' '+ getText('Title', '_usAcceptTradesLang'));
		
		$("#AcceptTradesModal .modal-footer").prepend([
			$('<button>').attr({ "id": "_usAcceptTradesRun", "class": "btn btn-primary pull-left _usAcceptTradesRun" }).text(getText(_usAcceptTradesRunning ? 'BtnStop' : 'BtnRun', '_usAcceptTradesLang')),
			$('<button>').attr({ "id": "_usAcceptTradesReset", "class": "btn btn-primary pull-left _usAcceptTradesReset" }).text(getText('CounterReset' , '_usAcceptTradesLang')),
		]);

		$('#AcceptTradesModalData').html('<div class="container-fluid"></div>');

		_usAcceptTrades_Refresh();
		
		$('#_usAcceptTradesRun').click(function(){
			_usAcceptTrades_Start();
			$("#_usAcceptTradesRun").text(getText(_usAcceptTradesRunning ? 'BtnStop' : 'BtnRun', '_usAcceptTradesLang'));
		});
		$('#_usAcceptTradesReset').click(function(){
			_usAcceptTradesSettings.LastRead = 0;
			_usAcceptTrades_SaveSettings();
			_exudDashboard_ALERT(getText('CounterCleared' , '_usAcceptTradesLang'), "", getText('Title', '_usAcceptTradesLang'));
		});
		$('#_usAcceptTradesBtnLoots').change(function(){
			_usAcceptTradesSettings.AcceptLoots = $("#_usAcceptTradesBtnLoots").prop("checked");
			_usAcceptTrades_SaveSettings();
		});
		$('#_usAcceptTradesBtnGeologist').change(function(){
			_usAcceptTradesSettings.AcceptGeologistMsg = $("#_usAcceptTradesBtnGeologist").prop("checked");
			_usAcceptTrades_SaveSettings();
		});
		$('#_usAcceptTradesBtnDecline').change(function(){
			_usAcceptTradesSettings.DeclineTrades = $("#_usAcceptTradesBtnDecline").prop("checked");
			_usAcceptTrades_SaveSettings();
		});
		$('#_usAcceptAdvTradesBtnLoots').change(function(){
			_usAcceptTradesSettings.AcceptAdventureLoot = $("#_usAcceptAdvTradesBtnLoots").prop("checked");
			_usAcceptTrades_SaveSettings();
		});
		$('#_usAcceptAdvTradesBtnMsg').change(function(){
			_usAcceptTradesSettings.AcceptAdventureMessage = $("#_usAcceptAdvTradesBtnMsg").prop("checked");
			_usAcceptTrades_SaveSettings();
		});		
		
		$('#_usAcceptTradesBtnStar').change(function(){
			_usAcceptTradesSettings.ToStar = $("#_usAcceptTradesBtnStar").prop("checked");
			_usAcceptTrades_SaveSettings();
		});
		

		// show modal
		$('#AcceptTradesModal:not(:visible)').modal({backdrop: "static"});
	}
	catch (e)
	{
		_usAcceptTrades_Message(e);

	}
}

function _usAcceptTrades_Start()
{
	_usAcceptTrades_ID = new Date().getTime();
	_usAcceptTradesRunning = !_usAcceptTradesRunning;
	try
	{
		if (_usAcceptTradesTimeOut != null)
			clearTimeout(_usAcceptTradesTimeOut);
	}
	catch (e)
	{
	}
	
	if (!_usAcceptTradesRunning) return;
	
	_usAcceptTrades_SHMW(true);
	_usAcceptTrades_SHMW(true);
	_usAcceptTrades_SHMW(false);
	
	_usAcceptTradesTimeOut = setTimeout(function() {_usAcceptTrades_Thread(_usAcceptTrades_ID);}, 10000);
}

function _usAcceptTrades_SHMW(show)
{
	try
	{
		if (show)
			globalFlash.gui.mMailWindow.Show();
		else
			globalFlash.gui.mMailWindow.Hide();
	}
	catch (e)
	{
	}
}

function _usAcceptTrades_Thread(id)
{

	if (id != _usAcceptTrades_ID) return;
	try
	{
		if (_usAcceptTradesTimeOut != null)
			clearTimeout(_usAcceptTradesTimeOut);
	}
	catch (e)
	{
	}
	_usAcceptTrades_ID = new Date().getTime();	
	_usAcceptTradesTimeOut = null;
	
	if (!_usAcceptTradesRunning) return;

	if (!game.gi.isOnHomzone())
	{
		_usAcceptTradesTimeOut = setTimeout(function() {_usAcceptTrades_Thread(_usAcceptTrades_ID);}, 60000);
		return;
	}
	
	_usAcceptTrades_CheckMails();
}

function _usAcceptTrades_SaveSettings()
{
	try
	{
		storeSettings(_usAcceptTradesSettings, '_usAcceptTradesSettings');
	} catch (e) {
		_usAcceptTrades_Message(e);
	}
}

function _usAcceptTrades_Refresh()
{
	$('#AcceptTradesModalData .container-fluid').html(_usAcceptTrades_MakeModal());

	try
	{
	  var dorpdown = $('#_usAcceptTradesSelectResource');
		dorpdown.html(dorpdown.find('option').sort(function (option1, option2) {
			return $(option1).text().toLowerCase().localeCompare($(option2).text().toLowerCase());
		}));
	}
	catch (e)
	{
		_usAcceptTrades_Message(e);
	}

	_usAcceptTrades_Refresh_Divs();	
	
	$('#_usAcceptTradesBtnFriend').click(function() {
		var o = $('#_usAcceptTradesSelectFriend option:selected');
		var k = o.val();
		var v = o.text();
		if (k == "---") return;
		delete _usAcceptTradesSettings.EnabledUsers[k];
		_usAcceptTradesSettings.EnabledUsers[k] = {Name : v , favorite : $("#_usAcceptTradesFavorite").is(":checked")};
		_usAcceptTrades_SaveSettings();
		_usAcceptTrades_Refresh_Divs();
	});
	$('#_usAcceptTradesBtnResource').click(function() {
		var o = $('#_usAcceptTradesSelectResource option:selected');
		var k = o.val();
		var v = o.text();
		var a = parseInt($("#_usAcceptTradesInpMax").val());
		var isAll = $("#_usAcceptTradesEveryBody").is(":checked");
		if (a < 1) return;
		if (k == "---") return;
		
		if (isAll)
		{
			if (Object.keys(_usAcceptTradesSettings.EverybodyResources).indexOf(k) < 0)
			{
				_usAcceptTradesSettings.EverybodyResources[k] = {resource_name : v , resource_max : a};
				_usAcceptTrades_SaveSettings();
				_usAcceptTrades_Refresh_Divs();
			}		
		}
		else
		{
			if (Object.keys(_usAcceptTradesSettings.EnabledResources).indexOf(k) < 0)
			{
				_usAcceptTradesSettings.EnabledResources[k] = {resource_name : v , resource_max : a};
				_usAcceptTrades_SaveSettings();
				_usAcceptTrades_Refresh_Divs();
			}		
		}
	});
	
}

