function _usAcceptTrades_Message(Text) 
{
	
}

function _usAcceptTrades_FriendsCompare(a, b)
{
	return a.username.toLowerCase().localeCompare(b.username.toLowerCase());
}

function _usAcceptTrades_Clear_aWaitingResponse()
{
	clearTimeout(_usAcceptTrades_aWaitingResponse_callback);
	_usAcceptTrades_aWaitingResponse_callback = null;
	_usAcceptTrades_aWaitingResponse = false;
}
function _usAcceptTrades_Set_aWaitingResponse()
{
	_usAcceptTrades_aWaitingResponse_callback = setTimeout(function() {_usAcceptTrades_aWaitingResponse_NoResponse(_usAcceptTrades_ID);}, 20000);
	_usAcceptTrades_aWaitingResponse = true;
}
function _usAcceptTrades_aWaitingResponse_NoResponse()
{
	_usAcceptTrades_Clear_aWaitingResponse();
	_usAcceptTrades_Message("Responder No Response");
	_usAcceptTrades_LastQueue = null;
	_usAcceptTradesTimeOut = setTimeout(function() {_usAcceptTrades_Thread(_usAcceptTrades_ID);},  _usAcceptTradesSettings.TimerMinutes*60000);
}

function _usAcceptTrades_CheckMails()
{
	_usAcceptTrades_Set_aWaitingResponse();
	if (!_usMailSystem_GetHeaders(_usAcceptTrades_GetHeadersResponder))
	{
		_usAcceptTradesTimeOut = setTimeout(function() {_usAcceptTrades_Thread(_usAcceptTrades_ID);},  _usAcceptTradesSettings.TimerMinutes*60000);
	}
}
function _usAcceptTrades_TestMails()
{
	_usMailSystem_GetHeaders(_usAcceptTrades_GetHeadersResponderTest);
}

var _usAcceptTradesTestData = null;

function _usAcceptTrades_GetHeadersResponderHandlerTest(event, data)
{
	_usAcceptTradesTestData = data;
}
function _usAcceptTrades_GetHeadersResponderHandlerFault(event, data)
{
	_usAcceptTrades_aWaitingResponse_NoResponse();
}
function _usAcceptTrades_GetHeadersResponderHandler(event, data)
{
	_usAcceptTrades_Clear_aWaitingResponse();
	_usAcceptTrades_Message("Get Mails Headers Handler");
	exudSaveResourcesResponderResult = {};
	_usAcceptTrades_LastQueue = null;
	var Stopped = false;
	var AceeptLootMailsID = [];
	var AcceptOthersMailsID =[];
	var AcceptInviteMailsID = [];
	var EndUnlock = true;
	try
	{
		if (data != null && data.data != null)
		{
			_usAcceptTrades_Message("RS1 init");
			_usAcceptTrades_LastHeadersReceived = data;
			if (_usAcceptTrades_LastHeadersReceived.data.isInbox)
			{
				var col = _usAcceptTrades_LastHeadersReceived.data.headers_collection;
				_usAcceptTrades_Message("RS1: received "+col.length+" headers");
				var UsersEnabled = Object.keys(_usAcceptTradesSettings.EnabledUsers);
				var actMax = 0;
				var xq = new TimedQueue(1000);
				
				$.each(col, function(i, objMail) {
					if (objMail != null)
					{
						if (!game.gi.isOnHomzone() || Stopped) {Stopped = true; return; }
						
						if (objMail.id > actMax) actMax = objMail.id;
						if (objMail.id <= _usAcceptTradesSettings.LastRead) return; // already verifieds
						_usAcceptTrades_Message("Mail Type : " + objMail.type + " SenderId : " + objMail.senderId)
						// this groups can be to star
						if 	( 	(_usAcceptTradesSettings.AcceptLoots && _usMailSystem_MailLootTypes.indexOf(objMail.type) >= 0) ||
								(_usAcceptTradesSettings.AcceptGeologistMsg && _usMailSystem_MailLootGeoTypes.indexOf(objMail.type) >= 0) ||
								(objMail.senderId < 0 && _usAcceptTradesSettings.AcceptAdventureLoot && _usMailSystem_MailAdvLootTypes.indexOf(objMail.type) >= 0) 
							)
						{
							AceeptLootMailsID.push(objMail.id);
						}
					else  // this group cannot go to star
						if 	(objMail.senderId < 0 && _usAcceptTradesSettings.AcceptAdventureMessage && _usMailSystem_MailAdvMessageTypes.indexOf(objMail.type) >= 0)
							{
								AcceptOthersMailsID.push(objMail.id);
							}
					else
							if (_usAcceptTradesSettings.AcceptInvites && _usMailSystem_MailAdvInviteTypes.indexOf(objMail.type) >= 0)
							{
								_usAcceptTrades_Message("Invite ID : " + objMail.id)
								AcceptInviteMailsID.push(objMail.id);
							}
						else
						{
							if (objMail.type == _usMailSystem_TRADE || objMail.type == _usMailSystem_TRADE_ACCEPTED || objMail.type == _usMailSystem_TRADE_REJECTED)
							{
								var user = _usAcceptTradesSettings.EnabledUsers[objMail.senderId.toString()];
								if (user !== undefined && user != null && user.favorite && !_usAcceptTradesSettings.SaveFriendsTrades)
									{
										_usAcceptTrades_Message("Favorite -> Type : " + objMail.type + " SenderId : " + objMail.senderId)
										xq.add(function() {_usAcceptTrades_AcceptUserTrade(objMail.type , objMail.id);});
									}
								else
									{
										_usAcceptTrades_Message("Trade Type : " + objMail.type + " SenderId : " + objMail.senderId)
										xq.add(function() {_usAcceptTrades_GetMailBody(objMail.id);});
									}								
							}
						}
					}
				});
				
				if (!Stopped && game.gi.isOnHomzone())
				{
					if (AceeptLootMailsID.length > 0)
						xq.add(function() {_usMailSystem_AcceptMultiLoot(AceeptLootMailsID , _usAcceptTradesSettings.ToStar , null);}, 5000);

					if (AcceptOthersMailsID.length > 0)
						xq.add(function() {_usMailSystem_AcceptMultiLoot(AcceptOthersMailsID , false , null);}, 5000);

					if (AcceptInviteMailsID.length > 0)
						xq.add(function() {_usAcceptTrades_AcceptInvites(AcceptInviteMailsID);}, 5000);

					if (xq.len() > 0)
					{
						_usAcceptTrades_LastQueue = xq;
						EndUnlock = false;
						xq.run();
					}

					_usAcceptTradesSettings.LastRead = actMax;
					_usAcceptTrades_SaveSettings();
					 
				}
			}
			
		}
	}
	catch (e) 
	{
		_usAcceptTrades_Message("SR1: " + e);
	}
	_usAcceptTrades_Message("Restart Loop");
	_usAcceptTradesTimeOut = setTimeout(function() {_usAcceptTrades_Thread(_usAcceptTrades_ID);}, (Stopped ? 30000 : _usAcceptTradesSettings.TimerMinutes*60000));
	
	if (EndUnlock)
	{}
}

function _usAcceptTrades_AcceptInvites(AceeptLootMailsID)
{
	try
	{
		if (AceeptLootMailsID === undefined || AceeptLootMailsID == null || AceeptLootMailsID.length <= 0)	return;
		_usAcceptTrades_AcceptInvite_Try_Mails = AceeptLootMailsID;
		_usAcceptTrades_AcceptInvite_Try_Index = 0;
		_usAcceptTrades_AcceptInvite_Try();
	}
	catch (e)
	{
		_usAcceptTrades_Message("AcceptInvites: " + e);
	}
}

function _usAcceptTrades_GetInviteResponderHandlerFault(event, data)
{
	_usAcceptTrades_AcceptInvite_Try(); // try next
}

function _usAcceptTrades_AcceptInvite_Try()
{
	try
	{
		if (_usAcceptTrades_AcceptInvite_Try_Index >= _usAcceptTrades_AcceptInvite_Try_Mails.length)
		{
			_usAcceptTrades_Message("Invite End Loop");				
			return;
		}
		var id = _usAcceptTrades_AcceptInvite_Try_Mails[_usAcceptTrades_AcceptInvite_Try_Index++];
		_usAcceptTrades_Set_aWaitingResponse();
		_usMailSystem_GetMailBody(id, _usAcceptTrades_GetInviteResponder);
	}
	catch (e)
	{
		_usAcceptTrades_Message("AcceptInvite_Try: " + e);
	}
}
function _usAcceptTrades_GetInviteResponderHandler(event, data)
{
	try
	{
		var advName = data.data.attachments.adventureName;
		var friend = data.data.senderId.toString();
		var zoneid = data.data.attachments.zoneID;
		var mailid = data.data.id;

		_usAcceptTrades_Message("Received an invite for " + advName + " from " + friend);
		if (_usInvitesSettings.Adventures[advName] !== undefined) // Invite configured?
		{
			cfg = _usInvitesSettings.Adventures[advName];
			if (cfg.Players[friend] !== undefined)
			{
				_usAcceptTrades_Message("Accepting an invite for " + advName + " from " + cfg.Players[friend] + " mailID : " + mailid);
				_exudMIA_HasStuckedInvitedAdv(zoneid);
				// ok valid invite
				setTimeout(function() {_exudMIA_StartAdventure(advName, zoneid, mailid);}, 5000);
				return; // end of loop
			}
		}
	}
	catch (e)
	{
		_usAcceptTrades_Message("_usAcceptTrades_GetInviteResponderHandler -> " + e);
	}
	
	_usAcceptTrades_AcceptInvite_Try(); // try next
}

function _usAcceptTrades_GetMailBody(id)
{
	if (!_usAcceptTradesRunning) return;
	if (!game.gi.isOnHomzone())
	{
		_usAcceptTrades_Stop(id);
		return;
	}	

	try
	{
		_usAcceptTrades_Set_aWaitingResponse();
		_usMailSystem_GetMailBody(id, _usAcceptTrades_GetBodyResponder);
	}
	catch (e)
	{
		_usAcceptTrades_Message("Get Body: " + e);
	}	
}

function _usAcceptTrades_CheckEveryBodyResources(type, amount)
{	
	try
	{
		_usAcceptTrades_Message("Check Resources EveryBody : " + amount + " " + type);
		var r = _usAcceptTradesSettings.EverybodyResources[type];
		if (r !== undefined && r != null)
		{
			_usAcceptTrades_Message("Check Resources EveryBody : " + amount + " " + type + " max is : " + r.resource_max);
			return (amount <= r.resource_max);
		}
	}
	catch (e)
	{
		_usAcceptTrades_Message("Check EveryBody Resource: " + e);
	}
	
	return false;
}
function _usAcceptTrades_CheckResources(type, amount)
{	

	try
	{
		var r = _usAcceptTradesSettings.EnabledResources[type];
		_usAcceptTrades_Message("Check Resources : " + amount + " " + type);
		if (r !== undefined && r != null)
		{
			_usAcceptTrades_Message("Check Resources : " + amount + " " + type + " max is : " + r.resource_max);
			return (amount <= r.resource_max);
		}
	}
	catch (e)
	{
		_usAcceptTrades_Message("Check Resource: " + e);
	}
	
	return false;
}

function _usAcceptTrades_Stop(id) // user in other zone, suspend all and back to previous computed msg
{
	if (id <= _usAcceptTradesSettings.LastRead)
	{
		_usAcceptTradesSettings.LastRead = id-1;
		_usAcceptTrades_SaveSettings();
	}
}
function _usAcceptTrades_GetBodyItems(datamail)
{
	var sname = "";
	var sqty = "";
	
	try
	{
		if (datamail !== undefined && datamail != null && datamail != "")
		{
			var resources = datamail.split(",");
			if (resources !== undefined && resources != null)
				if (resources.length == 2)
				{
					sname = resources[0];
					sqty = resources[1];
				}
				else
					if (resources.length == 3)
					{
						sname = resources[1];
						sqty = resources[2];
						if (sname == "")
							sname = resources[0];					
					}
		}
		else
			_usAcceptTrades_Message("datamail NULL");
	}
	catch (es)
	{
		_usAcceptTrades_Message("datamail: ["+datamail+"] " + es);
	}
	
	return { Name : sname , Qty : sqty };
}
function _usAcceptTrades_GetTestBodyResponderHandler(event, data)
{
	LastMailreadData = data;	
	_usAcceptTrades_Message("Test Get Body Succeded");
	debug(LastMailreadData);
}
var LastMailreadData = "";
function _usAcceptTrades_GetBodyResponderHandler(event, data)
{
	_usAcceptTrades_Clear_aWaitingResponse();
	if (!_usAcceptTradesRunning) return;
	if (!game.gi.isOnHomzone())
	{
		_usAcceptTrades_Stop(id);
		return;
	}
	LastMailreadData = data;
	try
	{
		if (data != null && data.data != null)
		{
			
			var mres = data.data.body.split("|");
			
			var get_resources = { Name : "" , Qty : "" };
			var send_resources = { Name : "" , Qty : "" };
			
			if (mres.length > 0)
				get_resources = _usAcceptTrades_GetBodyItems(mres[0]);
			if (mres.length > 1)
				send_resources = _usAcceptTrades_GetBodyItems(mres[1]);
			
			var okResources = false;
			var user = _usAcceptTradesSettings.EnabledUsers[data.data.senderId.toString()];
			if (user === undefined || user === null) // Not a friends
			{
				okResources = _usAcceptTrades_CheckEveryBodyResources(send_resources.Name, send_resources.Qty);
			}
			else
				if (user.favorite !== true) // is a friend but nor favorite
				{
					if (data.data.type == 1 && send_resources != null && send_resources.Name != "")
						okResources = _usAcceptTrades_CheckResources(send_resources.Name, send_resources.Qty);
				}
				else
					okResources = true; // Is a favorite friend
			
			var amount = 0;
			var canTrade = true;
			if (okResources)
			{
				if (data.data.type == _usMailSystem_TRADE)
				{
					amount = _exudMissions_GetItemAmount(send_resources.Name);
					if (amount < send_resources.Qty)
						canTrade = false;
				}
				
				try
				{
					if (_usAcceptTradesSettings.SaveFriendsTrades && (data.data.type == _usMailSystem_TRADE || data.data.type == _usMailSystem_TRADE_ACCEPTED || data.data.type == _usMailSystem_TRADE_REJECTED ))
						_usAcceptTrades_SaveTradeToLog(data.data.senderName , send_resources.Name , send_resources.Qty , get_resources.Name, get_resources.Qty, canTrade);
				}
				catch (elog)
				{
					
				}
				
				if (!canTrade)
				{
					_usAcceptTrades_Message("Cannot accept mail : " + data.data.body + " / " + data.data.id);
					if (_usAcceptTradesSettings.DeclineTrades)
						_usAcceptTrades_RefuseUserTrade(data.data.id);
				}
				else
				{
					_usAcceptTrades_Message("Accept mail : " + data.data.body + " / " + data.data.id);
					_usAcceptTrades_AcceptUserTrade(data.data.type, data.data.id);
				}
			}
			else
			{
				_usAcceptTrades_Message("PENDING MAIL : " + data.data.body + " / " + data.data.id);
				_exudDashboard_POA_ADD(getText('MsgPendingMail', '_exudPOAWin_Lang').format(data.data.body),'MsgPendingMail'); 
			}
				
		}
	}
	catch (e)
	{
		_usAcceptTrades_Message("SR2: " + e);
	}
}

function _usAcceptTrades_RefuseUserTrade(mailId)
{
	if (!game.gi.isOnHomzone())
	{
		_usAcceptTrades_Stop(mailId);
		return;
	}
	_usMailSystem_RefuseUserTrade(mailId, null);
}

function _usAcceptTrades_AcceptUserTrade(type, mailId)
{
	if (!game.gi.isOnHomzone())
	{
		_usAcceptTrades_Stop(mailId);
		return;
	}
	
	try
	{
		if (type == 1)
			_usMailSystem_AcceptUserTrade(mailId, null);
		else
			_usMailSystem_CompleteUserTrade(mailId, null);
	}
	catch (e)
	{
	}
}

function _usAcceptTrades_SaveTradeToLog(friend , out_res_name , out_res_qty , in_res_name, in_res_qty, canTrade)
{
	try
	{
		if (_exudDashboardSettings.SaveDbgOnCloseDIR !== undefined && _exudDashboardSettings.SaveDbgOnCloseDIR != null && _exudDashboardSettings.SaveDbgOnCloseDIR != "")
		{
			var dt = _exudDashboard_DateToString(new Date(), true);
			var r = dt + "\t" + (friend+"                    ").slice(0,20);
			
			if (in_res_name != "")
				r+= " " + (getText('InRes', '_usAcceptTradesLang') + ": " + (in_res_qty + "            ").slice(0,8) + (_exudMissions_FindTextOf(in_res_name) + "                              ").slice(0,30));
			
			if (out_res_name != "")
				r += " " + getText('OutRes', '_usAcceptTradesLang') + ": " + (out_res_qty + "            ").slice(0,8) + (_exudMissions_FindTextOf(out_res_name) + "                              ").slice(0,30);
			
			if (!canTrade)
				r += " " + getText('Declined', '_usAcceptTradesLang')
			
			r+= "\r\n"
			var fname = "tfriends.log";
			var file = new air.File(air.File.documentsDirectory.resolvePath(_exudDashboardSettings.SaveDbgOnCloseDIR + "\\" + fname).nativePath);
			fs = new air.FileStream;
			fs.open(file, "append");
			fs.writeUTFBytes(r);
			fs.close();

		}
	}
	catch (e)
	{
		_usAcceptTrades_Message("Error saving trade log: " + e);
	}
}

