function _usMailSystem_SendUserTrade(srcSend, srcSendAmount, srcReceive, srcReceiveAMount, FriendID, response_callback, isBuff) 
{
	if (!game.gi.isOnHomzone())	return false;
	try
	{
			var TOffDef = swmmo.getDefinitionByName("Communication.VO::dTradeOfferVO");
			var ResDef = swmmo.getDefinitionByName("Communication.VO::dResourceVO");
			var BuffDef = swmmo.getDefinitionByName("Communication.VO::dBuffVO");
			var TOff = new TOffDef();
			var buffOffer = new BuffDef();
			var MyBuffID = "";
			var MyBuffID2 = "";
			var Buffnamedata = "";
			var datashow = "";
			var isBuffIntern = false;
			var buffVector = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();
				buffVector.forEach(function(data){
					//debug(data.GetBuffDefinition().GetName_string());
					//debug(srcSend);
					if(data.GetResourceName_string() == srcSend && isBuff == "Buff") {
						MyBuffID = data.GetUniqueId().uniqueID1;
						MyBuffID2 = data.GetUniqueId().uniqueID2;
						Buffnamedata = data.GetType();
						datashow = data;
						isBuffIntern = true;
					}
					if(data.GetBuffDefinition().GetName_string() == srcSend && data.GetResourceName_string() == "" && isBuff == "Buff") {
						MyBuffID = data.GetUniqueId().uniqueID1;
						MyBuffID2 = data.GetUniqueId().uniqueID2;
						Buffnamedata = data.GetType();
						datashow = data;
						isBuffIntern = true;
					}
				});
				//debug(datashow + " srcSend: " + srcSend);
			if(isBuffIntern)
			{
				var uniqueID = swmmo.getDefinitionByName("Communication.VO::dUniqueID").Create(MyBuffID, MyBuffID2);
				buffOffer.amount = srcSendAmount;
				buffOffer.buffName_string = Buffnamedata;
				buffOffer.resourceName_string = srcSend;
				buffOffer.uniqueId1 = MyBuffID;
				buffOffer.uniqueId2 = MyBuffID2;
				buffOffer.sourceZoneId = game.player.GetPlayerId();
				/* debug(srcSend);	
				debug(Buffnamedata);	
				debug(datashow);	 */
				TOff.offerRes = null;
				TOff.offerBuff = buffOffer;			
			}
			else
			{
				var resOffer = new ResDef().init(srcSend, srcSendAmount);
				TOff.offerRes = resOffer;
				TOff.offerBuff = null;
			}
			var resCost = new ResDef().init(srcReceive, srcReceiveAMount);
			TOff.costsRes = resCost;
			TOff.costsBuff = null;
			TOff.receipientId = FriendID;
			TOff.lots = 0;
			TOff.slotType = _usMailSystem_TRADE_TYPE_FRIEND_TO_FRIEND;
			TOff.slotPos = 0;
			//debug(TOff);
			_exudDashboard_SendMessageDirectlyToServer(_usMailSystem_SEND_TRADE_MAIL, swmmo.application.mGameInterface.mCurrentViewedZoneID, TOff, response_callback);
			_exudDashboard_ALERT(getText("MailSent", '_usMailSystemLang'), "MAIL_TRADE", getText('Title', '_usMailSystemLang'));
			return true;
	}
	catch(e) 
	{
		//debug(e);	
		_usMailSystem_Message("SendUserTrade: " + e);
	}
	return false;
}
