function _exudDashboard_ALERT(e, type, title)
{
	if (title === undefined)	title = "";

	_exudDashboard_ALERT_ICON(e, type, title);
}

function _exudDashboard_ALERT_ICON(e, type, title)
{
	try
	{
		var icon_name = "inner_eye.png";
		var TITLE = "Framework";
		if (title != "")
			TITLE = title;

		switch(type)
		{
			case "BIG_ERROR" :
				icon_name = "Boss.png";
				break;
			case "MEMORY" :
				icon_name = "eventmarketbuff2_rabbid.png";
				break;
			case "RESOURCE" :
				icon_name = "buff_bridge_repair_kit.png";
				break;
			case "EXPLORER" :
				icon_name = "icon_explorer.png";
				break;
			case "GEOLOGIST" :
				icon_name = "icon_geologist.png";
				break;
			case "QUEST" :
				icon_name = "advanced_strategies_zone_buff_icon.png";
				break;
			case "MISSION" :
				icon_name = "icon_crisis_quest.png";
				break;
			case "MAIL_TRADE" :
				icon_name = "icon_task_building.png";
				break;
			case "MAIL_LOOT" :
				icon_name = "icon_streetwise_negotiator.png";
				break;
			case "ARMY" :
				icon_name = "buff_hire_swordsmen.png";
				break;
			case "COMBAT" :
				icon_name = "CombatGeneral.png";
				break;
			case "UNLOAD_UNIT" :
				icon_name = "remove_general_skin.png";
				break;
			case "":
				icon_name = "inner_eye.png";
				break;
			default:
				icon_name = type;
				break;
		}

		var t=game.def("GUI.Components.ItemRenderer::AvatarMessageItemRenderer",!0);
		swmmo.getDefinitionByName("globalFlash").gui.mAvatarMessageList.mClientMessages.addChild(t);
		t.headlineLabel.text=TITLE;
		t.messageBody.text=e;
		t.image.source=assets.GetBitmap(icon_name);
		if (t.image.source.height == 1)
			t.image.source=assets.GetBuildingIcon(icon_name, true);
	}
	catch (err)
	{
	}
}

