function exudSaveResourcestMenuHandler(event)
{
	try
	{
		if (!game.gi.isOnHomzone())
		{
			game.showAlert(getText('not_home'));
			return;
		}
		// close all modals
		$( "div[role='dialog']:not(#exudSaveResourcesModal):visible").modal("hide");
		$('#exudSaveResourcesModal').remove();
		// create modal
		createModalWindow('exudSaveResourcesModal', utils.getImageTag('icon_dice.png', '45px') + ' '+ getText('Title', '_exudSaveResourcesLang'));
		// fill modal data 
		$('#exudSaveResourcesModalData').html('<div class="container-fluid"></div>');
		// show modal
		$('#exudSaveResourcesModal:not(:visible)').modal({backdrop: "static"});
		OnlyLager = false;
		OnlyStar = false;
		exudSaveResourcesModal();
	}
	catch (e)
	{

	}
	
}

function exudSaveResourcesModal()
