function _exudTrades_PrepareSelectFriend(_friends, ids)
{
		var select_friend = $('<select>', { id: 'exudTradesSelectFriend'+ids });
		select_friend.append($('<option>', { value:"0" }).text("---"));

		_friends.forEach(function(item) {
			if (item != null)
			{
				select_friend.append($('<option>', { value: item.id }).text(item.username));	
			}
		});

		return select_friend;
}

function _exudTrades_SendItem()
{
	try
	{
		var SendRec = $('#_SelectResourcesSend option:selected').val();
		var RecRec = $('#_SelectResourcesRec option:selected').val();
		var SendAm = parseInt($("#exudTradesSelectAmountSend").val());
		var RecAm = parseInt($("#exudTradesSelectAmountReceive").val());
		var isBV = $("#exudTradesCheckISBV").prop("checked");
		var friendID2 = $('#exudTradesSelectFriend option:selected').val();
		var friendName2 = $('#exudTradesSelectFriend option:selected').text();

		if (SendRec == "---" || RecRec == "---" || SendAm < 1 || RecAm < 1 || friendID2 == 0 || friendName2 == "---")
			return;

		var t = new Date().getTime();
		var tr = {
					'ID' : t ,
					'SendResource' : SendRec,
					'SendAmount' : SendAm,
					'ReceiveResource' : RecRec,
					'ReceiveAmount' : RecAm,
					'ISBV' : isBV,
					'FriendID' : friendID2,
					'FriendName' : friendName2
				};
		
		var trade = tr;
		
		var EnoughRessiTrade = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
		var HasRessiForTrade = false;
		if (EnoughRessiTrade.HasPlayerResource(trade.SendResource, trade.SendAmount))
		{
			HasRessiForTrade = true;
		}
		else
		{
			HasRessiForTrade = false;
		}
		
		if (trade.ISBV)
		{
			if(HasRessiForTrade)
			{
				setTimeout(function() {
				if(game.gi.isOnHomzone() == true)
				{
					_usMailSystem_SendUserTrade2(trade.SendResource, trade.SendAmount, trade.ReceiveResource, trade.ReceiveAmount, trade.FriendID, null);
				}		
				},2000);
					
				setTimeout(function() {
				if(game.gi.isOnHomzone() == true)
				{
					_usMailSystem_SendUserTrade2(trade.ReceiveResource, trade.ReceiveAmount, trade.SendResource, trade.SendAmount, trade.FriendID, null);
				}		
				},4000);
			}
			else
			{
				game.showAlert(getText('TradeNotSend', 'SemiAutoATMenuLang'));
			}
		}
		else
		{
			if(HasRessiForTrade)
			{
				setTimeout(function() {
					if(game.gi.isOnHomzone() == true)
					{
						_usMailSystem_SendUserTrade2(trade.SendResource, trade.SendAmount, trade.ReceiveResource, trade.ReceiveAmount, trade.FriendID, null);
					}		
				},2000);
			}
			else
			{
				game.showAlert(getText('TradeNotSend', 'SemiAutoATMenuLang'));
			}
		}
	}
	catch (e)
	{
	}
}

