function _exudTrades_MakeTableData()
{
	var out = "";

	try 
	{
		var k = Object.keys(_exudTrades2_Settings.Trades);
		k.forEach(function(ki){
			var isIgnoreFriend = $("#exudTradesCheckIgnoreFriend").prop("checked");
			var friendName2 = $('#exudTradesSelectFriend option:selected').text();
			var trade = _exudTrades2_Settings.Trades[ki];
			out += createTableRow([
					[2 , getText('Send', '_exudTradesLang')],
					[2 , trade.SendAmount],
					[4 , loca.GetText("RES", trade.SendResource)],
					[4 , (trade.ISBV ?  getText('ISBV', '_exudTradesLang') : "")]
					], false)
			out += createTableRow([
					[2 , getText('Receive', '_exudTradesLang')],
					[2 , trade.ReceiveAmount ],
					[4 , loca.GetText("RES", trade.ReceiveResource)],
					[3 , (isIgnoreFriend ? friendName2 : trade.FriendName)],
					[1, $('<button>', { 'type': 'button', 'class': 'close exudTradesDelItem', 'value': trade.ID }).html($('<span style="color: red;font-size: 35px;">').html('&times;'))]
					], false)
			+	createTableRow([
				[2, ""],
				[3, ""],
				[4, $('<button>').attr({ "class": "btn btn-primary exudTradesSendItem2", 'value': trade.ID }).text(getText('BtnSend', '_exudTradesLang'))],
				[2, ""],
				[2, ""]
				], false)
			out += "<hr/>";
			
		});
	}
	catch (e)
	{
	}
	return out;
}

function _exudTrades_SendItem2(IDval)
{
	try
	{
		var SendRec;
		var RecRec;
		var SendAm;
		var RecAm;
		var isBV;
		var friendID2;
		var friendName2;
		var trade;
		var isIgnoreFriend = $("#exudTradesCheckIgnoreFriend").prop("checked");
		var friendID3 = $('#exudTradesSelectFriend option:selected').val();
		var k = Object.keys(_exudTrades2_Settings.Trades);
		k.forEach(function(ki){
			trade = _exudTrades2_Settings.Trades[ki];
			if(trade.ID == IDval)
			{
				SendRec = trade.SendResource;
				RecRec = trade.ReceiveResource;
				SendAm = trade.SendAmount;
				RecAm = trade.ReceiveAmount;
				isBV = trade.ISBV;
				if(isIgnoreFriend)
				{
					friendID2 = friendID3;
				}
				else
				{
					friendID2 = trade.FriendID;
				}
				friendName2 = trade.FriendName;
			}
		});
		
		if(isIgnoreFriend)
		{
			if (friendID3 == 0)
			return;
		}
		
		if (SendRec == "---" || RecRec == "---" || SendAm < 1 || RecAm < 1 || friendID2 == 0 || friendName2 == "---")
			return;

		var t = new Date().getTime();
		var tr = {
					'ID' : t ,
					'SendResource' : SendRec,
					'SendAmount' : SendAm,
					'ReceiveResource' : RecRec,
					'ReceiveAmount' : RecAm,
					'ISBV' : isBV,
					'FriendID' : friendID2,
					'FriendName' : friendName2
				};
		
		var trade2 = tr;
		
		var EnoughRessiTrade = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
		var HasRessiForTrade = false;
		if (EnoughRessiTrade.HasPlayerResource(trade2.SendResource, trade2.SendAmount))
		{
			HasRessiForTrade = true;
		}
		else
		{
			HasRessiForTrade = false;
		}
		
		if (trade2.ISBV)
		{
			if(HasRessiForTrade)
			{
				setTimeout(function() {
				if(game.gi.isOnHomzone() == true)
				{
					_usMailSystem_SendUserTrade2(trade2.SendResource, trade2.SendAmount, trade2.ReceiveResource, trade2.ReceiveAmount, trade2.FriendID, null);
				}		
				},2000);
					
				setTimeout(function() {
				if(game.gi.isOnHomzone() == true)
				{
					_usMailSystem_SendUserTrade2(trade2.ReceiveResource, trade2.ReceiveAmount, trade2.SendResource, trade2.SendAmount, trade2.FriendID, null);
				}		
				},4000);
			}
			else
			{
				game.showAlert(getText('TradeNotSend', 'SemiAutoATMenuLang'));
			}
		}
		else
		{
			if(HasRessiForTrade)
			{
				setTimeout(function() {
					if(game.gi.isOnHomzone() == true)
					{
						_usMailSystem_SendUserTrade2(trade2.SendResource, trade2.SendAmount, trade2.ReceiveResource, trade2.ReceiveAmount, trade2.FriendID, null);
					}		
				},2000);
			}
			else
			{
				game.showAlert(getText('TradeNotSend', 'SemiAutoATMenuLang'));
			}
		}
	}
	catch (e)
	{
	}
}

