function uSTARMENU_MakeTableData() {
    var out = "";

    try {
        var tableData = [];

        for (var x = 0; x < uSTARMENU_BOXTYPES.length; x++) {
            var isSel = (_exSTARMENU_Settings.BOXTYPES.indexOf(uSTARMENU_BOXTYPES[x]) >= 0);
            var text = _exudMissions_FindTextOf(uSTARMENU_BOXTYPES[x]);

            tableData.push({ switchValue: createSwitch("uSTARMENU_sw_" + x, isSel), text: text });
        }

        tableData.sort(function(a, b) {
            return a.text.localeCompare(b.text);
        });

        for (var i = 0; i < tableData.length; i++) {
            out += createTableRow([
                [1, tableData[i].switchValue],
                [11, tableData[i].text]
            ], false);
        }
    } catch (e) {
        uSTARMENU_Message("MakeTbl : " + e);
    }
    return out;
}

function uSTARMENU_OpenBox(e) {
	try {
		if (!game.gi.isOnHomzone())
		{
			game.showAlert(getText('not_home'));
			return;
		}
		var buffs = _exudMissions_GetSecureBuffMinimalInfo();

		if (buffs == null) {
			return;
		}
		var MH = CHAOS_CURRENT_PLAYER_ZONE().mStreetDataMap.GetMayorHouse().GetGrid();
		var q = new TimedQueue(2000);
		var bb = uSTARMENU_FindBuffsLootable(buffs);

		if (bb != null) {
			for (var x = 0; x < bb.length; x++) {
				var b = bb[x];
				if (_exSTARMENU_Settings.BOXTYPES.indexOf(b.Def_NameString) >= 0) {
					var txt = _exudMissions_FindTextOf(b.Def_NameString);
					var txtName = _exudMissions_FindTextOf(b.Def_NameString);
					for (var y = 0; y < b.Amount; y++) {

						(function(b, txtName, y) {
							q.add(function() {
								try {
									uSTARMENU_Message(getText("lblOpenMessage2", 'uSTARMENULang')+"("+ y +")"+": " + txtName);
									var uniqueIdArr = b.UID.split("_");
									var uniqueID = swmmo.getDefinitionByName("Communication.VO::dUniqueID").Create(uniqueIdArr[0], uniqueIdArr[1]);
									CHAOS_GI().SendServerAction(61, 0, MH, 0, uniqueID);
								} catch (e) {
									uSTARMENU_Message(getText("lblOpenMessageError", 'uSTARMENULang') + e);
								}
							}, 5000);
						})(b, txtName, y);

					}
				}
			}
		}
		if (q.len() > 0) {
			q.add(function() {
				game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
				showGameAlert(getText("lblZoneRefresh", 'uSTARMENULang'));
			}, 5000);

			if (game.gi.isOnHomzone() == true) {
				q.run();
				uSTARMENU_Message(getText("lblOpenMessage", 'uSTARMENULang'));
			}

		} else {
			uSTARMENU_Message(getText("lblOpenNoBoxes", 'uSTARMENULang'));
		}
	} catch (e) {
		uSTARMENU_Message(getText("lblOpenMessageError", 'uSTARMENULang') + e);
	}
}

function uSTARMENU_FindBuffsLootable(b)
{
	try
	{
		var Result = [];		
		if (b === undefined || b === null || b.length == 0 || b.length > 10000)
		{
			uSTARMENU_Message("BuffVector is null");
		}
		else
		{
			for(var i = b.length-1; i >= 0; i--)
				if (uSTARMENU_BOXTYPES.indexOf(b[i].Def_NameString) >= 0)
					Result.push(b[i]);

			if (Result.length>0)	return Result;
		}
	}
	catch (e)
	{
		uSTARMENU_Message("FindBuffsLootable: " + e);
	}
	return null;
}
function uSTARMENU_Message(Text) 
{
	game.showAlert(Text);
}

function _exudMissions_FindTextOf(s)
{
	if (s == "") return "";
	for(var idx = 0 ; idx < MISSION_TextTypes.length; idx++)
	{
		var n = loca.GetText(MISSION_TextTypes[idx], s);
		if (n.toLowerCase().indexOf("undefined") < 0)
			return n;
	}
	return s;
}

function _exudMissions_GetSecureBuffMinimalInfo()
{
	try
	{
		if (_exudMissions_Last_SecureBuffMinimalInfo != null && (new Date().getTime()-_exudMissions_Last_SecureBuffMinimalInfo_time < 5000))
		{
			_exudMissions_Last_SecureBuffMinimalInfo_time = new Date().getTime();
			return _exudMissions_Last_SecureBuffMinimalInfo;
		}
		_exudMissions_Last_SecureBuffMinimalInfo = null;

		var a = [];

		var b = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();
		if (b != null)
		{
			for(var x = 0; x < b.length; x++)
				try
				{
					if (b[x] != null) 
					{
						var item = b[x];
						var bd = item.GetBuffDefinition();
						if (bd === undefined)	return null;
						a.push(
								{
									'UID' : item.GetUniqueId().toKeyString().replace(".", "_"),
									'Name' : item.getName() ,
									'ResourceName_String' : item.GetResourceName_string(),
									'Amount' : item.GetAmount(),
									'InstantAmount' : item.GetInstantAmount(),
									'Def_NameString' : bd.GetName_string(),
									'Def_BuffType' : bd.GetBuffType() ,
									'Def_Type' : bd.GetType(),
									'Def_IsTypeCombat' : bd.IsTypeCombat(),
									'Def_IsChangeSkinBuff': bd.IsChangeSkinBuff(),
									'Def_GetAdventureTargets' : bd.GetAdventureTargets(),
									'Def_IsChangeDefaultSkinBuff' : bd.IsChangeDefaultSkinBuff(),
									'Def_TargetZoneTypes' : bd.getTargetZoneTypes(),
									'Def_IsAdventure' : bd.IsAdventure()
								}
							);
					}
					else
						return null;
				}
				catch (e2)
				{
					return null;
				}
			if (a.length == b.length)
			{
				_exudMissions_Last_SecureBuffMinimalInfo_time = new Date().getTime();
				_exudMissions_Last_SecureBuffMinimalInfo = a;
				return a;
			}
		}
	}
	catch (e)
	{
		game.showAlert(e);
	}
	return null;
}

