function containsSignStar (word, content) {
for(var i = 0; i < (word.length-content.length+1); i++){
if(word.substring(i, i+content.length) == content) return true;
}
return false;
}

function SendStarItemToStore(e)
{
	try {
		if (!game.gi.isOnHomzone())
		{
			game.showAlert(getText('not_home'));
			return;
		}
		var checking;
		var sign = "Premium";
		var dBuffListVO = swmmo.getDefinitionByName("Communication.VO::dBuffListVO");
		var buffList = new dBuffListVO();
		buffList.buffList = new(swmmo.getDefinitionByName("mx.collections::ArrayCollection"));
		buffList.target_string = "Mayorhouse";
		var dBuffVO = swmmo.getDefinitionByName("Communication.VO::dBuffVO");
		var n = 0;
		var cPlayerDataCapaTest = swmmo.application.mGameInterface.mHomePlayer;
		
		try{
		CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector().forEach(function(item) {
				checking = item.GetBuffDefinition().GetName_string();
				if (containsSignStar(checking, sign))
				{
					return;
					//debug(item.GetBuffDefinition().GetName_string());
				}
				if (item.GetBuffDefinition().GetName_string() == "Population" || item.GetResourceName_string() == "Population"){ return;}
				if (item.GetBuffDefinition().GetName_string() == "FillDeposit"){ return;}
				if (item.GetBuffDefinition().IsAdventure()){ return;}
				if (_exSTARTOSTORE_Settings.BOXTYPES.indexOf(item.GetResourceName_string()) >= 0 && item.GetAmount() > 0) {
					if(swmmo.application.mGameInterface.mCurrentPlayerZone.GetResources(cPlayerDataCapaTest).GetPlayerResource(item.GetResourceName_string()).amount != swmmo.application.mGameInterface.mCurrentPlayerZone.GetResources(cPlayerDataCapaTest).GetPlayerResource(item.GetResourceName_string()).maxLimit)
					{
						var buff = new dBuffVO();
						buff.uniqueId1 = item.GetUniqueId().uniqueID1;
						buff.uniqueId2 = item.GetUniqueId().uniqueID2;
						var iAmount = item.GetAmount();
						buff.amount = iAmount;
						buffList.buffList.addItem(buff);
						uSTARTOSTORE_Message(getText('SendStarToStorage', 'SemiAutoATMenuLang') + _exudMissions_FindTextOf(item.GetResourceName_string()) + getText('SendStarToStorage2', 'SemiAutoATMenuLang') + iAmount);
						++n;
					}	
				}
		});
		}catch(e){uSTARTOSTORE_Message(getText('SendStarToStorageError', 'SemiAutoATMenuLang') + item +") "+ getText('SendStarToStorageError2', 'SemiAutoATMenuLang'));}

		if (n > 0) {
			CHAOS_GI().SendServerAction(63, 0, swmmo.application.mGameInterface.mCurrentPlayerZone.mStreetDataMap.GetMayorHouse().GetGrid(), 0, buffList);    
		} else {
			uSTARTOSTORE_Message(getText('SendStarToStorageNoAction', 'SemiAutoATMenuLang'));
		}
	} catch (ex) {
		uSTARTOSTORE_Message(getText('SendStarToStorageErrorFatal', 'SemiAutoATMenuLang') + ex);
	}
}
