function uSHOPITEMS_MakeCentralDIV()
{
	try
	{
		$('#usShopItemsModalData').html('<div class="container-fluid">{0}</div>'.format(uSHOPITEMS_MakeTableData()));
	}
	catch (e)
	{
			uSHOPITEMS_Message("MakeCentralDIV : " + e);	
	}

}
function uSHOPITEMS_MakeTableData() {
  var tableData = [];
  try {
    var ShopItems = swmmo.getDefinitionByName("ShopSystem::cShopItemGroup").GetShopItemGroup(17).shopItems_vector;
	var ShopItems2 = swmmo.getDefinitionByName("ShopSystem::cShopItemGroup").GetShopItemGroup(3).shopItems_vector;
	//debug(ShopItems2);
    for (var x = 0; x < uSHOPITEM_TYPES.length; x++) {
      var isSel = (_exSHOPITEM_Settings.TYPES.indexOf(uSHOPITEM_TYPES[x]) >= 0);
      var text = _exudMissions_FindTextOf(uSHOPITEM_TYPES[x]);

      ShopItems.forEach(function(i){
        if (i.GetName_string() === uSHOPITEM_TYPES[x]) {
			var Costsname = i.GetCosts_vector()[0].getName();
			var Costs = i.GetCosts_vector()[0].amount;
			var Costcombo = Costs + " " + Costsname
			tableData.push({ switchValue: createSwitch("uSHOPITEMS_sw_" + x, isSel), text: text, cost: Costcombo });
        }
      });
	  ShopItems2.forEach(function(i){
        if (i.GetName_string() === uSHOPITEM_TYPES[x] && i.GetId() === 50924) {
			var Costsname = i.GetCosts_vector()[0].getName();
			var Costs = i.GetCosts_vector()[0].amount;
			var Costcombo = Costs + " " + Costsname
			tableData.push({ switchValue: createSwitch("uSHOPITEMS_sw_" + x, isSel), text: text, cost: Costcombo });
        }
      });
    }

    tableData.sort(function(a, b) {
      return a.text.localeCompare(b.text);
    });

    var out = "";
    for (var i = 0; i < tableData.length; i++) {
      out += createTableRow([
        [1, tableData[i].switchValue],
        [11, tableData[i].text + " ("+ tableData[i].cost +")"]
      ], false);
    }
  } catch (e) {
    uSHOPITEMS_Message("MakeTbl : " + e);
  }
  return out;
}

