function BuiBuffsUeberwachung(wasrestetueberwachungBuffs) {
    function checkUeberwachung2() {
        WarteZeitZwischenVorlagenÜberwachungFinal2 = 0;
			if(parseInt(user_fast_shortcut_settings_BuildingBuffs.WarteZeitZwischenVorlagenÜberwachungSelector2, 10) === 0)
			{
				WarteZeitZwischenVorlagenÜberwachungFinal2 = 999 * WarteZeitZwischenVorlagenÜberwachungIntern2;
				game.showAlert(getText('Paused', 'SemiAutoATMenuLang'));
			}
			else
			{
				WarteZeitZwischenVorlagenÜberwachungFinal2 = parseInt(user_fast_shortcut_settings_BuildingBuffs.WarteZeitZwischenVorlagenÜberwachungSelector2, 10) * WarteZeitZwischenVorlagenÜberwachungIntern2;
			}
			if(!wasrestetueberwachungBuffs)
			{
				BuiBuffsAktion();
			} else {
				wasrestetueberwachungBuffs = false;
			}
			nextExecutionTimeGebaeudeBuffs = Date.now() + WarteZeitZwischenVorlagenÜberwachungFinal2;
            ueberwachungBuffsTimeoutId = setTimeout(function () {
                checkUeberwachung2();
            }, WarteZeitZwischenVorlagenÜberwachungFinal2);
    }
    checkUeberwachung2();
}

