function GebaeudeBuffsExe(Realname, BuffID, Name)
{
	if(game.gi.isOnHomzone() == false) {
		game.showAlert(getText('not_home'));
		return;
	}
	try
	{
		var CooldownState;
		var BuiBuffGrid;
		var ProductionTypeBuff;
		game.zone.mStreetDataMap.GetBuildings_vector().forEach(function(item){
			if (item === null) { return; }
				if(item.GetBuildingName_string() == Realname)
				{
					CooldownState = item.getRemainingCooldown();
					BuiBuffGrid = item.GetGrid();
					ProductionTypeBuff = item.productionQueue.mProductionType;
					
					if (ProductionTypeBuff === ProductionTypeBuff) {
						return;
					}
				}	
			});
		
		var AllBuffs = [];

		swmmo.getDefinitionByName("global").timedProductions_vector[ProductionTypeBuff].forEach(function(buffs) {
			try
			{
				if(buffs.name_string == BuffID)
				{
					if (!swmmo.getDefinitionByName("global").ui.mRequirements.timedProductionRequirements_vector[buffs.name_string].isFulfilledForSkillList(swmmo.getDefinitionByName("global").ui.mCurrentPlayer.getSkills()))
					{
						return;
					}
					var CostRess = {};
					var ActiveState = false;
								
					buffs.costs_vector.forEach(function(CostRessinner) {
						if (CostRessinner != null)
							CostRess[CostRessinner.name_string] = CostRessinner.amount;
					});
					
					if(Realname == "ConcertHall" &&
						   (game.gi.mZoneBuffManager.isBuffRunning("ZoneConcertHallTSR1") ||
							game.gi.mZoneBuffManager.isBuffRunning("ZoneConcertHall1") ||
							game.gi.mZoneBuffManager.isBuffRunning("ZoneConcertHall2") ||
							game.gi.mZoneBuffManager.isBuffRunning("ZoneConcertHall3") ||
							game.gi.mZoneBuffManager.isBuffRunning("ZoneConcertHall4") ||
							game.gi.mZoneBuffManager.isBuffRunning("ZoneConcertHall5")))
					{
						ActiveState = true;
					}
					else
					{
						ActiveState = game.gi.mZoneBuffManager.isBuffRunning(buffs.GetType());
					}

					var buffdata = {
						Name : loca.GetText("RES", buffs.name_string),
						Costs : CostRess,
						Group : buffs.group,
						SelectedOrderType : buffs.GetType(),
						Cooldown : CooldownState,
						Grid : BuiBuffGrid,
						Active : ActiveState
					};
					AllBuffs.push(buffdata);
				}
			}
			catch (e)
			{
			}
		});
		
		var dTimedProductionVO = swmmo.getDefinitionByName("Communication.VO::dTimedProductionVO");
		var timedProductionVO = new dTimedProductionVO();
		timedProductionVO.productionType = ProductionTypeBuff;
		timedProductionVO.type_string = AllBuffs[0].SelectedOrderType;
		timedProductionVO.amount = 1;
		timedProductionVO.stacks = 1;
		timedProductionVO.buildingGrid = AllBuffs[0].Grid;
		var EnoughRessi = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
		var HasRessiForBuff = true;
		Object.keys(AllBuffs[0].Costs).forEach(function(itemcost) {
			if (EnoughRessi.HasPlayerResource(itemcost, AllBuffs[0].Costs[itemcost]))
			{
			}
			else
			{
				HasRessiForBuff = false;
			}
		});
		
		if(!AllBuffs[0].Active && HasRessiForBuff && AllBuffs[0].Cooldown <= 0 && game.gi.isOnHomzone() == true)
		{
			if(FirstClientStart && game.gi.isOnHomzone() == true)
			{
				globalFlash.gui.ShowBuilding(Realname);
				RefreshGUIBUI();
			}
			game.gi.mClientMessages.SendMessagetoServer(91, game.gi.mCurrentViewedZoneID, timedProductionVO);
			game.showAlert(Name + ": " + AllBuffs[0].Name + getText('Buffed', 'SemiAutoATMenuLang'));
		}
		else
		{
			if(FirstClientStart && game.gi.isOnHomzone() == true)
			{
				globalFlash.gui.ShowBuilding(Realname);
				RefreshGUIBUI();
			}
			game.showAlert(Name + ": " + AllBuffs[0].Name + getText('BuffCD', 'SemiAutoATMenuLang'));
		}
	}
	catch(e) {}
}

