function GebaeudeProdExeWithGridGuild(Realname, BuffID, Name, Grid, xLimit)
{
	if(!user_fast_shortcut_settings_BuildingProd.WithoutStacks)
	{
		if(game.gi.isOnHomzone() == false) {
			game.showAlert(getText('not_home'));
			return;
		}
		try
		{
			var BuiBuffGrid;
			var ProductionTypeBuff;
			var CurrentQueue = 0;
			var inProduction = {};
			
			try
			{
				
				game.zone.mStreetDataMap.GetBuildings_vector().forEach(function(item){
				if (item === null) { return; }
				
					if(item.GetBuildingName_string() == Realname && item.GetGrid() == Grid)
					{
						try{
						for(var i = 0; i < item.productionQueue.mTimedProductions_vector.length; i++){
							var item2 = item.productionQueue.mTimedProductions_vector[i];
							var productionVO = item2.GetProductionOrder().GetProductionVO();
							if(!inProduction[productionVO.type_string]){
								inProduction[productionVO.type_string] = 0;
							}
							inProduction[productionVO.type_string] += productionVO.amount;
						};
						}catch(e){}
						BuiBuffGrid = Grid;
						ProductionTypeBuff = item.productionQueue.mProductionType;
						if(!isNaN(inProduction[BuffID]))
						{
							CurrentQueue = inProduction[BuffID];
						}
						else 
						{
							CurrentQueue = 0;
						}
						if (ProductionTypeBuff === ProductionTypeBuff) {
							return;
						}
					}	
				});
			}
			catch(e) {game.showAlert(getText('BuildingProdError', 'SemiAutoATMenuLang'));}	
			
			var AllProds = [];
				
				swmmo.getDefinitionByName("global").timedProductions_vector[ProductionTypeBuff].forEach(function(prod) {
					try
					{
						
						if(prod.name_string == BuffID)
						{
							if(swmmo.getDefinitionByName("BuffSystem::BuffAdventureController").isBuffAdventureBuff(prod.name_string))
							{
								return;
							}
							var CostRess = {};
										
							prod.costs_vector.forEach(function(CostRessinner) {
								if (CostRessinner != null)
								{
									CostRess[CostRessinner.name_string] = CostRessinner.amount;
								}
							});

							var buffdata = {
								Name : loca.GetText("RES", prod.name_string),
								Costs : CostRess,
								SelectedOrderType : prod.GetType(),
								Queue : CurrentQueue,
								Grid : BuiBuffGrid
							};
							AllProds.push(buffdata);
						}
					}
					catch (e)
					{
					}
				});
			
			var amount = 1;
			var stacks = 1;
			var remainingAmount = 0;
			var RestVorhanden = false;
			var totalProduction = xLimit - AllProds[0].Queue;
			if(isNaN(totalProduction) || totalProduction <= 0){return;}
			if (totalProduction > 25) {
				amount = 25;
				stacks = Math.floor(totalProduction / 25);
				remainingAmount = totalProduction - (stacks * 25);
			} else {
				amount = totalProduction;
			}
			if(remainingAmount > 0){
				RestVorhanden = true;
			}
			else
			{
				RestVorhanden = false;
			}
			var dTimedProductionVO = swmmo.getDefinitionByName("Communication.VO::dTimedProductionVO");
			var timedProductionVO = new dTimedProductionVO();
			timedProductionVO.productionType = ProductionTypeBuff;
			timedProductionVO.type_string = AllProds[0].SelectedOrderType;
			timedProductionVO.amount = amount;
			timedProductionVO.stacks = stacks;
			timedProductionVO.buildingGrid = AllProds[0].Grid;
			if(RestVorhanden)
			{
				var dTimedProductionVO2 = swmmo.getDefinitionByName("Communication.VO::dTimedProductionVO");
				var timedProductionVO2 = new dTimedProductionVO2();
				timedProductionVO2.productionType = ProductionTypeBuff;
				timedProductionVO2.type_string = AllProds[0].SelectedOrderType;
				timedProductionVO2.amount = remainingAmount;
				timedProductionVO2.stacks = 1;
				timedProductionVO2.buildingGrid = AllProds[0].Grid;
			}
			var EnoughRessi = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
			var HasRessiForProd = true;
			Object.keys(AllProds[0].Costs).forEach(function(itemcost) {
				if (EnoughRessi.HasPlayerResource(itemcost, AllProds[0].Costs[itemcost]*totalProduction))
				{
				}
				else
				{
					HasRessiForProd = false;
				}
			});

			if(HasRessiForProd && AllProds[0].Queue < xLimit && game.gi.isOnHomzone() == true)
			{
				if(FirstClientStart2 && game.gi.isOnHomzone() == true)
				{
					globalFlash.gui.ShowBuilding(Realname);
					RefreshGUIBUI();
				}
				game.gi.mClientMessages.SendMessagetoServer(91, game.gi.mCurrentViewedZoneID, timedProductionVO);
				game.showAlert(Name + "("+AllProds[0].Grid+")" +": " + (totalProduction - remainingAmount) + ' ' + AllProds[0].Name + getText('ProdQueue', 'SemiAutoATMenuLang'));
				if(RestVorhanden)
				{
					game.gi.mClientMessages.SendMessagetoServer(91, game.gi.mCurrentViewedZoneID, timedProductionVO2);
					game.showAlert(Name + "("+AllProds[0].Grid+")" +": " + remainingAmount + ' ' + AllProds[0].Name + getText('ProdQueue', 'SemiAutoATMenuLang'));
				}
			}
			else
			{
				if(FirstClientStart2 && game.gi.isOnHomzone() == true)
				{
					globalFlash.gui.ShowBuilding(Realname);
					RefreshGUIBUI();
				}
				//game.showAlert(Name + "("+AllProds[0].Grid+")" +": " + AllProds[0].Name + ' Produktionswarteschlange > Limit oder keine Ressourcen!');
			}
		}
		catch(e) {}
	}
	else
	{
		if(game.gi.isOnHomzone() == false) {
		game.showAlert(getText('not_home'));
		return;
		}
		try
		{
			var BuiBuffGrid;
			var ProductionTypeBuff;
			var CurrentQueue = 0;
			
			try
			{
				
				game.zone.mStreetDataMap.GetBuildings_vector().forEach(function(item){
				if (item === null) { return; }
				
					if(item.GetBuildingName_string() == Realname && item.GetGrid() == Grid)
					{
						CurrentQueue = item.productionQueue.mTimedProductions_vector.length;
						BuiBuffGrid = Grid;
						ProductionTypeBuff = item.productionQueue.mProductionType;
						
						if (ProductionTypeBuff === ProductionTypeBuff) {
							return;
						}
					}	
				});
			}
			catch(e) {game.showAlert(getText('BuildingProdError', 'SemiAutoATMenuLang'));}	
			
			var AllProds = [];
				
				swmmo.getDefinitionByName("global").timedProductions_vector[ProductionTypeBuff].forEach(function(prod) {
					try
					{
						
						if(prod.name_string == BuffID)
						{
							if(swmmo.getDefinitionByName("BuffSystem::BuffAdventureController").isBuffAdventureBuff(prod.name_string))
							{
								return;
							}
							var CostRess = {};
										
							prod.costs_vector.forEach(function(CostRessinner) {
								if (CostRessinner != null)
								{
									CostRess[CostRessinner.name_string] = CostRessinner.amount;
								}
							});

							var buffdata = {
								Name : loca.GetText("RES", prod.name_string),
								Costs : CostRess,
								SelectedOrderType : prod.GetType(),
								Queue : CurrentQueue,
								Grid : BuiBuffGrid
							};
							AllProds.push(buffdata);
						}
					}
					catch (e)
					{
					}
				});
			
			var FinalAmount = xLimit - AllProds[0].Queue;
			var dTimedProductionVO = swmmo.getDefinitionByName("Communication.VO::dTimedProductionVO");
			var timedProductionVO = new dTimedProductionVO();
			timedProductionVO.productionType = ProductionTypeBuff;
			timedProductionVO.type_string = AllProds[0].SelectedOrderType;
			timedProductionVO.amount = 1;
			timedProductionVO.stacks = FinalAmount;
			timedProductionVO.buildingGrid = AllProds[0].Grid;
			var EnoughRessi = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
			var HasRessiForProd = true;
			Object.keys(AllProds[0].Costs).forEach(function(itemcost) {
				if (EnoughRessi.HasPlayerResource(itemcost, AllProds[0].Costs[itemcost]*FinalAmount))
				{
				}
				else
				{
					HasRessiForProd = false;
				}
			});

			if(HasRessiForProd && AllProds[0].Queue < xLimit && game.gi.isOnHomzone() == true)
			{
				if(FirstClientStart2 && game.gi.isOnHomzone() == true)
				{
					globalFlash.gui.ShowBuilding(Realname);
					RefreshGUIBUI();
				}
				game.gi.mClientMessages.SendMessagetoServer(91, game.gi.mCurrentViewedZoneID, timedProductionVO);
				game.showAlert(Name + "("+AllProds[0].Grid+")" +": " + FinalAmount + ' ' + AllProds[0].Name + getText('ProdQueue', 'SemiAutoATMenuLang'));
			}
			else
			{
				if(FirstClientStart2 && game.gi.isOnHomzone() == true)
				{
					globalFlash.gui.ShowBuilding(Realname);
					RefreshGUIBUI();
				}
				//game.showAlert(Name + "("+AllProds[0].Grid+")" +": " + AllProds[0].Name + ' Produktionswarteschlange > Limit oder keine Ressourcen!');
			}
		}
		catch(e) {}
	}
}

