function GetProdFromMayor(Realname, BuffID, Name, Grid, xLimit)
{
	if(game.gi.isOnHomzone() == false) {
		game.showAlert(getText('not_home'));
		return;
	}
		try
		{
		
			var prodQueue0 = swmmo.application.mGameInterface.mCurrentPlayerZone.GetProductionQueue(4);
			for(var i = 0; i < prodQueue0.mTimedProductions_vector.length; i++){
				
				var item = prodQueue0.mTimedProductions_vector[i];
				var productionVO = item.GetProductionOrder().GetProductionVO();
			};
			
			if(productionVO.producedItems == 1)
			{
				var prodQueue4 = swmmo.application.mGameInterface.mCurrentPlayerZone.GetProductionQueue(4); 
				var cPlayerData = swmmo.application.mGameInterface.mHomePlayer;
				var IncCollectedTime = true;
				prodQueue4.finishProduction(cPlayerData, IncCollectedTime);
				game.gi.mClientMessages.SendMessagetoServer(141, game.gi.mCurrentViewedZoneID, 4);
			}
		}catch(e){}
}

