function displayToTargetFast(targetAmount, unAssigned, assigned, name){
	var toTarget = targetAmount - unAssigned - assigned;
	if(toTarget <= 0){
		return '<span style="color: green;font-weight:900;">'+getText("Over target", 'RebuildLosses_translationsFast')+'</span>';
	} else if(toTarget <= inProductionFast[name]){
		totalRequiredProductionFast += toTarget;
		return '<span style="color: orange;font-weight:900;">'+toTarget+'</span>';
	}
	else{
		newRequiredProductionFast += toTarget;
		return '<span style="color: red; font-weight:900;">'+toTarget+'</span>';
	}
}

