function TriggerProductionFast(unitName, amount, stacks, isElite){
	var MILITARY_UNIT = 0;
	var ELITE_UNITS = 8;
	var dTimedProductionVOFast = swmmo.getDefinitionByName("Communication.VO::dTimedProductionVO");
	var cTimedProductionUtlFast = swmmo.getDefinitionByName("TimedProduction::cTimedProductionUtl");
	if(!unitName || !amount || !stacks){
		return;
	}
	var barracks_name = "Barracks";
	var elitteBarracks_name = "EliteBarracks";
	var timedProductionVOFast = new dTimedProductionVOFast();

	var buildingGrid = game.zone.mStreetDataMap.getBuildingByName(barracks_name).GetGrid();
	timedProductionVOFast.productionType = MILITARY_UNIT;
	// game.zone.mStreetDataMap.getBuildingByName(barracks_name).GetGrid();
	if(isElite){
		buildingGrid = game.zone.mStreetDataMap.getBuildingByName(elitteBarracks_name).GetGrid();
		timedProductionVOFast.productionType = ELITE_UNITS;
	}

	timedProductionVOFast.type_string = unitName;
	timedProductionVOFast.amount = amount; // how many units to produce
	timedProductionVOFast.stacks = stacks; // how many times to repeat
	timedProductionVOFast.buildingGrid = buildingGrid;
	var START_TIMED_PRODUCTION = 91;
	game.gi.mClientMessages.SendMessagetoServer(START_TIMED_PRODUCTION, game.gi.mCurrentViewedZoneID, timedProductionVOFast);
	showAlert(getText("Queued", 'RebuildLosses_translationsFast')+" "+amount*stacks+" "+getText(unitName, 'RebuildLosses_translationsFast'));
}

function getBarracksProductionQueueFast(){
	var prodQueue0Fast = swmmo.application.mGameInterface.mCurrentPlayerZone.GetProductionQueue(0);

	if(!prodQueue0Fast){
		return;
	}

	for(var i = 0; i < prodQueue0Fast.mTimedProductions_vector.length; i++){
		var item = prodQueue0Fast.mTimedProductions_vector[i];
		var productionVO = item.GetProductionOrder().GetProductionVO();
		if(!inProductionFast[productionVO.type_string]){
			inProductionFast[productionVO.type_string] = 0;
		}
		inProductionFast[productionVO.type_string] += productionVO.amount;
	};
	return inProductionFast;
}
function getElitteBarracksProductionQueueFast(){
	var prodQueue8 = swmmo.application.mGameInterface.mCurrentPlayerZone.GetProductionQueue(8);

	if(!prodQueue8){
		return;
	}

	for(var i = 0; i < prodQueue8.mTimedProductions_vector.length; i++){
		var item = prodQueue8.mTimedProductions_vector[i];
		var productionVO = item.GetProductionOrder().GetProductionVO();
		if(!inProductionFast[productionVO.type_string]){
			inProductionFast[productionVO.type_string] = 0;
		}
		inProductionFast[productionVO.type_string] += productionVO.amount;
	};
	return inProductionFast;
}

function jz_QueueBarracksFast(){
	var unitName = this.getAttribute("data-unit");
	var isplus50 = this.getAttribute('plus50');
	var isplus250 = this.getAttribute('plus250');
	var isplus500 = this.getAttribute('plus500');


	var amount = 1;
	var stacks = 1;
	var lessThan25 = 0;

	if(isplus50){
		amount = 25;
		stacks = 2;
	}
	if(isplus250){
		amount = 25;
		stacks = 10;
	}
	if(isplus500){
		amount = 25;
		stacks = 20;
	}
	if(!isplus50 && !isplus250 && !isplus500){
		var totalProduction = productionDetailsFast[unitName].toTarget;
		if(isNaN(totalProduction) || totalProduction <= 0){return;}
		allDisabledFast = true;

		if(totalProduction > 25){
			amount = 25;
		} else {
			amount = totalProduction;
		}
		if(totalProduction > 25){
			stacks = Math.floor(totalProduction / 25);
		}
		lessThan25 = totalProduction - (stacks * 25);
	}
	var isElite = false;
	var eliteUnits = ["MountedMarksman", "MountedSwordsman", "Knight", "Besieger", "ArmoredMarksman", "Swordsman", "Marksman"];
	if(eliteUnits.indexOf(unitName) > -1){
		isElite = true;
	}
	if(enoughResourcesFast(unitName, amount*stacks)){
		TriggerProductionFast(unitName, amount, stacks, isElite);
		if(lessThan25 > 0){
			TriggerProductionFast(unitName, lessThan25, 1, isElite);
		}
		allDisabledFast = true;
		RebuildLossesFast();
	} else {
		allDisabledFast = false;
		RebuildLossesFast();
		return;
	}

	setRefreshTimeoutFast();
}

function setRefreshTimeoutFast(){
	setTimeout(function(){
		allDisabledFast = false;
		RebuildLossesFast();
	}, 4000);
}

function enoughResourcesFast(unitName, amount){
	var resourcesFast = swmmo.application.mGameInterface.mCurrentPlayerZone.GetResourcesForPlayerID(game.player.GetPlayerId());
	var resourceNamesFast = ["Population", "Beer", "BronzeSword", "Bow", "IronSword", "Horse", "Longbow", "SteelSword",
						 "Crossbow", "TitaniumSword", "Cannon", "PlatinumSword", "BattleHorse", "Archebuse"];
	var resourceAmounts = {};
	resourceNamesFast.forEach(function(item){
		resourceAmounts[item] = resourcesFast.GetPlayerResource(item).amount;
	});
	var unitCost = getUnitCostFast(unitName);
	var totalCost = {};
	for(var key in unitCost){
		totalCost[key] = unitCost[key] * amount;
	}
	for (var resource in totalCost) {
		if (totalCost[resource] > resourceAmounts[resource]) {
			showAlert(
				getText("Not enough", "RebuildLosses_translationsFast") +
				" " +
				getText(resource, "RebuildLosses_translationsFast") +
				": " +
				resourceAmounts[resource] +
				" / " +
				totalCost[resource] +
				" " +
				getText("required", "RebuildLosses_translationsFast")
			);
			return false;
		}
	}
	return true;
}

