function GebaeudeGuildFestEinlesenForBuff_1(Realnames) {
    if (game.gi.mCurrentPlayer.mIsAdventureZone == true) {
        return { data: [] };
    }
    try {
        var AllBUIEinlesen = [];
        game.zone.mStreetDataMap.GetBuildings_vector().forEach(function(item) {
            if (item === null) { return; }
            Realnames.forEach(function(Realname) {
                if (item.GetBuildingName_string() == Realname) {
                    var BUIWithGrid = item.GetGrid();
                    var BUIWithGridName = item.GetBuildingName_string();
                    var BUIdataEinlesen = {
                        buffName: "ProvisionerBuffLvlGuildFestGrounds1",
                        buiGrid: BUIWithGrid,
                        buiName: BUIWithGridName
                    };
                    AllBUIEinlesen.push(BUIdataEinlesen);
                }
            });
        });
        return { data: AllBUIEinlesen };
    } catch (e) {
        game.showAlert(getText('BuildingBuffError', 'SemiAutoATMenuLang'));
        return { data: [] };
    }
}

