function checkBuffType3(type)
{
	availableBuffTypes3 = ["ProductivityBuff", "RecruitingBuff", "ProvisionerBuff", "BookbinderBuff", "AreaBuff", "RemoveBuff"];
	return availableBuffTypes3.filter(function(item) { return type.indexOf(item); }).length > 0;
}

function getBuffAvailableCount3(buffName)
{
	var buffVectorGetName = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();
	
	buffsAvailable3[buffName] = {count: 0, id: ''};
	buffVectorGetName.every(function(item){
		
		if(item.GetBuffDefinition().GetName_string() == buffName) {
			buffsAvailable3[buffName].count = item.GetAmount();
			buffsAvailable3[buffName].id = item.GetUniqueId().uniqueID1 + '_' + item.GetUniqueId().uniqueID2;
			return false;
		}
		return true;
	});
	return buffsAvailable3[buffName].count;
}

function buffDoJob3(Daten) {
    var buffRecordFiltered3 = [];
    var status3;
    var buinull;

    $.each(Daten['data'], function(index, data) {
        status3 = "buff_ready";
        buinull = false;

        var bui = game.zone.GetBuildingFromGridPosition(data['buiGrid']);
        if (bui == null) {
            buinull = true;
            status3 = "buff_not_exist";
        }
        if (!buinull && bui.GetBuildingName_string() != data['buiName']) {
            status3 = "buff_wrong_name";
        }
        if (!buinull && bui.productionBuff != null && checkBuffType3(bui.productionBuff.GetBuffDefinition().GetName_string())) {
            status3 = "buff_buffed";
        }
        if (!buinull && mainSettings.buffOnlyActive && (!bui.IsProductionActive() || bui.IsUpgradeInProgress())) {
            status3 = "buff_notactive";
        }
        if (!buinull && mainSettings.buffOnlyActive && bui.GetResourceCreation() != null && bui.GetResourceCreation().GetProductionState() != 0) {
            status3 = "buff_notactive";
        }

        if (data['buffName'].indexOf("RemoveBuff") >= 0) {
            if (status3 == "buff_buffed") {
                status3 = "buff_ready";
            } else if (status3 == "buff_ready") {
                status3 = "buff_not_buffed";
            }
        }

        if (status3 == "buff_ready" && getBuffAvailableCount3(data['buffName']) > 0) {
            buffRecordFiltered3.push(data);				
        }
    });

    var xbuffDoJob3 = new TimedQueue(1000);
    $.each(buffRecordFiltered3, function(i, item) {
        if (buffsAvailable3[item.buffName].count > 0) {
            buffsAvailable3[item.buffName].count -= 1;
            xbuffDoJob3.add(function() {
                sendBuffPacket(buffsAvailable3[item.buffName].id, item.buiGrid);
            });
        }
    });
    xbuffDoJob3.run();
}
