var uQUESTSYSTEM_TYPES = [
					"DailyQuest", "GuildfestQuest", "GuildQuest", "WeeklyQuest", "LoveGardenQuest", "GhostShipQuest", "PathfinderShipQuest", "TalentBonusQuest"
	];

function uQUESTSYSTEM_MainWindow(event)
{
	try
	{
		if (!game.gi.isOnHomzone())
		{
			game.showAlert(getText('not_home'));
			return;
		}
		$("div[role='dialog']:not(#usQuestSystemModal):visible").modal("hide");
		$('#usQuestSystemModal').remove();
		$('#usQuestSystemstyle').remove();
		$("head").append($("<style>", { 'id': 'usQuestSystemstyle' }).text('#usQuestSystemModal div .row:hover {background-color: #A65329;}'));
		createModalWindow('usQuestSystemModal', getText('Title', 'uQUESTSYSTEMLang'));

		$("#usQuestSystemModal .modal-header").append(
			createTableRow([
				[1, getText("lblOpenCheck", 'uQUESTSYSTEMLang')],
				[11, getText("lblBoxType", 'uQUESTSYSTEMLang')]
			], true)
		);
		uQUESTSYSTEM_MakeCentralDIV();

		$("#usQuestSystemModal .modal-footer").prepend([
			$('<button>').attr({ "id": "usQuestSystemApply",'style': 'margin-left: 4px;', "class": "btn btn-primary pull-left usQuestSystemApply" }).text(getText("Apply", 'uQUESTSYSTEMLang')),
			$('<button>').attr({ "id": "usQuestSystemExecute",'style': 'margin-left: 4px;', "class": "btn btn-primary pull-left usQuestSystemExecute" }).text(getText("Execute", 'uQUESTSYSTEMLang')),
		]);
		$('#usQuestSystemModal .usQuestSystemApply').click(function(){
			settings.settings["_usQuestSystem"] = {};
			_exQUESTSYSTEM_Settings.QUESTTYPES = [];
			for(var x = 0; x < uQUESTSYSTEM_TYPES.length; x++)
				{
					var c = "#uQUESTSYSTEM_sw_" + x;
					var isSel = $(c).prop("checked");
					if (isSel)
					{
						var name = uQUESTSYSTEM_TYPES[x];
						_exQUESTSYSTEM_Settings.QUESTTYPES.push(name);
					}
				}
				storeSettings(_exQUESTSYSTEM_Settings, '_usQuestSystem');
				game.showAlert(getText('SettingsSave', 'SemiAutoATMenuLang'));
		});
		$('#usQuestSystemModal .usQuestSystemExecute').click(function(){
			QuestComplete();
			$('#usQuestSystemModal').modal('hide');
		});
		$('#usQuestSystemModal:not(:visible)').modal({ backdrop: "static" });
	}
	catch (mwerr)
	{
		uQUESTSYSTEM_Message("Quest error : " + mwerr);	
	}
}
function uQUESTSYSTEM_MakeCentralDIV()
{
	try
	{
		$('#usQuestSystemModalData').html('<div class="container-fluid">{0}</div>'.format(uQUESTSYSTEM_MakeTableData()));
	}
	catch (e)
	{
			uQUESTSYSTEM_Message("MakeCentralDIV : " + e);	
	}

}
function uQUESTSYSTEM_MakeTableData() {
    var tableData = [];

    try {
        for (var x = 0; x < uQUESTSYSTEM_TYPES.length; x++) {
            var isSel = (_exQUESTSYSTEM_Settings.QUESTTYPES.indexOf(uQUESTSYSTEM_TYPES[x]) >= 0);
            var text = getText(uQUESTSYSTEM_TYPES[x], 'uQUESTSYSTEMLang');

            tableData.push({ switchValue: createSwitch("uQUESTSYSTEM_sw_" + x, isSel), text: text });
        }

        tableData.sort(function(a, b) {
            return a.text.localeCompare(b.text);
        });

        var out = "";
        for (var i = 0; i < tableData.length; i++) {
            out += createTableRow([
                [1, tableData[i].switchValue],
                [11, tableData[i].text]
            ], false);
        }
    } catch (e) {
        uQUESTSYSTEM_Message("MakeTbl : " + e);
    }
    return out;
}

function uQUESTSYSTEM_Message(Text) 
{
	game.showAlert(Text);
}

function QuestComplete(e) {
    try {
        if (!game.gi.isOnHomzone()) {
            game.showAlert(getText('not_home'));
            return;
        }

        game.gi.mQuestClientCallbacks.JustRefresh();
        globalFlash.gui.mQuestBook.Show();
        globalFlash.gui.mQuestBook.Hide();

        function processQuests(quests, isPaymentPhase) {
            for (var i = 0; i < quests.length; i++) {
                var itemQuest = quests[i];
                if (!itemQuest || !itemQuest.IsQuestActive()) continue;

                var questName = itemQuest.GetQuestDefinition().questName_string;
                var questMode = itemQuest.GetQuestMode().toString();

                var questTypes = {
                    DailyQuest: questName.indexOf("Dai") === 0 && questName[3] === questName[3].toUpperCase(),
                    GuildQuest: questName.indexOf("GuiDai") === 0 && questName[6] === questName[6].toUpperCase(),
                    WeeklyQuest: questName.indexOf("WeeklyChallenge_") === 0,
                    LoveGardenQuest: questName.indexOf("LoveGarden_") === 0 && questName.indexOf("LoveGarden_OnMapFirst") !== 0,
                    GuildfestQuest: questName.indexOf("GuildFest_") === 0,
                    GhostShipQuest: questName.indexOf("BuiBonus_GhostLantern_") === 0,
                    TalentBonusQuest: questName.indexOf("SophisticatedPillager_") === 0 || questName.indexOf("StreetwiseNegotiator_") === 0
                };

                for (var type in questTypes) {
                    if (questTypes.hasOwnProperty(type) && questTypes[type] && _exQUESTSYSTEM_Settings.QUESTTYPES.indexOf(type) >= 0 && ["12", "1", "10", "9"].indexOf(questMode) === -1 && itemQuest.mNewTriggersFinished) {
                        if (isPaymentPhase && !itemQuest.isFinished() && game.gi.isOnHomzone()) {
                            game.gi.mQuestClientCallbacks.InitiatePayForQuestFinish(itemQuest.mUniqueID);
                        } else if (!isPaymentPhase && itemQuest.isFinished() && game.gi.isOnHomzone()) {
                            game.showAlert(getText('QuestDone', 'SemiAutoATMenuLang') + ": " + loca.GetText("QUL", questName) + " (" + type + ")");
                            globalFlash.gui.mQuestBook.SetPreselectedQuest(itemQuest);
                            globalFlash.gui.mQuestBook.Show();
                            game.gi.mNewQuestManager.RewardOkButtonPressedFromGui(itemQuest);
                            globalFlash.gui.mQuestBook.Hide();
                        }
                    }
                }
            }
        }

        setTimeout(function () {
            processQuests(game.gi.mNewQuestManager.GetQuestPool().GetQuest_vector(), true);
        }, 5000);

        setTimeout(function () {
            processQuests(game.gi.mNewQuestManager.GetQuestPool().GetQuest_vector(), false);
        }, 30000);
		
		try{
			if(game.gi.isOnHomzone() && _exQUESTSYSTEM_Settings.QUESTTYPES.indexOf("PathfinderShipQuest") >= 0)
			{
				globalFlash.gui.mTaskBuildingPanel.SetData(game.zone.mStreetDataMap.getBuildingByName("TaskBuilding"));
				setTimeout(function () {
					globalFlash.gui.mTaskBuildingPanel.Show();
					globalFlash.gui.mTaskBuildingPanel.Hide();
				}, 3000);
			}
		}catch(e){}
		
		function processQuestsPathfinder(isPaymentPhase) {
			var DoPathFinder = new TimedQueue(2000);
			var DoPathFinder2 = new TimedQueue(2000);
			var taskManager = game.gi.getCurrentTaskManager();
			if(taskManager == null) return;
			
			if (isPaymentPhase && game.gi.isOnHomzone() && _exQUESTSYSTEM_Settings.QUESTTYPES.indexOf("PathfinderShipQuest") >= 0) 
			{
				var Tasks = taskManager.getChildTasks(taskManager.getCategoryByName('TaskBuilding'));
				var processedTaskIds = {};

				$.each(Tasks, function(i, Task) {
					var taskId = Task.getId();
					var state = Task.getState();
					var taskName = Task.getDefinition().getName();

					if (state !== 0 || processedTaskIds[taskId]) return;

					var shouldProcess = false;

					$.each(Task.getTriggers(), function(t, Trigger) {
						var def = Trigger.getDefinition();
						if (def.action_string === "paytofinish" && Trigger.isRunning() && !Trigger.getFinished()) {
							shouldProcess = true;
							return false;
						}
					});

					if (shouldProcess) {
						processedTaskIds[taskId] = true;

						DoPathFinder.add((function(id, name) {
							return function() {
							if(game.gi.isOnHomzone())
							{
								game.gi.mClientMessages.SendMessagetoServer(162, game.gi.mCurrentViewedZoneID, id);
								game.showAlert(getText('PfadfinderQuest', 'uQUESTSYSTEMLang') + loca.GetText("QUL", name) + getText('Payed', 'uQUESTSYSTEMLang') + " ID: " + id);
								//debug(getText('PfadfinderQuest', 'uQUESTSYSTEMLang') + loca.GetText("QUL", name) + getText('Payed', 'uQUESTSYSTEMLang') + " ID: " + id);
							}
							};
						})(taskId, taskName));
					}
				});

				DoPathFinder.run();
            } 
			else if (!isPaymentPhase && game.gi.isOnHomzone() && _exQUESTSYSTEM_Settings.QUESTTYPES.indexOf("PathfinderShipQuest") >= 0)
			{
				var updatedTasks = taskManager.getChildTasks(taskManager.getCategoryByName('TaskBuilding'));

				$.each(updatedTasks, function(i, Task) {
					if (Task.getState() === 1) {
						var taskId = Task.getId();
						var taskName = Task.getDefinition().getName();
						DoPathFinder2.add((function(id, name) {
						return function() {
							if(game.gi.isOnHomzone())
							{
								game.gi.mClientMessages.SendMessagetoServer(161, game.gi.mCurrentViewedZoneID, id);
								game.showAlert(getText('PfadfinderQuest', 'uQUESTSYSTEMLang') + loca.GetText("QUL", name) + getText('Finished', 'uQUESTSYSTEMLang') + " ID: " + id);
								//debug(getText('PfadfinderQuest', 'uQUESTSYSTEMLang') + loca.GetText("QUL", Task.getDefinition().getName()) + getText('Finished', 'uQUESTSYSTEMLang'));
							}
						};
							})(taskId, taskName));
						}
				});

				DoPathFinder2.run();      
            }
		}
		
		setTimeout(function () {
            processQuestsPathfinder(true);
        }, 5000);

        setTimeout(function () {
            processQuestsPathfinder(false);
        }, 30000);

    } catch (ex) {
        uQUESTSYSTEM_Message(ex);
    }
}
