function _exudTradepost_MainWindow(event)
{
	try
	{
		if (!game.gi.isOnHomzone())
		{
			game.showAlert(getText('not_home'));
			return;
		}
		
		SlotsCount = 11 - game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(0) - game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(2);

		$("div[role='dialog']:not(#usTradepostModal):visible").modal("hide");

		$('#usTradepostModal').remove();

		createModalWindow('usTradepostModal', utils.getImageTag('icon_dice.png', '45px') + ' '+ getText('Title', '_exudTradepostLang'));

		var select_resourcesSend = $('<select>', { id: '_SelectResourcesSendTradepost' });
		select_resourcesSend.append($('<option>', { value:"---" }).text("---")).prop("outerHTML");
		
		var select_resourcesRec = $('<select>', { id: '_SelectResourcesRecTradepost' });
		select_resourcesRec.append($('<option>', { value:"---" }).text("---")).prop("outerHTML");
		
		var select_posts = $('<select>', { id: '_SelectPostTradepost' });
		for (var i = 1; i <= 4; i++) {
			select_posts.append($('<option>', { value: i }).text(i));
		}
		select_posts.prop("outerHTML");

		_Tradepost_Resources.forEach(function(item) {
			select_resourcesSend.append($('<option>', { value: item }).text(loca.GetText("RES", item))).prop("outerHTML");
			select_resourcesRec.append($('<option>', { value: item }).text(loca.GetText("RES", item))).prop("outerHTML");
		});
		
		select_resourcesSend.find('option').sort(function (a, b) {
			return a.text.localeCompare(b.text);
		}).appendTo(select_resourcesSend);
		
		select_resourcesRec.find('option').sort(function (a, b) {
			return a.text.localeCompare(b.text);
		}).appendTo(select_resourcesRec);

		$("#usTradepostModal .modal-header").append('<br><div class="container-fluid">' 
		+
			createTableRow([
				[3, $('<span>').attr({ "id": "freeSlotsText" }).text(getText('FreeSlots', '_exudTradepostLang') + SlotsCount)],
				[4, ""],
				[3, ""],
				[3, ""]
				], false)
		+	'<br>'
		+
			createTableRow([
				[3,  getText('Send', '_exudTradepostLang')],
				[4 , select_resourcesSend.prop("outerHTML")],
				[3, '<input type="text" style="color:black;width:80px" id="exudTradepostSelectAmountSend"/>'],
				[3, ""]
				], false)
		+	createTableRow([
				[3,  getText('Receive', '_exudTradepostLang')],
				[4, select_resourcesRec.prop("outerHTML")],
				[3, '<input type="text" style="color:black;width:80px" id="exudTradepostSelectAmountReceive"/>'],
				[3, ""]
				], false)
		+
			createTableRow([
				[3,  getText('Posten', '_exudTradepostLang')],
				[4 , select_posts.prop("outerHTML")],
				[3, ""],
				[3, ""]
				], false)
		+	createTableRow([
				[5, ""],
				[2, ""],
				[4, $('<button>').attr({ "id": "exudTradepostSendItem", "class": "btn btn-primary" }).text(getText('BtnSend', '_exudTradesLang'))],
				[3, ""]
				], false)
		+	'<br>'
		+	createTableRow([
				[5, getText('BtnAddInfo', '_exudTradepostLang')],
				[2, ""],
				[4, $('<button>').attr({ "id": "exudTradepostAddItem", "class": "btn btn-primary" }).text(getText('BtnAdd', '_exudTradepostLang'))],
				[3, ""]
				], false)
		+	'<br>'
		+	createTableRow([
				[12,  getText('TradeListTitle', '_exudTradepostLang')]
				], true)
		);
	
		$('#exudTradepostSendItem').click(function () { 
			var button = $(this);
			var originalText = button.text();

			button.prop('disabled', true).text(getText('Wait', '_exudTradepostLang'));

			var buttons2 = $('#usTradepostModalData .exudTradepostSendItem2');
			var originalTexts2 = [];
			buttons2.each(function (index, btn) {
				originalTexts2[index] = $(btn).text();
				$(btn).prop('disabled', true).text(getText('Wait', '_exudTradepostLang'));
			});

			_exudTradepost_SendItem();

			setTimeout(function () {
				button.prop('disabled', false).text(originalText);

				buttons2.each(function (index, btn) {
					$(btn).prop('disabled', false).text(originalTexts2[index]);
				});
				SlotsCount = 11 - game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(0) - game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(2);
				$('#freeSlotsText').text(getText('FreeSlots', '_exudTradepostLang') + SlotsCount);
			}, 15000);
		});
		
		$('#exudTradepostAddItem').click(function () { _exudTradepost_AddItem(); });
		
		_exudTradepost_MakeCentralDIV();

		$('#usTradepostModal:not(:visible)').modal({ backdrop: "static" });
	}
	catch (e)
	{
	}
}

function _exudTradepost_SendItem()
{
	try
	{
		var SendRec = $('#_SelectResourcesSendTradepost option:selected').val();
		var RecRec = $('#_SelectResourcesRecTradepost option:selected').val();
		var SendAm = parseInt($("#exudTradepostSelectAmountSend").val());
		var RecAm = parseInt($("#exudTradepostSelectAmountReceive").val());
		var Posten = parseInt($('#_SelectPostTradepost option:selected').val());

		if (SendRec == "---" || RecRec == "---" || SendAm < 1 || RecAm < 1)
			return;

		var t = new Date().getTime();
		var tr = {
					'ID' : t ,
					'SendResource' : SendRec,
					'SendAmount' : SendAm,
					'ReceiveResource' : RecRec,
					'ReceiveAmount' : RecAm,
					'Posten' : Posten
				};
		
		var trade = tr;
		
		var EnoughRessiTrade = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
		var HasRessiForTrade = false;
		if (EnoughRessiTrade.HasPlayerResource(trade.SendResource, trade.SendAmount*trade.Posten))
		{
			HasRessiForTrade = true;
		}
		else
		{
			HasRessiForTrade = false;
		}
		
		if(HasRessiForTrade)
		{
			setTimeout(function() {
				try
				{
					if (!game.gi.isOnHomzone())
					{
						game.showAlert(getText('not_home'));
						return;
					}
					var TOffDef = swmmo.getDefinitionByName("Communication.VO::dTradeOfferVO");
					var ResDef = swmmo.getDefinitionByName("Communication.VO::dResourceVO");
					var TOff = new TOffDef();
					var resOffer = new ResDef().init(trade.SendResource, trade.SendAmount);
					var resCost = new ResDef().init(trade.ReceiveResource, trade.ReceiveAmount);
					TOff.offerRes = resOffer; 
					TOff.costsRes = resCost; 
					TOff.receipientId = 0;
					TOff.lots = trade.Posten;
					if(game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(0) == 0)
					{
						TOff.slotPos = game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(0);
						TOff.slotType = 0;
						game.showAlert("TradeSlotPos(free): " + TOff.slotPos);
					}
					else
					{
						TOff.slotPos = game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(2);
						TOff.slotType = 2;
						game.showAlert("TradeSlotPos(coin): " + TOff.slotPos);
					}
					if(TOff.slotPos >= 10)
					{
						game.showAlert("TradeSlotPos(coin): " + TOff.slotPos + " | Limit reached!");
						return;
					}
					game.gi.mClientMessages.SendMessagetoServer(1049, game.gi.mCurrentViewedZoneID, TOff);
				}
				catch (e)
				{		
				}
			},2000);
		}
		else
		{
			game.showAlert(getText('TradeNotSend', 'SemiAutoATMenuLang'));
		}
	}
	catch (e)
	{
	}
}

function _exudTradepost_AddItem()
{
	try
	{
		var SendRec = $('#_SelectResourcesSendTradepost option:selected').val();
		var RecRec = $('#_SelectResourcesRecTradepost option:selected').val();
		var SendAm = parseInt($("#exudTradepostSelectAmountSend").val());
		var RecAm = parseInt($("#exudTradepostSelectAmountReceive").val());
		var Posten = parseInt($('#_SelectPostTradepost option:selected').val());
		if (SendRec == "---" || RecRec == "---" || SendAm < 1 || RecAm < 1)
			return;

		var t = new Date().getTime();
		var tr = {
					'ID' : t ,
					'SendResource' : SendRec,
					'SendAmount' : SendAm,
					'ReceiveResource' : RecRec,
					'ReceiveAmount' : RecAm,
					'Posten' : Posten
				};
		
		var trade = tr;
		
		_exudTradepost_Settings.Trades[t] = trade;
		storeSettings(_exudTradepost_Settings, '_usTradepost');
		_exudTradepost_MakeCentralDIV();
	}
	catch (e)
	{
	}
}

function _exudTradepost_MakeCentralDIV()
{
	try
	{
		$('#usTradepostModalData').html('<div class="container-fluid">{0}</div>'.format(_exudTradepost_MakeTableData()));

		$('#usTradepostModalData .exudTradepostDelItem').click(function (e) {
			try{
				delete _exudTradepost_Settings.Trades[$(this).val()];
				storeSettings(_exudTradepost_Settings, '_usTradepost');
				_exudTradepost_MakeCentralDIV();	
			}
			catch (a)
			{
			}
		});
		
		$('#usTradepostModalData .exudTradepostSendItem2').click(function () { 
			var clickedButton = $(this);
			var originalTextClicked = clickedButton.text();

			clickedButton.prop('disabled', true).text(getText('Wait', '_exudTradepostLang'));

			var button1 = $('#exudTradepostSendItem');
			var originalText1 = button1.text();
			button1.prop('disabled', true).text(getText('Wait', '_exudTradepostLang'));

			var buttons2 = $('#usTradepostModalData .exudTradepostSendItem2');
			var originalTexts2 = [];
			buttons2.each(function (index, btn) {
				if (btn !== clickedButton[0]) {
					originalTexts2[index] = $(btn).text();
					$(btn).prop('disabled', true).text(getText('Wait', '_exudTradepostLang'));
				}
			});

			_exudTradepost_SendItem2(clickedButton.val());

			setTimeout(function () {
				clickedButton.prop('disabled', false).text(originalTextClicked);
				button1.prop('disabled', false).text(originalText1);

				buttons2.each(function (index, btn) {
					if (btn !== clickedButton[0]) {
						$(btn).prop('disabled', false).text(originalTexts2[index]);
					}
				});
				SlotsCount = 11 - game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(0) - game.gi.mHomePlayer.mTradeData.getNextFreeSlotForType(2);
				$('#freeSlotsText').text(getText('FreeSlots', '_exudTradepostLang') + SlotsCount);
			}, 15000);
		});

	}
	catch (e)
	{}
}

function _exudTradepost_MakeTableData()
{
	var out = "";

	try 
	{
		var k = Object.keys(_exudTradepost_Settings.Trades);
		k.forEach(function(ki){
			var trade = _exudTradepost_Settings.Trades[ki];
			out += createTableRow([
					[3 , getText('Send', '_exudTradepostLang')],
					[4, trade.SendAmount + " (" + (trade.Posten ? trade.SendAmount * trade.Posten : trade.SendAmount) + ")"],
					[4 , loca.GetText("RES", trade.SendResource)]
					], false)
			out += createTableRow([
					[3 , getText('Receive', '_exudTradepostLang')],
					[4, trade.ReceiveAmount + " (" + (trade.Posten ? trade.ReceiveAmount * trade.Posten : trade.ReceiveAmount) + ")"],
					[4 , loca.GetText("RES", trade.ReceiveResource)]
					], false)
			out += createTableRow([
				[3 , getText('Posten', '_exudTradepostLang')],
				[4 , trade.Posten || 1],
				[4, ""],
				[1, ""]
				], false)
			+	createTableRow([
				[2, ""],
				[3, ""],
				[4, $('<button>').attr({ "class": "btn btn-primary exudTradepostSendItem2", 'value': trade.ID }).text(getText('BtnSend', '_exudTradepostLang'))],
				[2, ""],
				[1, $('<button>', { 'type': 'button', 'class': 'close exudTradepostDelItem', 'value': trade.ID }).html($('<span style="color: red;font-size: 35px;">').html('&times;'))]
				], false)
			out += "<hr/>";
			
		});
	}
	catch (e)
	{
	}
	return out;
}

