function CheckAutoSzenario()
{
	if(user_fast_shortcut_settings.MemUeberwachung && user_fast_shortcut_settings_AutoSzenario.Runde != 0)
	{
		ToolingMenuUpdate(false);
		ToolingMenuUpdateSzenaMenu(false);
		ToolingMenuUpdateSzenaStoppen(true);
		ToolingMenuUpdateSzenaStarten(false);
		ToolingMenuUpdateMainMenu(false);
		setTimeout(function() {
			showGameAlert(getText('CheckRound', 'SemiAutoATMenuLang'));
		}, 130000);
		setTimeout(function() {
			RundenanzahlCounterSzenario = user_fast_shortcut_settings_AutoSzenario.Runde;
			SzenarioStart();
		}, 3 * 60 * 1000);
	}
}

function AutoSzenariosave()
{
	settings.settings["FastShortcutAutoSzenario"] = {};
	settings.store(user_fast_shortcut_settings_AutoSzenario, "FastShortcutAutoSzenario");
}

function FastShortcutSzenarioHandler(event)
{
	if(game.gi.isOnHomzone() == false) {
		game.showAlert(getText('not_home'));
		return;
	}
	FastDataLoad();
	$('div[role="dialog"]:not(#FastShortcutSZENARIO):visible').modal('hide');
	$('#FastShortcutSZENARIO').remove();
	
	var w = new Modal('FastShortcutSZENARIO', utils.getImageTag('icon_dice.png', '45px') + ' ' + getText('Title', 'uSZENARIOSYSTEMLang') +"<div style='text-align: center; font-size: smaller;'>"+"</div>");
	var createButton = function(id, text) {
		return $('<button>', { 
			'style': 'cursor: pointer;text-decoration:none;color:#000;height: 20px;padding: 0px;',
			'class': 'btn form-control',
			'id': id
		}).text(text)
	}
	w.size = '';
	w.create();
	var html = '<div class="container-fluid" style="user-select: all;">';
	html += utils.createTableRow([[6, loca.GetText("LAB", "Name")], [6, loca.GetText("LAB", "AvatarCurrentSelection")]], true);
	
		
	var SzenarioRundenanzahl = $('<select>', { 'class': 'form-control SzenarioRundenanzahl' });
	for (var i = 1; i <= 100; i++) {
		SzenarioRundenanzahl.append($('<option>', { 'value': i }).text(i));
	}
	
	var options = [
	$('<option>', { 'value': 'BuffAdventures_twins_easy' }).text(loca.GetText("ADN", "BuffAdventures_twins_easy")),
	$('<option>', { 'value': 'BuffAdventures_Storm_Recovery' }).text(loca.GetText("ADN", "BuffAdventures_Storm_Recovery")),
	$('<option>', { 'value': 'BuffAdventures_heartOfTheWood_medium' }).text(loca.GetText("ADN", "BuffAdventures_heartOfTheWood_medium")),
	$('<option>', { 'value': 'BuffAdventures_safeTheTowns_easy' }).text(loca.GetText("ADN", "BuffAdventures_safeTheTowns_easy")),
	$('<option>', { 'value': 'BuffAdventures_Riches_of_the_Mountain' }).text(loca.GetText("ADN", "BuffAdventures_Riches_of_the_Mountain"))
	];
	
	options.sort(function (a, b) {
    var textA = a.text().toUpperCase();
    var textB = b.text().toUpperCase();
    return (textA < textB) ? -1 : (textA > textB) ? 1 : 0;
	});
	
	var SzenarioAuswahl = $('<select>', { 'class': 'form-control SzenarioAuswahl' });
	SzenarioAuswahl.append(options);
	
	
	html += utils.createTableRow([[11, loca.GetText("BUI", "ProvisionHouse2") + getText('Rari', 'uSZENARIOSYSTEMLang')], [1, createSwitch('Rari', user_fast_shortcut_settings_SZENARIO.Rari)]]);
	html += utils.createTableRow([[6, getText('Rounds', 'uSZENARIOSYSTEMLang')], [6, SzenarioRundenanzahl.prop('outerHTML')]]);
	html += utils.createTableRow([[6, getText('Choice', 'uSZENARIOSYSTEMLang')], [6, SzenarioAuswahl.prop('outerHTML')]]);
	html += utils.createTableRow([[9, '<br>']]);
	html += '<div class="row"><div class="col-12"><div id="RessourcenTabelle" style="margin-top:10px;"></div></div></div>';

	
	w.Body().html(html + '</div>');
	w.withBody('div.row').addClass('nohide');
	
	function RessiCheckCompleteRounds() {
        var EnoughRessi = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
        var itemCosts = FastData.FastSenariosResources[user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl];
        var insufficientResources = {};

        for (var itemcost in itemCosts) {
            var requiredAmount = itemCosts[itemcost].amount * user_fast_shortcut_settings_SZENARIO.SzenarioRundenanzahl;
            if (!EnoughRessi.HasPlayerResource(itemcost, requiredAmount)) {
                insufficientResources[itemcost] = true;
            }
        }
        return insufficientResources;
    }
	
	function RessiCheckCompleteRoundsRealRess() {
        var EnoughRessi = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
        var itemCosts = FastData.FastSenariosResources[user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl];
		var RealResources = {};
		
		for (var itemcost in itemCosts) {
			if(itemcost == "Population")
			{
				var populationReal = swmmo.application.mGameInterface.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer).GetFree();
				RealResources[itemcost] = populationReal;
			}
			else
			{
				RealResources[itemcost] = EnoughRessi.GetResourceAmount(itemcost);
			}
        }
        return RealResources;
    }
	
	function ATCheckCompleteRounds() {
		var gamingstarbuffATCheck = game.gi.mCurrentPlayer.getBuffsSortedForStarMenu();
		var ATAmount = 0;
				gamingstarbuffATCheck.forEach(function(data){						
					if(user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl == data.GetResourceName_string()) 
					{
						ATAmount = data.GetAmount();

					}
				});
				return ATAmount;
	}
	
	function updateRessourcenAnzeige() {
        var selectedRunden = user_fast_shortcut_settings_SZENARIO.SzenarioRundenanzahl;
        var itemCosts = FastData.FastSenariosResources[user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl];

        if (!itemCosts || typeof itemCosts !== 'object') {
            return;
        }

        var insufficient = RessiCheckCompleteRounds();
		var RealResources = RessiCheckCompleteRoundsRealRess();
		var RealATAmount = ATCheckCompleteRounds();

		var styleAT = RealATAmount < user_fast_shortcut_settings_SZENARIO.SzenarioRundenanzahl ? 'color: red; font-weight: bold;' : 'color: white;';
        var tabelle = '<b style="color:white;">' + getText('RequiredResources', 'uSZENARIOSYSTEMLang') + '</b><br><br>';
		tabelle += '<b style="' + styleAT + '">' + loca.GetText("ADN", user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl) + ": " + RealATAmount + " (" + loca.GetText("LAB", "StarMenu") + ")" + '</b>';
        tabelle += '<table class="table table-bordered table-sm" style="margin-top:5px; color: white; font-size: inherit;">';
        tabelle += '<thead><tr><th>' + loca.GetText("LAB", "Resources") + '</th><th>' + loca.GetText("LAB", "Amount") + " (" + loca.GetText("LAB", "InStock") + ")" + '</th></tr></thead><tbody>';

        for (var itemcost in itemCosts) {
            var amount = itemCosts[itemcost].amount * selectedRunden;
            var style = insufficient[itemcost] ? 'color: red; font-weight: bold;' : 'color: white;';
            tabelle += '<tr><td>' + loca.GetText("RES", itemcost) + '</td><td style="' + style + '">' + amount.toLocaleString() + " (" + RealResources[itemcost].toLocaleString() + ")" + '</td></tr>';
        }

        tabelle += '</tbody></table>';
        w.withBody('#RessourcenTabelle').html(tabelle);
    }


	w.withBody('.SzenarioRundenanzahl').val(user_fast_shortcut_settings_SZENARIO.SzenarioRundenanzahl).change(function(e) { user_fast_shortcut_settings_SZENARIO.SzenarioRundenanzahl = $(e.target).val(); updateRessourcenAnzeige();});
	w.withBody('.SzenarioAuswahl').val(user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl).change(function(e) { user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl = $(e.target).val(); updateRessourcenAnzeige();});
	
	w.withBody('#Rari').change(function(e) {
		user_fast_shortcut_settings_SZENARIO.Rari = $(e.target).is(':checked');
	});
	
	if(game.gi.isOnHomzone())
	{
		w.Footer().prepend($("<button>").attr({'class':"btn btn-primary pull-left"}).text(loca.GetText("LAB","Save")).click(function(){


		game.showAlert(getText('SettingsSave', 'SemiAutoATMenuLang'));
		settings.settings["FastShortcutSZENARIO"] = {};
		settings.store(user_fast_shortcut_settings_SZENARIO, "FastShortcutSZENARIO");
		//reloadScripts();
		setTimeout(function () {$.extend(user_fast_shortcut_settings_SZENARIO, settings.read(null, "FastShortcutSZENARIO"));}, 2000);
		w.hide();
		}));
	}
	w.show();
	updateRessourcenAnzeige();
}

