function ProvRariGrid()
{
	try{
		game.zone.mStreetDataMap.GetBuildings_vector().forEach(function(item){
			if (item === null) { return; }
			if(item.GetBuildingName_string() == "ProvisionHouse")
			{
				ProvGridInt = item.GetGrid();
				
			}
			if(item.GetBuildingName_string() == "ProvisionHouse2")
			{
				RariGridInt = item.GetGrid();
				
			}
		});
	}
	catch(e)
	{
		
	}
}

