function RessiCheckBeforeStart()
{
	var EnoughRessi = game.gi.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer);
	var itemCosts = FastData.FastSenariosResources[user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl];

	for (var itemcost in itemCosts) {
		var requiredAmount = itemCosts[itemcost].amount;
		if(itemcost == "Population")
		{
			var populationReal = swmmo.application.mGameInterface.mCurrentPlayerZone.GetResources(game.gi.mCurrentPlayer).GetFree();
			requiredAmount = populationReal;
		}
		if (EnoughRessi.HasPlayerResource(itemcost, requiredAmount)) {
			if (user_fast_shortcut_settings.debugAT) {
			debug("⚠️ Genug Ressourcen für aktuelle Runde: " + loca.GetText("RES", itemcost) + " " + requiredAmount);}
		} else {
			if (user_fast_shortcut_settings.debugAT) {
			debug("⚠️ Nicht genug Ressourcen für aktuelle Runde: " + loca.GetText("RES", itemcost) + " " + requiredAmount);}
			game.showAlert("Nicht genug Ressourcen für aktuelle Runde: " + loca.GetText("RES", itemcost) + " " + requiredAmount);
			return false;
		}
	}
	return true;
}

const StepHandlers = {
    StartSenario: function (_, scenarioName) {
		if (user_fast_shortcut_settings.debugAT) {
        debug("🟢 Starte Szenario... " + loca.GetText("ADN", scenarioName));}
		game.showAlert("Starte Szenario... " + loca.GetText("ADN", scenarioName));
        SenarioStartBuffen(scenarioName);
    },
    ProduceItem: function (data, scenarioName) {
        waitForHomeZoneAndRunSenarioProdden(data, scenarioName);
    },
    VisitSenario: function (_, scenarioName) {
		if (user_fast_shortcut_settings.debugAT) {
        debug("🚪 Besuche Szenario... " + loca.GetText("ADN", scenarioName));}
		game.showAlert("Besuche Szenario... " + loca.GetText("ADN", scenarioName));
		SenarioVisit(scenarioName);
    },
    CollectPickups: function (_, scenarioName) {
		SenarioCollect(scenarioName);
    },
    ReturnHome: function (_, scenarioName) {
		SenarioReturn(scenarioName);
    },
    ApplyBuff: function (data, scenarioName) {
		waitForAdventureZoneAndApplyBuff(data, scenarioName);
    }
};

function runScenario(scenario) {
    var steps = scenario.steps;
    var index = 0;
    var defaultDelay = 2000;


    function nextStep() {
		if(stopScenario)
		{
			if (user_fast_shortcut_settings.debugAT) {
			debug("✅ Szenario gestoppt! : " + scenario.name);}
			game.showAlert("Szenario gestoppt! : " + scenario.name);
			SzenarioStoppen();
			return;
		}
			
        if (index >= steps.length) {
			if (user_fast_shortcut_settings.debugAT) {
            debug("✅ Szenario abgeschlossen: " + scenario.name);}
			game.showAlert("Szenario abgeschlossen: " + scenario.name);
            return;
        }

        var step = steps[index];
        var actionName = step.name;
        var data = step.data;
		WasCollectedperRound = false;
		
		if (user_fast_shortcut_settings.debugAT) {
        debug("➡️ Schritt " + (index + 1) + ": " + actionName);}
		//game.showAlert("Schritt " + (index + 1) + ": " + actionName);
		
		if (actionName === "ProduceItem") {
			// Produktion starten
			var ProddenRetryTimeout;
			var hasRetriedProdden = false;
			StepHandlers.ProduceItem(data, scenario.name);
			var Fixedamountentry = FastData.adventureItems[scenario.name][data];
			var Fixedamount = Fixedamountentry.length;
			if ($.isArray(Fixedamountentry[0])) {
				Fixedamount = Fixedamountentry[1];
			}
			// Warte bis Items produziert sind
			index++;
			ProddenRetryTimeout = setTimeout(function () {
					if(stopScenario)
					{
						if (user_fast_shortcut_settings.debugAT) {
						debug("✅ Szenario gestoppt! : " + scenario.name);}
						game.showAlert("Szenario gestoppt! : " + scenario.name);
						SzenarioStoppen();
						return;
					}
					if (!WasProddedEnoughRess && !hasRetriedProdden) {
						if (user_fast_shortcut_settings.debugAT) {
						debug("⚠️ Nicht genug Ressourcen - Stoppe Szenario!");}
						game.showAlert("Nicht genug Ressourcen (Retry Versuch) - Stoppe Szenario!");
						game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
						setTimeout(function () {
							SzenarioStoppen();
						}, 5000);
							
						hasRetriedProdden = true;
					}
				}, 60000);
			var checkProduktion = function () {
				if(stopScenario)
				{
					if (user_fast_shortcut_settings.debugAT) {
					debug("✅ Szenario gestoppt! : " + scenario.name);}
					game.showAlert("Szenario gestoppt! : " + scenario.name);
					SzenarioStoppen();
					return;
				}
				if (user_fast_shortcut_settings.debugAT) {
				debug("✨ FixedAmount: " + Fixedamount);}
				getBuffAvailableCountSenario(data);
				var RealAmount = buffsAvailableSenario[data].count;
				if (user_fast_shortcut_settings.debugAT) {
				debug("✨ RealAmount: " + RealAmount);}
				if (RealAmount === Fixedamount) {
					if (user_fast_shortcut_settings.debugAT) {
					debug("✅ Produktion fertig, fahre fort.");}
					game.showAlert("Produktion fertig, fahre fort.");
					clearTimeout(ProddenRetryTimeout);
					WasProddedperRound = true;
					setTimeout(nextStep, 5000);
				} else {
					if(!stopScenario)
					{
						setTimeout(checkProduktion, 5000);
					}
				}
			};
			checkProduktion();
			return;
		}

        if (actionName === "Wait") {
            var delay = parseInt(data, 10) || defaultDelay;
			if (user_fast_shortcut_settings.debugAT) {
            debug("⏳ Warte " + delay + "ms...");}
			game.showAlert("Warte " + delay + "ms...");
            index++;
			WasProddedperRound = false;
			if(stopScenario)
			{
				if (user_fast_shortcut_settings.debugAT) {
				debug("✅ Szenario gestoppt! : " + scenario.name);}
				game.showAlert("Szenario gestoppt! : " + scenario.name);
				SzenarioStoppen();
				return;
			}
            setTimeout(nextStep, delay);
            return;
        }
		
		if (actionName === "CollectPickups") {
			index++;
			var collectRetryTimeout;
			var hasRetried = false;
			
			var checkCollect = function () {
				if(stopScenario)
				{
					if (user_fast_shortcut_settings.debugAT) {
					debug("✅ Szenario gestoppt! : " + scenario.name);}
					game.showAlert("Szenario gestoppt! : " + scenario.name);
					SzenarioStoppen();
					return;
				}
				if (SzenarioCollectReady) {
					if (user_fast_shortcut_settings.debugAT) {
					debug("📦 Sammle Items ein...");}
					game.showAlert("Sammle Items ein...");
					StepHandlers.CollectPickups(data, scenario.name);
					SzenarioCollectReady = false;
					WasCollectedperRound = true;

					collectRetryTimeout = setTimeout(function () {
						if (!SzenarioCollectFinished && !hasRetried) {
							if (user_fast_shortcut_settings.debugAT) {
							debug("⚠️ Sammeln Lag erkannt, versuche erneut.");}
							game.showAlert("Sammeln Lag erkannt, versuche erneut.");
							game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
							setTimeout(function () {
								if (user_fast_shortcut_settings.debugAT) {
								debug("📦 Sammle Items ein...");}
								game.showAlert("Sammle Items ein...");
								StepHandlers.CollectPickups(data, scenario.name);
							}, 5000);
							
							hasRetried = true;
						}
					}, 60000);
				}

				if (SzenarioCollectFinished) {
					clearTimeout(collectRetryTimeout);
					if (user_fast_shortcut_settings.debugAT) {
					debug("✅ Sammeln fertig, fahre fort.");}
					game.showAlert("Sammeln fertig, fahre fort.");
					WasProddedperRound = false;
					SzenarioCollectFinished = false;
					setTimeout(nextStep, 5000);
				} else {
					if(!stopScenario)
					{
						setTimeout(checkCollect, 5000);
					}
				}
			};
			checkCollect();
			return;
		}

        var handler = StepHandlers[actionName];
        if (typeof handler === "function") {
            handler(data, scenario.name);
        } else {
			if (user_fast_shortcut_settings.debugAT) {
            debug("⚠️ Kein Handler für Schritt: " + actionName);}
			game.showAlert("Kein Handler für Schritt: " + actionName);
        }

        index++;
		WasProddedperRound = false;
        setTimeout(nextStep, defaultDelay);
    }

    nextStep();
}

function SenarioStartBuffen(scenarioName) {
    var BuffGefunden = false;
    var SenarionochAktiv;
	
	if(stopScenario)
	{
		return;
	}
    
    if (game.gi.isOnHomzone())
	{
        try{menu.nativeMenu.getItemByName("DebugMethoden").label = "ATStartBuffen() - Senario Buffen";}catch(e){}
        var MyBuffID;
        var buffVector = [];

        try {
            buffVector = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();
            buffVector.forEach(function (data) {
                if (data.GetResourceName_string() === scenarioName && data.GetBuffDefinition().GetName_string() === "Adventure") {
                    BuffGefunden = true;
                    MyBuffID = data.GetUniqueId();
                }
            });

            try {
                SenarionochAktiv = false;
                var AdvManager = swmmo.getDefinitionByName("com.bluebyte.tso.adventure.logic::AdventureManager").getInstance();
                var Adventures = AdvManager.getAdventures();

                if (Adventures[0] && game.player.GetPlayerId() === Adventures[0].ownerPlayerID) {
                    SenarionochAktiv = true;
                } else if (Adventures[1] && game.player.GetPlayerId() === Adventures[1].ownerPlayerID) {
                    SenarionochAktiv = true;
                }
            } catch (error) {
                SenarionochAktiv = true;
            }

            if (BuffGefunden && !SenarionochAktiv) {
                game.showAlert(getText('Buffing', 'SemiAutoATMenuLang') + scenarioName + " | ID: " + MyBuffID);
                game.gi.SendServerAction(61, 0, 0, 0, MyBuffID);
            } else {
                game.showAlert(getText('ATNotFound', 'SemiAutoATMenuLang'));
				stopScenario = true;
            }
        } catch (e) {stopScenario = true;}
    }
}

function waitForHomeZoneAndRunSenarioProdden(data, scenarioName) {
    if (!stopScenario && game.gi.isOnHomzone()) {
		if(!WasProddedperRound)
		{
			if (user_fast_shortcut_settings.debugAT) {
			debug("⚠️ Refresh Prodden");}
			//game.showAlert("Refresh Prodden");
			game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
		}
		setTimeout(function () {
			SenarioProdden(data, scenarioName);
		}, 10000);
    } else {
        setTimeout(function() {
            waitForHomeZoneAndRunSenarioProdden(data, scenarioName);
        }, 5000);
    }
}

