function SenarioVisit(scenarioName) {
    if(stopScenario)
	{
		return;
	}
	
	try {
			try{menu.nativeMenu.getItemByName("DebugMethoden").label = "SenarioVisit()";}catch(e){}
			var AdvManager = swmmo.getDefinitionByName("com.bluebyte.tso.adventure.logic::AdventureManager").getInstance();
			var Adventures = AdvManager.getAdventures();
			if (game.gi.isOnHomzone()) {
					if(Adventures[0] !== undefined && game.player.GetPlayerId() == Adventures[0].ownerPlayerID)
					{
						game.gi.visitZone(Adventures[0].zoneID);
						LaggySZENARIOID = Adventures[0].zoneID;
					}
					else if(Adventures[1] !== undefined && game.player.GetPlayerId() == Adventures[1].ownerPlayerID)
					{
						game.gi.visitZone(Adventures[1].zoneID);
						LaggySZENARIOID = Adventures[1].zoneID;
					}
					else if(Adventures[0] !== undefined && game.player.GetPlayerId() != Adventures[0].ownerPlayerID)
					{
						game.gi.visitZone(Adventures[0].zoneID);
						LaggySZENARIOID = Adventures[0].zoneID;
					}
					else if(Adventures[1] !== undefined && game.player.GetPlayerId() != Adventures[1].ownerPlayerID)
					{
						game.gi.visitZone(Adventures[1].zoneID);
						LaggySZENARIOID = Adventures[1].zoneID;
					}
					else
					{
						showGameAlert(getText('NoActiveAT', 'SemiAutoATMenuLang'));
						stopScenario = true;
					}
					
					waitForAdventureZoneQuest(scenarioName);	
			}
			else
			{
				showGameAlert(getText('NotHome', 'SemiAutoATMenuLang'));
			}		
		} catch (e) {}
}

