function GetQuestSenario(scenarioName) {
	var LastQuest = false;
	var CounterQuestCheck = 0;
	game.gi.mQuestClientCallbacks.JustRefresh();
	globalFlash.gui.mQuestBook.Show();
	globalFlash.gui.mQuestBook.Hide();
    function checkQuest() {
		if(!game.gi.mCurrentPlayer.mIsAdventureZone || stopScenario)
		{
			return;
		}
		
		try{menu.nativeMenu.getItemByName("DebugMethoden").label = "GetQuestSenario()";}catch(e){}
		
		try{
			if (game.gi.mCurrentPlayer.mIsAdventureZone && game.gi.mNewQuestManager.GetQuestPool().IsAnyQuestsActive()) {
				game.gi.mQuestClientCallbacks.JustRefresh();
				$.each(game.gi.mNewQuestManager.GetQuestPool().GetQuest_vector(), function (i, item) {
					if (item == null || LastQuest)
					{
						return;
					}						
					
					globalFlash.gui.mQuestBook.SetPreselectedQuest(item);

					var questmode = item.GetQuestMode().toString();
					var questname = item.getQuestName_string();			

					if (questmode == "2")
					{
						globalFlash.gui.mQuestBook.Show();
						game.gi.mQuestClientCallbacks.QuestOkButtonPressedFromGui(item);
						globalFlash.gui.mQuestBook.Hide();
					}	
					
					if (!item.isFinished() && questname == "CollectAllEventCollectibles" && item.GetQuestMode().toString() != "12" && !WasCollectedperRound) {
						setTimeout(function () {
							SzenarioCollectReady = true;
						}, 5000);	
					}
					
					//game.showAlert("Quest: " + questname + "(Mode:"+ questmode +")" + " | " + "isFinished:"+item.isFinished());
					
					if (item.isFinished()) {
						game.showAlert(getText('QuestFinish', 'SemiAutoATMenuLang') + questname + "(Mode:"+ questmode +")");
						globalFlash.gui.mQuestBook.Show();
						game.gi.mNewQuestManager.RewardOkButtonPressedFromGui(item);
						globalFlash.gui.mQuestBook.Hide();
						if (questname == "CollectAllEventCollectibles") {
							SzenarioCollectFinished = true;
						}
						if (item.GetQuestDefinition().specialType_string.toString() == "lastQuest") {
							LastQuest = true;
						}
						if (item.GetQuestDefinition().specialType_string.toString() == "firstQuestlastQuest") {
							LastQuest = true;
						}
					}
				});
								
				if(CounterQuestCheck == 3 && !LastQuest)
				{
					game.gi.mQuestClientCallbacks.JustRefresh();
					globalFlash.gui.mQuestBook.Show();
					globalFlash.gui.mQuestBook.Hide();
					CounterQuestCheck = 0;
				}
				CounterQuestCheck++;
			}
		}
		catch(e){game.showAlert(getText('AutoATQuestError', 'SemiAutoATMenuLang'));game.gi.mQuestClientCallbacks.JustRefresh();globalFlash.gui.mQuestBook.Show();globalFlash.gui.mQuestBook.Hide();}

        if (game.gi.mCurrentPlayer.mIsAdventureZone && LastQuest && !game.gi.mPacketLost) {
            game.showAlert(getText('LastQuestAuto', 'SemiAutoATMenuLang'));
            LastQuest = false;
            setTimeout(function () {
				if (user_fast_shortcut_settings.debugAT) {
				debug("🏠 Zurück nach Hause...");}
				game.showAlert("Zurück nach Hause...");
                SenarioReturn(scenarioName);
				RundenanzahlCounterSzenario++;
				setTimeout(function() {
						try{
							RefreshGUIBUI();
							game.gi.mClientMessages.SendMessagetoServer(1037, game.gi.mCurrentViewedZoneID, null);
							var AdvManager = swmmo.getDefinitionByName("com.bluebyte.tso.adventure.logic::AdventureManager").getInstance();
							AdvManager.removeAdventure(LaggySZENARIOID);
							/* showGameAlert('Laggy AT entfernt!'); */
							}catch(e){showGameAlert('Konnte Laggy Szenario nicht entfernen!');}
					},10000);
				if(RundenanzahlCounterSzenario < user_fast_shortcut_settings_SZENARIO.SzenarioRundenanzahl)
				{
					setTimeout(function() {
						if(user_fast_shortcut_settings.MemUeberwachung)
						{
							if(MemTriggerClientRestart())
							{
								showGameAlert(getText('MemInAT', 'SemiAutoATMenuLang') + humanMemorySize(air.System.privateMemory, 1) + getText('MemInAT2', 'SemiAutoATMenuLang'));
								try{menu.nativeMenu.getItemByName("AutoATRundenanzahl").label = "AutoModus - Speichergrenze erreicht, Neustart demnächst!";}catch(e){}
								user_fast_shortcut_settings_AutoSzenario.Runde = RundenanzahlCounterSzenario;
								AutoSzenariosave();
								ToolingMenuUpdateSzenaMenu(false);
								ToolingMenuUpdateSzenaStoppen(false);
								ToolingMenuUpdateSzenaStarten(false);
								ToolingMenuUpdate(false);
								ToolingMenuUpdateMainMenu(false);
							}
							else
							{
								if(game.gi.isOnHomzone() && !stopScenario)
								{
									SzenarioStart();	
								}
							}
						}
						else
						{
							if(game.gi.isOnHomzone() && !stopScenario)
							{
								SzenarioStart();	
							}
						}
					},30000);
				}
				else
				{
					if(RundenanzahlCounterSzenario === 1338)
					{
						try{menu.nativeMenu.getItemByName("AutoATRundenanzahl").label = "Szenario Runden : " + RealRundenanzahlCounterSzenario + " (Fertig, gestoppt nach Runde)";}catch(e){}
					}
					else
					{
						try{menu.nativeMenu.getItemByName("AutoATRundenanzahl").label = "Szenario Runden : " + RundenanzahlCounterSzenario + " (Fertig)";}catch(e){}
					}
					
					RundenanzahlCounterSzenario = 0;
					RealRundenanzahlCounterSzenario = 0;
					user_fast_shortcut_settings_AutoSzenario.Runde = 0;
					AutoSzenariosave();
					stopScenario = true;	
					ToolingMenuUpdate(true);
					ToolingMenuUpdateSzenaMenu(true);
					ToolingMenuUpdateSzenaStoppen(false);
					ToolingMenuUpdateSzenaStarten(true);	
					ToolingMenuUpdateMainMenu(true);					
				}
            }, 20000);
            return;
        }

        questTimeoutSenarios = setTimeout(function () {
            if (game.gi.mCurrentPlayer.mIsAdventureZone) {
				checkQuest();
			}
        }, 15000);
    }
	setTimeout(checkQuest, 15000);
}

function waitForAdventureZoneAndApplyBuff(data, scenarioName) {
    if (game.gi.mCurrentPlayer.mIsAdventureZone) {
		setTimeout(function () {
			if (user_fast_shortcut_settings.debugAT) {
			debug("✨ Buff angewendet: " + loca.GetText("RES", data));}
			game.showAlert("Buff angewendet: " + loca.GetText("RES", data));
			ApplyBuffSenario(data, scenarioName);
		}, 10000);     
    } else {
        setTimeout(function() {
            waitForAdventureZoneAndApplyBuff(data, scenarioName);
        }, 5000);
    }
}

function ApplyBuffSenario(data, scenarioName) {

	try{menu.nativeMenu.getItemByName("DebugMethoden").label = "ApplyBuffSenario()";}catch(e){}
    var buffAdventureName = scenarioName;

    var buffs = FastData.adventureItems[buffAdventureName];
    if (!buffs) return;
	
    var buffRecordFilteredSenario = {};
    var buffRecordFiltered2Senario = [];
	var MaxStacksBuff = false;

    for (var buffName in buffs) {
        var grids = buffs[buffName];
		grids = $.isArray(grids[0]) ? grids[0] : grids;
		getBuffAvailableCountSenario(buffName);
		var BuffID = buffsAvailableSenario[buffName].id;
        buffRecordFilteredSenario[buffName] = {
            id: BuffID,
            count: buffsAvailableSenario[buffName].count
        };
        for (var i = 0; i < grids.length; i++) {
            buffRecordFiltered2Senario.push({
                buffName: buffName,
                buiGrid: grids[i]
            });
        }
		if ($.isArray(grids[0])) {
			MaxStacksBuff = true;
		}
    }

    var xbuffDoJob2Senario = new TimedQueue(1000);

		for (var j = 0; j < buffRecordFiltered2Senario.length; j++) {
			(function(item) {
				var buffData = buffRecordFilteredSenario[item.buffName];
				if (buffData && buffData.count > 0 && item.buffName === data) {

					buffData.count--;

					xbuffDoJob2Senario.add(function() {
						if (game.gi.mCurrentPlayer.mIsAdventureZone && !stopScenario) {
							if (user_fast_shortcut_settings.debugAT) {
							debug("BuffID: " + buffData.id + " Grid: " + item.buiGrid);}
							game.showAlert("BuffID: " + buffData.id + " Grid: " + item.buiGrid);
							if(MaxStacksBuff)
							{
								sendBuffPacketSzenario(buffData.id, item.buiGrid, 1);
							}
							else
							{
								sendBuffPacketSzenario(buffData.id, item.buiGrid, 0);
							}
							
						}
					});
				}
			})(buffRecordFiltered2Senario[j]);
		}

		xbuffDoJob2Senario.run();
}

function sendBuffPacketSzenario(buffId, grid, amount)
{
	try{
		var uniqueIdArr = buffId.split("_"),
			uniqueID = game.def("Communication.VO::dUniqueID").Create(uniqueIdArr[0], uniqueIdArr[1]);
		game.gi.SendServerAction(61, 0, grid, amount, uniqueID);
	} catch (ex) {
		alert(ex);
	}
}

function getBuffAvailableCountSenario(buffName)
{
	var buffVectorGetName = CHAOS_CURRENT_PLAYER().getAvailableBuffs_vector();
	
	buffsAvailableSenario[buffName] = {count: 0, id: ''};
	buffVectorGetName.every(function(item){
		
		if(item.GetBuffDefinition().GetName_string() == buffName) {
			buffsAvailableSenario[buffName].count = item.GetAmount();
			buffsAvailableSenario[buffName].id = item.GetUniqueId().uniqueID1 + '_' + item.GetUniqueId().uniqueID2;
			return false;
		}
		return true;
	});
	return buffsAvailableSenario[buffName].id;
}

function SzenarioStoppen()
{
	stopScenario = true;
	ToolingMenuUpdate(true);
	ToolingMenuUpdateSzenaMenu(true);
	ToolingMenuUpdateSzenaStoppen(false);
	ToolingMenuUpdateSzenaStarten(true);
	ToolingMenuUpdateMainMenu(true);
	game.showAlert("Szenario wird gestoppt!");
	RundenanzahlCounterSzenario = 0;
	user_fast_shortcut_settings_AutoSzenario.Runde = 0;
	AutoSzenariosave();
	WasProddedperRound = false;
	SzenarioCollectReady = false;
	WasProddedEnoughRess = true;
}

function SzenarioStart() {

	FastDataLoad();
	if(!RessiCheckBeforeStart())
	{
		SzenarioStoppen();
		return;
	}
	stopScenario = false;
	ToolingMenuUpdate(false);
	ToolingMenuUpdateSzenaMenu(false);
	ToolingMenuUpdateSzenaStoppen(true);
	ToolingMenuUpdateSzenaStarten(false);
	ToolingMenuUpdateMainMenu(false);
	WasProddedperRound = false;
	SzenarioCollectReady = false;
	WasProddedEnoughRess = true;
	function checkSzenarioStart() {
		if(!game.gi.isOnHomzone())
		{
			return;
		}
		user_fast_shortcut_settings_AutoSzenario.Runde = 0;
		AutoSzenariosave();
		
		if (game.gi.isOnHomzone() == true && RundenanzahlCounterSzenario < user_fast_shortcut_settings_SZENARIO.SzenarioRundenanzahl) {
			try{menu.nativeMenu.getItemByName("DebugMethoden").label = "SzenarioStart() - Auf Heimatinsel";}catch(e){}
			
			var RundeAktuell = RundenanzahlCounterSzenario + 1;
			try{menu.nativeMenu.getItemByName("AutoATRundenanzahl").label = "Szenario Runde : " + RundeAktuell;}catch(e){}
			RealRundenanzahlCounterSzenario = RundeAktuell;
			
			setTimeout(function () {
				if(!stopScenario)
				{
					runScenario(FastData.FastSenarios[user_fast_shortcut_settings_SZENARIO.SzenarioAuswahl]);  
				}				
			}, 10000);
			return;
		}
		setTimeout(checkSzenarioStart, 10000);
	}

	setTimeout(checkSzenarioStart, 10000);
}


